/**
 * Plugin Name: ToPersia Core Functions
 * Description: توابع اختصاصی سایت ToPersia — اسلاگ لاتین از نام انگلیسیِ کیوریت‌شده، شناسهٔ یکتای موجودیت، ریدایرکت موجودیت‌های گراف‌فقط (G4)، منطق مسیرهای گردشگری (P9)، قاعدهٔ سراسری وضعیت ردیف، یکپارچگی Rank Math، پنهان‌سازی مسیر نصب، کاهش اثر انگشت، و پنل تنظیمات و تشخیص. موتور دادهٔ ساختاریافته در افزونهٔ جداگانهٔ topersia-schema است.
 * Version: 4.10.0
 * Requires PHP: 7.4
 * Author: ToPersia
 * Text Domain: topersia-core
 *
 * ══════════════════════════════════════════════════════════════════════════
 *  فهرست بخش‌ها
 * ══════════════════════════════════════════════════════════════════════════
 *  ۰ — پیکربندی                    تنظیمات، ثابت‌ها، و ترتیب تقدم آن‌ها
 *  ۱ — ابزارهای مشترک              توابعی که چند بخش از آن‌ها استفاده می‌کنند
 *  ۲ — اسلاگ لاتین                 از نام انگلیسیِ کیوریت‌شده
 *  ۳ — شناسهٔ یکتای موجودیت         entity_uid پایدار و میان‌زبانی
 *  ۴ — هم‌سان‌سازی اسلاگ ترجمه‌ها     تا هر سه زبان یک اسلاگ بگیرند
 *  ۵ — G4 گراف‌فقط                  ریدایرکت ۳۰۱ و حذف از سایت‌مپ
 *  ۶ — P9 مسیرهای گردشگری           ترتیب توقف‌ها و روابط مشتق‌شده
 * ۶-ب — یال‌های مشتق‌شده              از زیرفیلد ریپیتر — P5-D114
 *  ۷ — استخراج خودکار استان         با فلگ کنترل می‌شود
 *  ۸ — یکپارچگی Rank Math           عنوان، توضیح متا، و تصویر اشتراک‌گذاری
 * ۸-ب — بستن جعبهٔ Custom Fields    محافظت از ریپیترها و entity_uid — F-19
 * ۸-ج — محافظ حذف ردیف Repeater     تبدیل حذف به بازنشستگی — P5-D121
 *  ۹ — (منتقل شد)                   موتور شِما → افزونهٔ topersia-schema
 * ۱۰ — پاک‌سازی head                حذف تگ‌های بی‌مصرف
 * ۱۱ — پنهان‌سازی مسیر نصب         حذف /geo از تمام خروجی عمومی
 * ۱۲ — کاهش اثر انگشت              کم‌کردن نویز اسکن خودکار
 * ۱۳ — پنل مدیریت                  تنظیمات، تشخیص خودکار، و راهنما
 * ۱۴ — واردکنندهٔ اسکلت جغرافیایی  DATA-P9-001 — کشور تا شهر با یال رابطه
 * ۱۵ — سیستم ثبت رویداد            جدول اختصاصی، سطح، کانال، شناسهٔ درخواست
 *
 * شمارهٔ بخش‌ها عمداً دست‌نخورده مانده و جای بخش ۹ خالی نگه داشته شده، تا
 * ارجاع‌های موجود در اسناد پروژه معتبر بمانند.
 *
 * ══════════════════════════════════════════════════════════════════════════
 *  Changelog
 * ══════════════════════════════════════════════════════════════════════════
 * 4.10.0 — پنل مدیریت یکپارچه شد.
 *
 *        — منو به جای ۲ رفت، بلافاصله زیر پیشخوان، با نام ToPersia Core.
 *          افزونهٔ نمایش و افزونهٔ کاربر زیرمنوی همین شدند تا منوی وردپرس
 *          با هر افزونهٔ تازه بالا و پایین نشود.
 *
 *        — topersia_admin_css() منبع واحد زبان بصری پنل‌هاست. هر سه افزونه
 *          همین را صدا می‌زنند؛ جهت وابستگی درست است چون آن‌ها به هسته
 *          تکیه می‌کنند نه برعکس.
 *
 * 4.9.0 — بخش ۱۵ کامل شد: خروجی فایل لاگ و ثبت خطای جاوااسکریپت.
 *
 *        — خروجی متنی از زبانهٔ لاگ. فیلترهای همان لحظه اعمال می‌شوند و
 *          فایل سه لایه دارد: سربرگ محیط، خلاصهٔ آماری با پرتکرارترین
 *          پیام‌ها، و رویدادها گروه‌بندی‌شده بر پایهٔ شناسهٔ درخواست.
 *          گروه‌بندی مهم‌ترین بخش است: یک خطا معمولاً چند سطر می‌سازد و
 *          جدا کردنشان بدون شناسهٔ درخواست ممکن نیست.
 *
 *        — خطای مرورگر هم به همین جدول می‌آید، کانال js. تا امروز نیمی از
 *          مسیر دیده نمی‌شد: خطای PHP ثبت می‌شد و خطای جاوااسکریپت نه.
 *
 *          فقط برای کاربر مدیر فعال می‌شود. دلیل: تزریق nonce در هر صفحه
 *          کش تمام‌صفحه را می‌شکند، و بدون nonce هر بازدیدکننده‌ای می‌تواند
 *          جدول را پر کند. عیب‌یابی هم همیشه با حساب مدیر انجام می‌شود.
 *
 * 4.8.0 — افزوده شد بخش ۱۵: سیستم ثبت رویداد.
 *
 *          آنچه جایگزین شد یک حلقهٔ پنجاه‌سطری در جدول options بود — برای
 *          عیب‌یابی یک روزه کافی، برای سایتی با ۱۹۴٬۰۰۰ صفحه و چند
 *          ویرایشگر هم‌زمان بی‌فایده.
 *
 *          سه تصمیم برای مقیاس:
 *          • جدول اختصاصی با ایندکس، نه options. نوشتن پیاپی روی options
 *            جدولی را متورم می‌کند که در هر بارگذاری صفحه خوانده می‌شود.
 *          • نوشتن بافرشده: رویدادها در حافظه جمع و در پایان درخواست با
 *            یک INSERT نوشته می‌شوند — یک کوئری در هر درخواست، نه یکی
 *            به‌ازای هر رویداد.
 *          • سقف پنجاه رویداد در هر درخواست، تا یک حلقهٔ معیوب نتواند در
 *            چند ثانیه دیسک را پر کند. رسیدن به سقف خودش ثبت می‌شود.
 *
 *        — شناسهٔ درخواست: همهٔ رویدادهای یک بارگذاری صفحه یک شناسه
 *          می‌گیرند. یک خطای واقعی چند سطر می‌سازد و وقتی چند ویرایشگر
 *          هم‌زمان کار می‌کنند این سطرها در هم می‌ریزند؛ فیلتر بر شناسه
 *          تنها راه جدا کردن داستان یک خطاست.
 *
 *        — گرفتن خطای مرگبار در هوک shutdown، از هر منبعی. اگر فقط
 *          فراخوانی‌های خودمان ثبت شوند، دقیقاً همان لحظه‌ای که صفحه سفید
 *          می‌شود هیچ چیزی نداریم. این همان چیزی است که در ۴.۶.۳ نداشتیم.
 *
 *        — مدیر خطای PHP برای هشدارها، که عمداً رفتار سایت را عوض نمی‌کند
 *          و کنترل را به مدیر پیش‌فرض برمی‌گرداند. یک لاگر نباید چیزی را
 *          که ثبت می‌کند تغییر دهد.
 *
 *        — هرس روزانه با دو سقف هم‌زمان: سن و تعداد.
 *        — زبانهٔ لاگ در پنل با فیلتر سطح، کانال، جست‌وجوی متن و شناسهٔ
 *          درخواست.
 *        — افزوده شد نوع فیلد select به طرح تنظیمات.
 * 4.7.2 — 🔴 رفع شمارش غلط «موجودیت منتشرشده». نسخهٔ ۴.۶.۰ با یک
 *          جایگزینی سراسری همهٔ کوئری‌ها را به publish+draft تبدیل کرد تا
 *          پیش‌نویس‌های واردکننده دیده شوند — ولی همین کوئری را هم گرفت و
 *          برچسب «منتشرشده» عدد مجموع را نشان می‌داد. با ۱۵۰۰ پیش‌نویس
 *          جغرافیایی، عدد به ۱٬۵۳۴ رسید در حالی که واقعاً ۵۱ بود.
 *
 *          جایگزینی سراسری بدون بررسی تک‌تک موارد، همان حدس‌زدن است.
 *
 *        — بررسی «بدون توضیح مؤثر» به دو ردیف تقسیم شد: منتشرشده (خطا) و
 *          پیش‌نویس (اطلاعاتی). پیش‌نویسِ بدون توضیح نقص نیست، کار ناتمام
 *          است. پس از ورود اسکلت جغرافیایی، علامت‌زدن هزاروپانصد پیش‌نویس
 *          به‌عنوان خطا ردیف را برای همیشه قرمز نگه می‌داشت و هشدار واقعی
 *          را زیر نویز دفن می‌کرد.
 * 4.7.1 — افزوده شد شناسایی رکوردهای یتیم به زبانهٔ اسکلت جغرافیایی.
 *
 *          رکورد یتیم آن است که در سایت هست ولی در فایل داده نیست —
 *          معمولاً بازماندهٔ اجرای نسخهٔ قدیمی‌تر فایل. حالت به‌روزرسانی
 *          هرگز لمسشان نمی‌کند، چون از فایل شروع می‌کند نه از دیتابیس. پس
 *          بی‌صدا برای همیشه می‌مانند.
 *
 *        — فهرست می‌شوند با پیوند ویرایش، نه حذف خودکار. ممکن است رکورد
 *          دستی و عمدی باشد یا محتوا داشته باشد؛ حذف خودکار در مقیاس هزار
 *          رکورد غیرقابل بازگشت است.
 * 4.7.0 — افزوده شد حالت «به‌روزرسانی» به واردکنندهٔ بخش ۱۴.
 *
 *          چرا لازم است: تقسیمات کشوری ایران هر سال عوض می‌شود — شهرستان
 *          تازه تأسیس می‌شود، روستا شهر می‌شود، املا اصلاح می‌شود. تا امروز
 *          واردکننده فقط می‌ساخت و رکورد موجود را رد می‌کرد، پس تنها راه
 *          اصلاح یک رکورد غلط، حذف دستی هزار پست و ورود دوباره بود.
 *
 *        — اسلاگ و entity_uid در حالت به‌روزرسانی دست‌نخورده می‌مانند.
 *          تغییر اسلاگ یعنی شکستن URL منتشرشده و تغییر entity_uid یعنی
 *          شکستن @id در کل گراف — هر دو غیرقابل بازگشت.
 *        — گزارش اجرا شمار «عنوان اصلاح‌شده» را جدا نشان می‌دهد، تا معلوم
 *          باشد به‌روزرسانی واقعاً چیزی را عوض کرده یا نه.
 * 4.6.4 — 🔴 رفع خطای مرگبار در هر ذخیرهٔ پست. تابع error_log روی این
 *          میزبان با disable_functions بسته است و topersia_log بدون گارد
 *          صدایش می‌زد.
 *
 *          درسی که P5-D138 می‌گوید و من رعایتش نکردم: هر فراخوانی بیرونی
 *          گارد می‌خواهد، حتی «تابع هستهٔ PHP». فرض، همان حدس است — این
 *          چهارمین بار در این پروژه بود.
 *
 *        — لاگ حالا در یک حلقهٔ پنجاه‌سطری در پایگاه‌داده می‌نشیند و در
 *          زبانهٔ تشخیص دیده می‌شود. مستقل از پیکربندی میزبان کار می‌کند و
 *          از فایل لاگ روی سرور هم در دسترس‌تر است.
 *
 *        — 🔴 محافظ حذف ردیف اصلاح شد. استک‌تریس محیط زنده نشان داد
 *          جت‌انجین از Cherry_X_Post_Meta و update_post_meta می‌نویسد —
 *          یعنی هوک درست بود و فرضیهٔ delete_post_meta در ۴.۶.۳ غلط. ولی
 *          وقتی همهٔ ردیف‌ها برداشته می‌شوند، مقدار نوشته‌شده آرایهٔ خالی
 *          نیست؛ رشتهٔ خالی است. شرط is_array دقیقاً همان‌جا گارد را کنار
 *          می‌گذاشت و بدترین حالت بی‌محافظ می‌ماند.
 * 4.6.3 — 🔴 محافظ حذف ردیف روی مسیر اصلی اصلاً اجرا نمی‌شد.
 *
 *          وقتی آخرین ردیف یک Repeater برداشته می‌شود، جت‌انجین به‌جای
 *          نوشتن آرایهٔ خالی، خودِ متا را حذف می‌کند. آن مسیر از فیلتر
 *          update_post_metadata عبور نمی‌کند — یعنی بدترین حالت، خالی‌کردن
 *          کل Repeater، بی‌محافظ مانده بود.
 *
 *          فرض‌کردن مسیر نوشتن بدون دیدنش، همان اشتباهی است که P5-D136
 *          هشدارش را می‌دهد. افزوده شد هوک delete_post_metadata.
 *
 *        — افزوده شد ردیابی مسیر نوشتن متا در حالت اشکال‌زدایی. وقتی محافظ
 *          اجرا نمی‌شود باید بشود دید جت‌انجین از کدام مسیر می‌نویسد،
 *          به‌جای حدس‌زدن.
 *        — پیام خطای واردکننده تشخیصی شد: پیش از این فقط می‌گفت «ساختارش
 *          معتبر نیست»، بدون اینکه بگوید فایل خالی است، JSON خراب است، یا
 *          کلیدها فرق دارند. حالا هر سه جدا گزارش می‌شوند.
 * 4.6.2 — حالت آزمایشی واردکننده یک‌جا انجام می‌شود، نه دسته‌ای. چیزی
 *          نوشته نمی‌شود پس دسته‌بندی بی‌معنا بود و فقط باعث می‌شد صفحه ده
 *          بار پشت سر هم رفرش شود — که شبیه حلقهٔ بی‌پایان به نظر می‌رسید.
 *
 *        — محافظ حذف ردیف دیگر خاموش کنار نمی‌کشد. اگر به‌دلیل نبودِ ترجمه
 *          دخالت نکند، پیام اطلاعاتی نشان می‌دهد و در لاگ ثبت می‌کند.
 *
 *          چرا مهم است: ویرایشگر ردیفی را حذف می‌کرد، هیچ اتفاقی نمی‌افتاد،
 *          و هرگز نمی‌فهمید محافظی وجود داشته و چرا دخالت نکرده. یک
 *          عدم‌رویدادِ نامرئی — دقیقاً همان جنس شکستی که این پروژه با آن
 *          درگیر بوده.
 *
 *        — افزوده شد گزینهٔ «محافظ ردیف حتی بدون ترجمه» برای حالت
 *          سخت‌گیرانه، پیش‌فرض خاموش.
 *        — افزوده شد ردیف تشخیص «محافظ حذف ردیف» که نشان می‌دهد محافظ
 *          روی چند موجودیت اصلاً می‌تواند فعال شود.
 * 4.6.1 — 🔴 رفع باگ آدرس در واردکنندهٔ بخش ۱۴. هر شش دکمه به‌جای زبانهٔ
 *          اسکلت جغرافیایی به صفحهٔ تنظیمات می‌پریدند.
 *
 *          ریشه: wp_nonce_url خروجی‌اش را با esc_html برمی‌گرداند، یعنی &
 *          تبدیل به &amp; می‌شود. اعمال دوبارهٔ esc_url روی آن باعث می‌شد
 *          مرورگر پارامترها را با نام «amp;tab» ببیند و tab اصلاً وجود
 *          نداشته باشد — پس پنل به زبانهٔ پیش‌فرض برمی‌گشت.
 *
 *          نمونهٔ دیگری از فرض‌کردن رفتار یک تابع بدون خواندنش. افزوده شد
 *          topersia_geo_url که آدرس خام می‌سازد و escape را به محل استفاده
 *          واگذار می‌کند.
 *
 *        — دستهٔ ۱۰۰تایی به ۵۰ کاهش یافت و تأخیر ادامهٔ خودکار از یک ثانیه
 *          به سه ثانیه رسید، به‌علاوهٔ دکمهٔ توقف. با تأخیر کوتاه، صفحه
 *          پیش از خوانده‌شدن می‌پرید و اگر خطایی رخ داده بود دیده نمی‌شد.
 * 4.6.0 — افزوده شد بخش ۸-ج: محافظ حذف ردیف Repeater.
 *          تا امروز P5-D121 فقط یک قاعدهٔ ادیتوریال بود و یک ویرایشگر در
 *          یک ثانیه می‌توانست نقضش کند. حالا اگر ردیفی حذف شود و آن پست
 *          ترجمه داشته باشد، همان ردیف در همان موقعیت برمی‌گردد و
 *          بازنشسته می‌شود — حذف به بازنشستگی تبدیل می‌شود.
 *
 *          چرا سمت سرور و نه پنهان‌کردن دکمه: پنهان‌کردن نیازمند حدس‌زدن
 *          کلاس‌های CSS جت‌انجین است و اگر افزونه نشانه‌گذاری‌اش را عوض
 *          کند، محافظ بی‌صدا از کار می‌افتد. همان دسته شکستی که P5-D136
 *          هشدارش را می‌دهد.
 *
 *        — فقط وقتی پست ترجمه دارد اعمال می‌شود. بدون ترجمه حذف بی‌ضرر
 *          است و اعمال محافظ فقط اصطکاک بی‌دلیل برای ورود دادهٔ اولیه
 *          می‌سازد، آن هم در مقیاس ۱۹۴٬۰۰۰ رکورد.
 *
 *        — 🔴 رفع شکافی که خودِ نسخهٔ ۴.۵.۰ ساخت: بررسی‌های سلامت داده فقط
 *          پست‌های منتشرشده را می‌شمردند، در حالی که واردکنندهٔ بخش ۱۴ هزار
 *          رکورد را به‌صورت پیش‌نویس می‌سازد. آن هزار رکورد از دید ابزار
 *          تشخیص نامرئی بودند و مشکلاتشان تازه در لحظهٔ انتشار بیرون
 *          می‌زد. حالا پیش‌نویس‌ها هم شمرده می‌شوند.
 *        — افزوده شد ردیف تشخیص «زنجیرهٔ جغرافیایی» که شهرستان و شهرِ
 *          بدون والد را می‌شمرد — سنجهٔ مستقیم DATA-P9-001.
 * 4.5.0 — افزوده شد بخش ۱۴: واردکنندهٔ اسکلت جغرافیایی، برای بستن
 *          DATA-P9-001 — زنجیرهٔ کشور ← استان ← شهرستان ← شهر.
 *
 *          چرا ابزار اختصاصی و نه WXR وردپرس: WXR پست و متا را وارد
 *          می‌کند ولی یال رابطهٔ JetEngine نمی‌سازد، و بدون یال زنجیرهٔ
 *          نیاکان و containedInPlace خالی می‌ماند — یعنی بدهی سر جایش.
 *
 *        — خودتکرارپذیر: هر رکورد با اسلاگش شناسایی می‌شود، اجرای دوباره
 *          موجودها را رد می‌کند. اگر نیمه‌کاره قطع شد، دوباره اجرا کن.
 *        — دسته‌ای ۱۰۰تایی با ادامهٔ خودکار، تا هزار رکورد تایم‌اوت ندهد.
 *        — حالت آزمایشی که پیش از هر نوشتنی نتیجه را نشان می‌دهد.
 *        — رکوردها پیش‌نویس ساخته می‌شوند نه منتشرشده: هزار صفحهٔ بدون متن
 *          که یک‌باره منتشر شوند به گوگل سیگنال محتوای نازک می‌دهند.
 * 4.4.0 — افزوده شد بخش ۸-ب: بستن جعبهٔ Custom Fields روی موجودیت‌ها (F-19).
 *          آن جعبه متاکلیدهای خام را با دکمهٔ ویرایش نشان می‌داد. ویرایش یک
 *          Repeater سریال‌شده به‌عنوان متن ساده کل داده را خراب می‌کند، و
 *          entity_uid که کل معماری @id روی پایداری‌اش بناست هم قابل تغییر
 *          بود. فلگ دارد ولی پیش‌فرض بسته است.
 *        — اصلاح ردیف تشخیص «متاکلید مشترک». نسخهٔ ۴.۱.۰ آن را «ناسازگار»
 *          می‌نامید و هشدار می‌داد؛ آن قضاوت غلط بود. بررسی اسناد CA نشان
 *          داد این الگوی عمدی و تصویب‌شدهٔ پروژه است و ۴۲ متاکلید از ۴۵
 *          متاکلید مشترک همین وضع را دارند (P5-D141).
 *        — به‌جایش ریسک واقعی سنجیده می‌شود: تصادم مقدار میان واژه‌نامه‌های
 *          هم‌کلید. اگر دو مجموعه مقدار یکسانی داشته باشند، کوئری مبهم
 *          می‌شود و نگاشت Schema نمی‌تواند تشخیص دهد مقدار از کجا آمده.
 *          مقدار not_applicable از این بررسی مستثناست، چون طبق P5-D109
 *          عمداً در همهٔ مجموعه‌ها هست.
 * 4.3.2 — نام درست متد حذف یال از محیط زنده گزارش شد: delete_rows.
 *          هیچ‌کدام از چهار نامی که در ۴.۳.۱ حدس زده شده بود وجود نداشت،
 *          پس گارد کار می‌کرد ولی یال برداشته نمی‌شد.
 *        — cleanup_relation در API هست ولی عمداً به فهرست نامزدها اضافه
 *          نشد: نامش می‌گوید کل رابطه را پاک می‌کند نه یک یال را. صدا زدنش
 *          همهٔ پیوندهای آن رابطه را در کل پروژه از بین می‌برد.
 *        — افزوده شد topersia_relation_signature و گزارش امضای متدها در
 *          زبانهٔ تشخیص. دانستن نام متد کافی نیست؛ اگر delete_rows به‌جای
 *          دو شناسه یک آرایه بخواهد، فراخوانی ما یا بی‌اثر است یا دامنه‌اش
 *          از یک یال فراتر می‌رود.
 *        — get_relation_name که در API واقعی هست، اولین نامزد خواندن نام
 *          رابطه شد.
 * 4.3.1 — 🔴 رفع خطای مرگبار هنگام برداشتن یال رابطه.
 *
 *          مسیر حذف یال از نسخهٔ ۱.۰.۰ در کد بود ولی هرگز اجرا نشده بود:
 *          تا آن روز هیچ توقفی از هیچ مسیری برداشته نشده بود و هیچ ردیفی
 *          بازنشسته نشده بود. اولین باری که یک ردیف regional_notes به
 *          بازنشسته تغییر کرد، ذخیرهٔ پست خوابید.
 *
 *          این سومین بار در یک جلسه بود که همین الگو تکرار شد — پس از
 *          jet_engine()->listings و پس از فیلتر قواعد پیش‌بارگذاری. نتیجه:
 *          هر فراخوانی به API افزونهٔ ثالث باید گارد داشته باشد، نه فقط
 *          آن‌هایی که به‌نظر خطرناک می‌رسند.
 *
 *        — افزوده شد topersia_relation_connect و topersia_relation_disconnect:
 *          چند نام متد را امتحان می‌کنند و خطا را با try/catch می‌گیرند، پس
 *          یک API ناشناخته دیگر نمی‌تواند ذخیرهٔ پست را بخواباند.
 *        — هر هشت فراخوانی مستقیم به شیء رابطه — در P9، استخراج استان و
 *          یال‌های مشتق‌شده — از این دو گارد عبور می‌کنند.
 *        — افزوده شد topersia_log برای ثبت شکست در حالت اشکال‌زدایی.
 *        — افزوده شد ردیف تشخیص «متدهای شیء رابطه» که API واقعی JetEngine
 *          را گزارش می‌کند، به‌جای اینکه ما نامش را حدس بزنیم.
 * 4.3.0 — پیاده‌سازی P5-D114: بخش ۶-ب، موتور عمومی یال‌های مشتق‌شده.
 *          زیرفیلد rn_g3_id در ریپیتر regional_notes روی P2 حالا یال‌های
 *          رابطهٔ applies_g3_p2 را می‌سازد. فیلد منبع حقیقت است؛ رابطه فقط
 *          ایندکس کوئری معکوس — همان الگوی بخش ۶ برای P9.
 *
 *          چرا موتور عمومی و نه تابع اختصاصی: این دومین باری است که همین
 *          الگو لازم می‌شود، و اسناد دستهٔ E و P موارد بیشتری پیش‌بینی
 *          کرده‌اند. افزودن مورد تازه حالا یک بلوک در نگاشت است، نه یک تابع.
 *
 *        — کلید role در نگاشت: در applies_g3_p2 والد استان است و فرزند ارز،
 *          یعنی برعکس P9. اشتباه گرفتن جهت، یال را وارونه می‌سازد و کوئری
 *          معکوس هرگز جواب نمی‌دهد — بدون هیچ خطایی.
 *        — ردیف بازنشسته یال نمی‌سازد: یادداشت بازنشسته یعنی آن استان دیگر
 *          یادداشتی ندارد، پس نباید یالی هم داشته باشد.
 *        — افزوده شد هشدار ادمین برای شناسهٔ نامعتبر. زیرفیلد از نوع number
 *          است و ویرایشگر می‌تواند هر عددی بنویسد؛ بدون هشدار، یک عدد اشتباه
 *          فقط باعث می‌شد یال ساخته نشود، بی‌هیچ نشانه‌ای.
 *        — افزوده شد ثابت و تنظیم TOPERSIA_REL_PROVINCE_CURRENCY.
 * 4.2.0 — 🔴 رفع نشتی /geo در بلوک قواعد پیش‌بارگذاری (F-18). وردپرس ۶٫۸
 *          فهرست مسیرهای مستثنا را در فوتر منتشر می‌کند و «/geo/wp-admin/*»
 *          روی هر صفحه برای هر بازدیدکننده دیده می‌شد.
 *
 *          تابعی که در نسخهٔ ۳.۱.۰ برای همین نوشته شده بود هرگز اثری
 *          نداشت: هستهٔ وردپرس پس از اجرای فیلتر، مسیرهای پیش‌فرض را
 *          دوباره ادغام می‌کند تا هیچ افزونه‌ای نتواند حذفشان کند. آن فیلتر
 *          به‌طراحی قابل دور زدن نیست. و چون حالت تعمیر روشن بود، خروجی
 *          بازدیدکنندهٔ ناشناس تا امروز اصلاً دیده نشده بود.
 *
 *          حالا فقط داخل همان یک بلوک اسکریپت، پیشوند پوشه حذف می‌شود —
 *          و فقط برای کاربر واردنشده.
 *
 *        — افزوده شد الحاق خودکار نام برند به عنوان سئو (F-17 گزینهٔ الف).
 *          فیلتر عنوان کل عنوان را جایگزین می‌کرد و نام ToPersia را از هر
 *          نتیجهٔ جستجو حذف کرده بود. سه گارد: نبودِ تکرار، سقف نویسه، و
 *          ساخت خودکار پسوند از نام سایت وقتی خالی باشد.
 *        — افزوده شد topersia_str_len و topersia_str_has با گارد mbstring.
 *          فراخوانی تابع تعریف‌نشده همان دسته خطای مرگباری است که ۴.۱.۴
 *          برای رفعش نوشته شد.
 *        — پاک‌سازی ورودی تنظیمات تفکیک شد. تا پیش از این، همان قاعدهٔ سختِ
 *          مسیرها روی همهٔ فیلدهای متنی اجرا می‌شد؛ پسوند برند که خط تیرهٔ
 *          بلند و حرف فارسی دارد، بی‌صدا خالی ذخیره می‌شد.
 * 4.1.4 — 🔴 سخت‌سازی مسیر عنوان و توضیح متا پس از گزارش خطای مرگبار روی
 *          صفحات موجودیت. هسته دیگر jet_engine()->listings->data->get_meta()
 *          را صدا نمی‌زند.
 *
 *          ریشهٔ ساختاری: آن فراخوانی از نسخهٔ ۲.۰.۰ در کد بود ولی هرگز
 *          اجرا نمی‌شد، چون متغیرهای سفارشی Rank Math ثبت می‌شدند و
 *          هیچ‌وقت به‌کار نمی‌رفتند — همان نقص F-13. نسخهٔ ۴.۱.۰ با افزودن
 *          دو فیلتر frontend، برای نخستین بار آن مسیر را زنده کرد. یعنی
 *          کدی که سه ماه در فایل بود ولی هرگز آزموده نشده بود، یک‌باره روی
 *          هر صفحهٔ موجودیت اجرا شد.
 *
 *          درس: رفع یک نقص می‌تواند کد مرده را زنده کند. کدی که تا دیروز
 *          اجرا نمی‌شد، «آزموده» نیست — فقط خاموش بوده.
 *
 *        — گاردش هم ناقص بود: فقط isset( ->listings ) بررسی می‌شد، نه خودِ
 *          ->data و نه وجود متد. در PHP 8 فراخوانی متد روی null خطای
 *          مرگبار است، نه هشدار.
 *        — این فیلدها متن ساده‌اند؛ get_post_meta برایشان کافی است. یک
 *          وابستگی که سود نمی‌دهد ولی می‌تواند سایت را بخواباند، حذف شد.
 *        — افزوده شد گارد بازگشتی روی هر دو فیلتر frontend، تا اگر خواندن
 *          متا دوباره همان فیلتر را فایر کند، حلقهٔ بی‌پایان نشود.
 * 4.1.3 — ستون نام رابطه‌ها که در ۴.۱.۲ هنوز خالی می‌ماند، از راه جدول خام
 *          حل شد. سه متد روی شیء رابطه امتحان شده بود و هر سه خالی
 *          برمی‌گشتند؛ به‌جای امتحان متد چهارم، همان مسیری به کار رفت که
 *          برای واژه‌نامه‌ها اثبات شده بود.
 *        — افزوده شد جهت رابطه به همان جدول. بدون آن، یک شناسهٔ اشتباه که
 *          تصادفاً به رابطهٔ موجودِ دیگری اشاره کند سبز نشان داده می‌شد؛
 *          حالا نوع پست والد و فرزند دیده می‌شود، پس درستی شناسه قابل
 *          راستی‌آزمایی است نه فقط اعتبارش.
 *        — بررسی «بدون meta_description» با «بدون هیچ توضیح مؤثر» جایگزین
 *          شد. نسخهٔ قبلی فقط یک فیلد را می‌شمرد و «همه دارند» می‌گفت، در
 *          حالی که خروجی زندهٔ یک صفحه هیچ توضیحی نداشت. حالا همان زنجیرهٔ
 *          سه‌حلقه‌ای بررسی می‌شود که بخش ۸ در زمان رندر اجرا می‌کند، و
 *          نمونه‌های ناقص نام‌به‌نام فهرست می‌شوند.
 *        — افزوده شد شمارندهٔ «متکی به پشتیبان»: موجودیت‌هایی که توضیح
 *          اختصاصی SERP ندارند ولی از short_summary یا ai_summary استفاده
 *          می‌کنند. کار می‌کند، ولی بهینه نیست.
 * 4.1.2 — رفع ریشه‌ایِ همان باگ ۴.۱.۱. گزارش کلیدهای واقعی روی محیط زنده
 *          نشان داد آیتم‌های واژه‌نامه شکل جدول عمومی JetEngine را دارند —
 *          id · slug · status · labels · args · meta_fields — که در آن slug
 *          همیشه خالی است و نام در labels کدشده زندگی می‌کند. همان الگویی
 *          که پیش‌تر برای روابط ثابت شده بود و باید همان‌جا تعمیم می‌یافت.
 *        — افزوده شد topersia_diag_decode(): سه ستون کدشدهٔ JetEngine را باز
 *          می‌کند. هم PHP-serialized و هم JSON را می‌پذیرد، چون بسته به نوع
 *          موجودیت هر دو دیده می‌شود.
 *        — unserialize با allowed_classes = false صدا زده می‌شود و فقط روی
 *          رشته‌ای که با a: شروع شود. بدون این، یک رشتهٔ دستکاری‌شده
 *          می‌توانست نمونهٔ شیء بسازد و __wakeup آن اجرا شود.
 *        — نام رابطه هم از همان رمزگشا عبور می‌کند.
 * 4.1.1 — 🔴 رفع دو باگ در زبانهٔ تشخیص که روی محیط زنده کشف شدند.
 *        — بررسی «نام تکراری واژه‌نامه» هر ۷۴ واژه‌نامه را تکراری گزارش
 *          می‌کرد. ریشه: نسخهٔ ۴.۱.۰ فرض کرده بود آیتم‌های get_items() همان
 *          شکل فایل export را دارند. روی محیط زنده کلید id جواب می‌داد ولی
 *          name نه، پس همه زیر یک نام خالی گروه‌بندی می‌شدند. یک هشدار کاذب
 *          از نبود هشدار بدتر است: یاد می‌دهد قرمزها را نادیده بگیری.
 *        — افزوده شد topersia_diag_normalize_glossary(): چند نامزد کلید را
 *          امتحان می‌کند و اگر هیچ‌کدام جواب نداد، بررسی‌های وابسته به نام
 *          را صریحاً کنار می‌گذارد و کلیدهای واقعی را گزارش می‌دهد — به‌جای
 *          دادن نتیجهٔ غلط با دادهٔ ناقص.
 *        — افزوده شد topersia_diag_relation_name(): نام رابطه از سه مسیر
 *          مختلف امتحان می‌شود. نسخهٔ ۴.۱.۰ فقط get_arg('labels') را
 *          می‌آزمود و ستون نام خالی می‌ماند بدون اینکه معلوم باشد چرا.
 *        — افزوده شد بررسی تازه: واژه‌نامهٔ بدون پیشوند استاندارد (P5-D127).
 * 4.1.0 — افزوده شد بخش ۱۳: پنل مدیریت ToPersia با سه زبانه.
 *          • تنظیمات — شناسه‌های رابطه و فلگ‌ها دیگر در کد قفل نیستند.
 *            ترتیب تقدم: wp-config › پنل › پیش‌فرض کد. ویرایش پیکربندی
 *            دیگر نیازی به رفتن به سرور ندارد، ولی کد همچنان تنها جایی
 *            است که منطق در آن زندگی می‌کند.
 *          • تشخیص — همان بررسی‌هایی که تا امروز دستی و با اسکریپت انجام
 *            می‌شد: اعتبار شناسهٔ هر رابطه، واژه‌نامهٔ هم‌نام تکراری،
 *            واژه‌نامهٔ یتیم، متاکلید مشترک با تعریف ناسازگار، Repeater
 *            بدون row_status، و سلامت داده. پنج نقص خاموشی که در ممیزی
 *            ۳۱ اوت ۲۰۲۶ کشف شد، همگی از این نوع بودند.
 *          • راهنما — نقشهٔ اینکه هر کاری در کدام فایل انجام می‌شود.
 *        — عمداً ویرایشگر کد ساخته نشد. دلیلش در زبانهٔ راهنما آمده.
 *        — 🔴 رفع نبود کامل تگ توضیح متا در کل سایت. دو متغیر سفارشی
 *          Rank Math از نسخهٔ ۲.۰.۰ ثبت می‌شدند ولی هرگز در تنظیمات
 *          Titles & Meta به‌کار نرفته بودند، پس فیلد meta_description به
 *          HTML نمی‌رسید — با اینکه در JSON-LD درست منتشر می‌شد. حالا دو
 *          فیلتر frontend این کار را برای هر ۴۲ نوع پست خودکار می‌کنند.
 *        — 🔴 رفع نبود og:image و twitter:image. hero_image با تصویر شاخص
 *          وردپرس همگام می‌شود؛ بدون آن هر اشتراک‌گذاری کارت بی‌تصویر بود.
 *        — افزوده شد زنجیرهٔ پشتیبان توضیح متا: meta_description ←
 *          short_summary ← ai_summary. عنوان به عنوان پست پشتیبان می‌شود.
 *        — افزوده شد topersia_entity_meta() به‌عنوان خوانندهٔ یکدست متا.
 * 4.0.0 — 🔶 تغییر شکننده: موتور دادهٔ ساختاریافته (بخش ۹) به افزونهٔ
 *          جداگانهٔ topersia-schema منتقل شد.
 *        — چهار فیلتر خاموش‌کنندهٔ شِمای Rank Math هم به همان افزونه رفتند،
 *          چون فقط زمانی معنا دارند که موتور ما جایشان را پر کند.
 *        — همهٔ شناسه‌های رابطهٔ P9 از داخل تابع به بخش ۰ منتقل شدند.
 *        — ترتیب فیزیکی بخش‌ها با فهرست سرصفحه هم‌تراز شد.
 *        — افزوده شد ثابت TOPERSIA_CORE_VERSION.
 * 3.3.0 — افزوده شد topersia_active_rows() — قاعدهٔ سراسری وضعیت ردیف
 *          (P5-D121). حذف ردیف از هر Repeater ترجمه‌شدنی ممنوع است، چون
 *          P5-T008 ثابت کرد WPML ردیف‌ها را با شمارهٔ موقعیت دنبال می‌کند.
 * 3.2.0 — افزوده شد موجودیت G5 شهر و سازندهٔ عمومی موجودیت‌های مکانی.
 * 3.1.0 — رفع آخرین نشتی /geo در بلوک قواعد پیش‌بارگذاری وردپرس ۶٫۸.
 * 3.0.0 — 🔴 رفع آسیب‌پذیری XSS در خروجی JSON-LD.
 *        — افزوده شد بخش ۱۱ (پنهان‌سازی /geo) و بخش ۱۲ (کاهش اثر انگشت).
 * 2.0.1 — رفع پنج ایراد Schema Markup Validator روی گرهٔ TouristTrip.
 * 2.0.0 — بازنویسی کامل در ده بخش · افزوده شد موتور دادهٔ ساختاریافته.
 * 1.4.0 — غیرفعال‌سازی استخراج خودکار استان · entity_uid با بخش نوع.
 * 1.3.0 — اصلاح شناسهٔ رابطهٔ R01 از ۷ به ۷۲ پس از بازسازی فاز ۵.
 * 1.2.0 — اجرای منطق اسلاگ روی wpml_pro_translation_completed.
 * 1.1.0 — ریدایرکت ۳۰۱ صفحات tp_county به استان والد (P5-D018).
 * 1.0.1 — رفع باگ تشخیص اسلاگ درصد-کدشده به‌عنوان «سالم».
 * 1.0.0 — نسخهٔ اول.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit; // دسترسی مستقیم مجاز نیست.
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۰ — پیکربندی
 * ═══════════════════════════════════════════════════════════════════════
 * ترتیب تقدم، از قوی به ضعیف:
 *
 *   ۱. define در wp-config.php     — قفل سخت، پنل نمی‌تواند تغییرش دهد
 *   ۲. تنظیم در پنل ToPersia       — راه معمول تغییر
 *   ۳. پیش‌فرض همین فایل            — وقتی هیچ‌کدام تنظیم نشده باشد
 *
 * چرا این ترتیب: در شرایط اضطراری — مثلاً وقتی یک فلگ سایت را شکسته و
 * پیشخوان در دسترس نیست — همیشه باید راهی باشد که از بیرون پنل قفلش کنی.
 * wp-config آن راه است.
 *
 * چرا اصلاً پنل: شناسهٔ رابطهٔ G3–G4 یک بار از ۷ به ۷۲ عوض شد و چون در کد
 * قفل بود، ریدایرکت بی‌صدا شکست تا مدت‌ها بعد کشف شود. پیکربندی‌ای که
 * به‌ندرت ولی حتماً عوض می‌شود، نباید در فایل زندانی باشد.
 */

/** نسخهٔ هسته — افزونهٔ شِما این را برای بررسی سازگاری می‌خواند. */
