/**
 * همهٔ تنظیمات، با پیش‌فرض‌های پرشده.
 *
 * یک بار در هر درخواست خوانده می‌شود و در حافظه کش می‌ماند. گزینه autoload
 * است، پس کوئری اضافه نمی‌زند.
 */
function topersia_settings() {

	static $cache = null;

	if ( null !== $cache ) {
		return $cache;
	}

	$schema = topersia_settings_schema();
	$saved  = get_option( TOPERSIA_OPTION_KEY, array() );
	$saved  = is_array( $saved ) ? $saved : array();

	$cache = array();

	foreach ( $schema as $key => $spec ) {

		if ( ! array_key_exists( $key, $saved ) ) {
			$cache[ $key ] = $spec['default'];
			continue;
		}

		if ( 'int' === $spec['type'] ) {

			$cache[ $key ] = absint( $saved[ $key ] );

		} elseif ( 'bool' === $spec['type'] ) {

			$cache[ $key ] = (bool) $saved[ $key ];

		} elseif ( 'select' === $spec['type'] ) {

			// مقدار خارج از فهرست مجاز پذیرفته نمی‌شود.
			$value         = sanitize_text_field( (string) $saved[ $key ] );
			$cache[ $key ] = isset( $spec['choices'][ $value ] ) ? $value : $spec['default'];

		} else {

			$cache[ $key ] = sanitize_text_field( (string) $saved[ $key ] );
		}
	}

	return $cache;
}

/** مقدار یک تنظیم. */
function topersia_setting( $key ) {

	$all = topersia_settings();

	return isset( $all[ $key ] ) ? $all[ $key ] : null;
}

/* ─── ثابت‌ها ───
 *
 * هر ثابت با گارد if(!defined) تعریف می‌شود، پس define در wp-config.php
 * همیشه برنده است و پنل نمی‌تواند دورش بزند.
 */

/** G3 استان → G4 شهرستان — نام رابطه در پنل: province_county */
if ( ! defined( 'TOPERSIA_REL_PROVINCE_COUNTY' ) ) {
	define( 'TOPERSIA_REL_PROVINCE_COUNTY', (int) topersia_setting( 'rel_province_county' ) );
}

if ( ! defined( 'TOPERSIA_REL_NAME_PROVINCE_COUNTY' ) ) {
	define( 'TOPERSIA_REL_NAME_PROVINCE_COUNTY', 'province_county' );
}

/** G4 شهرستان → G5 شهر — نام رابطه در پنل: county_city */
if ( ! defined( 'TOPERSIA_REL_COUNTY_CITY' ) ) {
	define( 'TOPERSIA_REL_COUNTY_CITY', (int) topersia_setting( 'rel_county_city' ) );
}

/** P9 مسیر → G3 استان — R03 */
if ( ! defined( 'TOPERSIA_REL_ROUTE_PROVINCE' ) ) {
	define( 'TOPERSIA_REL_ROUTE_PROVINCE', (int) topersia_setting( 'rel_route_province' ) );
}

/** P9 مسیر → G5 شهر — R03 */
if ( ! defined( 'TOPERSIA_REL_ROUTE_CITY' ) ) {
	define( 'TOPERSIA_REL_ROUTE_CITY', (int) topersia_setting( 'rel_route_city' ) );
}

/** P9 مسیر → G7 روستا — R03 */
if ( ! defined( 'TOPERSIA_REL_ROUTE_VILLAGE' ) ) {
	define( 'TOPERSIA_REL_ROUTE_VILLAGE', (int) topersia_setting( 'rel_route_village' ) );
}

/** P9 مسیر → G8 جزیره — R03 */
if ( ! defined( 'TOPERSIA_REL_ROUTE_ISLAND' ) ) {
	define( 'TOPERSIA_REL_ROUTE_ISLAND', (int) topersia_setting( 'rel_route_island' ) );
}

/** G3 استان → P2 ارز — نام رابطه در پنل: applies_g3_p2 */
if ( ! defined( 'TOPERSIA_REL_PROVINCE_CURRENCY' ) ) {
