/** دامنهٔ پایهٔ شناسهٔ یکتای موجودیت — بدون اسلش پایانی. */
if ( ! defined( 'TOPERSIA_UID_BASE' ) ) {
	define( 'TOPERSIA_UID_BASE', 'https://topersia.com/e' );
}

/**
 * دامنهٔ ریشه برای @id های سراسری.
 *
 * افزونهٔ شِما هم همین را با گارد if(!defined) تعریف می‌کند، تا هر کدام
