/** نام واقعی پوشهٔ نصب وردپرس — بخش ۱۱. */
if ( ! defined( 'TOPERSIA_WP_DIR' ) ) {
	define( 'TOPERSIA_WP_DIR', (string) topersia_setting( 'wp_dir' ) );
}

/** مسیر عمومی جایگزین برای wp-content — بخش ۱۱. */
if ( ! defined( 'TOPERSIA_ASSETS_PATH' ) ) {
	define( 'TOPERSIA_ASSETS_PATH', (string) topersia_setting( 'assets_path' ) );
}

/** مسیر عمومی جایگزین برای wp-includes — بخش ۱۱. */
if ( ! defined( 'TOPERSIA_CORE_PATH' ) ) {
	define( 'TOPERSIA_CORE_PATH', (string) topersia_setting( 'core_path' ) );
