/** حذف کتابخانهٔ CSS بلوک‌ها — بخش ۱۲. */
if ( ! defined( 'TOPERSIA_DROP_BLOCK_CSS' ) ) {
	define( 'TOPERSIA_DROP_BLOCK_CSS', (bool) topersia_setting( 'drop_block_css' ) );
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۱ — ابزارهای مشترک
 * ═══════════════════════════════════════════════════════════════════════
 * توابعی که چند بخش — و افزونهٔ شِما — از آن‌ها استفاده می‌کنند. هر تابعی
 * که اینجا اضافه می‌شود بخشی از قرارداد عمومی هسته است و حذف یا تغییر
 * امضایش می‌تواند افزونهٔ شِما را بشکند.
 */

/** آیا این پست یک موجودیت ToPersia است؟ */
function topersia_is_entity( $post_type ) {
	return is_string( $post_type ) && 0 === strpos( $post_type, 'tp_' );
}

/**
 * آیا این پست نسخهٔ زبان پیش‌فرض است؟
 *
 * کدهایی که ساختار داده را می‌نویسند باید فقط روی نسخهٔ فارسی اجرا شوند،
 * وگرنه نسخهٔ انگلیسی و عربی همان داده را دوباره و گاهی متناقض می‌نویسند.
 */
function topersia_is_default_language( $post_id ) {

	if ( ! has_filter( 'wpml_default_language' ) ) {
		return true; // WPML نصب نیست — همه‌چیز زبان پیش‌فرض است.
	}

	$details = apply_filters( 'wpml_post_language_details', null, $post_id );
	$default = apply_filters( 'wpml_default_language', null );

	if ( empty( $details['language_code'] ) ) {
		return true; // نامشخص — محافظه‌کارانه اجازه بده.
	}

	return $details['language_code'] === $default;
}

/** شیء رابطهٔ JetEngine را با شناسه برمی‌گرداند. */
function topersia_relation( $relation_id ) {

	if ( ! function_exists( 'jet_engine' ) || ! isset( jet_engine()->relations ) ) {
		return false;
	}

	$relation = jet_engine()->relations->get_active_relations( $relation_id );

	return $relation ? $relation : false;
}

/**
 * یک پیام را فقط در حالت اشکال‌زدایی در لاگ می‌نویسد.
 *
 * هدف: شکست‌های خاموشِ لایهٔ افزونهٔ ثالث ردپا داشته باشند، بدون اینکه در
 * حالت عادی چیزی به لاگ سرور اضافه شود.
 */
/* ───────────────────────────────────────────────────────────────────────
 *  بخش ۱۵ — سیستم ثبت رویداد
 * ───────────────────────────────────────────────────────────────────────
 * چرا این سیستم به‌جای یک فایل لاگ ساده:
 *
 * ۱ — error_log روی این میزبان با disable_functions بسته است. تکیه بر آن
 *     یعنی هیچ ردپایی نداشتن — و همان فرض، یک بار سایت را خواباند.
 *
 * ۲ — در مقیاس ۱۹۴٬۰۰۰ صفحه و چند ویرایشگر هم‌زمان، یک خطا ده‌ها سطر
 *     تولید می‌کند که در هم می‌ریزند. بدون شناسهٔ درخواست، فهمیدن اینکه
 *     کدام سطرها به یک اتفاق مربوطند غیرممکن است.
 *
 * ۳ — خطای مرگبار در هر افزونه‌ای می‌تواند رخ دهد، نه فقط کد ما. اگر فقط
 *     فراخوانی‌های خودمان را ثبت کنیم، دقیقاً همان لحظه‌ای که سایت سفید
 *     می‌شود هیچ چیزی نداریم.
 *
 * ── سه تصمیم برای مقیاس ─────────────────────────────────────────────
 *
 * جدول اختصاصی، نه options: نوشتن پیاپی روی options در هر رویداد یک کوئری
 * می‌زند و جدول options را که در هر بارگذاری خوانده می‌شود متورم می‌کند.
 *
 * نوشتن بافرشده: رویدادها در حافظه جمع می‌شوند و در پایان درخواست با یک
 * INSERT نوشته می‌شوند. یک کوئری در هر درخواست، نه یکی به‌ازای هر رویداد.
 *
 * سقف در هر درخواست: یک حلقهٔ معیوب می‌تواند میلیون‌ها سطر بسازد. سقف
 * پنجاه‌تایی جلویش را می‌گیرد و خودِ رسیدن به سقف هم ثبت می‌شود.
 */

/** نام جدول لاگ. */
function topersia_log_table() {

	global $wpdb;

	return $wpdb->prefix . 'topersia_log';
}

/** نسخهٔ ساختار جدول — تغییرش باعث اجرای دوبارهٔ dbDelta می‌شود. */
if ( ! defined( 'TOPERSIA_LOG_SCHEMA' ) ) {
	define( 'TOPERSIA_LOG_SCHEMA', '1.0' );
}

/**
 * برش امن یک رشتهٔ UTF-8.
 *
 * mbstring روی هر میزبانی نصب نیست. این تابع در خودِ لاگر به کار می‌رود،
 * و یک فراخوانی محافظت‌نشده آنجا بدترین حالت ممکن است: ابزاری که برای
 * تشخیص خرابی ساخته شده، خودش منبع خرابی شود.
 *
 * پشتیبان PCRE با پرچم /u است، نه substr بایتی — چون برش وسط یک نویسهٔ
 * چندبایتی، رشتهٔ نامعتبر می‌سازد که در JSON و پایگاه‌داده مشکل درست
 * می‌کند.
 */
function topersia_str_cut( $text, $length ) {

	$text = (string) $text;

	if ( function_exists( 'mb_substr' ) ) {
		return mb_substr( $text, 0, $length, 'UTF-8' );
	}

	if ( preg_match( '/^.{0,' . absint( $length ) . '}/us', $text, $m ) ) {
		return $m[0];
	}

	return substr( $text, 0, $length );
}

/** وزن سطوح — برای مقایسه با آستانه. */
function topersia_log_levels() {

	return array(
		'debug'    => 10,
		'info'     => 20,
		'notice'   => 30,
		'warning'  => 40,
		'error'    => 50,
		'critical' => 60,
	);
}

/**
 * شناسهٔ یکتای این درخواست.
 *
 * همهٔ رویدادهای یک بارگذاری صفحه این شناسه را می‌گیرند. در پنل می‌شود
 * روی آن فیلتر کرد و کل داستان یک خطا را از اول تا آخر دید — که در
 * سایتی با چند ویرایشگر هم‌زمان تنها راه فهمیدن است.
 */
function topersia_request_id() {

	static $id = null;

	if ( null === $id ) {
		$id = substr( md5( uniqid( (string) mt_rand(), true ) ), 0, 12 );
	}

	return $id;
}

/** ساخت یا به‌روزرسانی جدول لاگ. */
function topersia_log_install() {

	if ( get_option( 'topersia_log_schema' ) === TOPERSIA_LOG_SCHEMA ) {
		return;
	}

	global $wpdb;

	require_once ABSPATH . 'wp-admin/includes/upgrade.php';

	$table   = topersia_log_table();
	$collate = $wpdb->get_charset_collate();

	dbDelta(
		"CREATE TABLE {$table} (
			id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
			logged_at DATETIME NOT NULL,
			level VARCHAR(10) NOT NULL DEFAULT 'info',
			channel VARCHAR(32) NOT NULL DEFAULT 'core',
			message TEXT NOT NULL,
			context LONGTEXT NULL,
			request_id CHAR(12) NOT NULL DEFAULT '',
			user_id BIGINT UNSIGNED NOT NULL DEFAULT 0,
			url VARCHAR(255) NOT NULL DEFAULT '',
			source VARCHAR(191) NOT NULL DEFAULT '',
			PRIMARY KEY (id),
			KEY level_time (level, logged_at),
			KEY channel_time (channel, logged_at),
			KEY request (request_id)
		) {$collate};"
	);

	update_option( 'topersia_log_schema', TOPERSIA_LOG_SCHEMA, false );
}
add_action( 'admin_init', 'topersia_log_install' );

/**
 * ثبت یک رویداد.
 *
 * @param string $message متن — کوتاه و قابل جست‌وجو.
 * @param string $level   debug · info · notice · warning · error · critical
 * @param string $channel نام بخش، برای فیلتر کردن: geo · schema · relation · seo · guard
 * @param array  $context دادهٔ ساختاریافته — شناسهٔ پست، نام فیلد، هر چیزی که به یافتن علت کمک کند.
 */
function topersia_log( $message, $level = 'info', $channel = 'core', $context = array() ) {

	static $buffer = array();
	static $capped = false;

	// فراخوانی بدون آرگومان یعنی درخواست تخلیهٔ بافر — از هوک shutdown.
	if ( '' === $message ) {
		return $buffer;
	}

	if ( ! topersia_setting( 'log_enabled' ) ) {
		return null;
	}

	$levels    = topersia_log_levels();
	$threshold = topersia_setting( 'log_level' );
	$weight    = isset( $levels[ $level ] ) ? $levels[ $level ] : 20;

	if ( $weight < ( isset( $levels[ $threshold ] ) ? $levels[ $threshold ] : 40 ) ) {
		return null;
	}

	/*
	 * سقف در هر درخواست.
	 *
	 * یک حلقهٔ معیوب می‌تواند در چند ثانیه میلیون‌ها سطر بسازد و دیسک را پر
	 * کند. رسیدن به سقف خودش یک رویداد است — وگرنه بی‌صدا کوتاه می‌شد و
	 * کسی نمی‌فهمید چیزی جا افتاده.
	 */
	if ( count( $buffer ) >= 50 ) {

		if ( ! $capped ) {

			$capped   = true;
			$buffer[] = array(
				'level'   => 'warning',
				'channel' => 'log',
				'message' => 'سقف پنجاه رویداد در این درخواست پر شد — بقیه ثبت نشدند',
				'context' => array(),
				'source'  => '',
			);
		}

		return null;
	}

	/* محل فراخوانی — بدون هزینهٔ گرفتن کل پشته. */
	$trace  = debug_backtrace( DEBUG_BACKTRACE_IGNORE_ARGS, 2 );
	$source = '';

	if ( isset( $trace[0]['file'] ) ) {
		$source = basename( $trace[0]['file'] ) . ':' . ( isset( $trace[0]['line'] ) ? $trace[0]['line'] : '?' );
	}

	$buffer[] = array(
		'level'   => isset( $levels[ $level ] ) ? $level : 'info',
		'channel' => substr( preg_replace( '/[^a-z0-9_-]/i', '', $channel ), 0, 32 ),
		'message' => topersia_str_cut( wp_strip_all_tags( (string) $message ), 2000 ),
		'context' => is_array( $context ) ? $context : array( 'value' => $context ),
		'source'  => $source,
	);

	return true;
}

/**
 * نوشتن بافر در پایان درخواست.
 *
 * یک INSERT برای همهٔ رویدادها، نه یکی به‌ازای هر رویداد. در صفحه‌ای که
 * ده رویداد ثبت می‌کند، این تفاوت ده کوئری است — و در سایتی با ترافیک
 * واقعی، تفاوت بین قابل‌استفاده و غیرقابل‌استفاده.
 */
add_action( 'shutdown', 'topersia_log_flush', 999 );

function topersia_log_flush() {

	$buffer = topersia_log( '' );

	if ( empty( $buffer ) || ! is_array( $buffer ) ) {
		return;
	}

	global $wpdb;

	$table = topersia_log_table();

	if ( get_option( 'topersia_log_schema' ) !== TOPERSIA_LOG_SCHEMA ) {
		return; // جدول هنوز ساخته نشده.
	}

	$now  = current_time( 'mysql' );
	$rid  = topersia_request_id();
	$uid  = function_exists( 'get_current_user_id' ) ? get_current_user_id() : 0;
	$url  = isset( $_SERVER['REQUEST_URI'] ) ? substr( sanitize_text_field( wp_unslash( $_SERVER['REQUEST_URI'] ) ), 0, 255 ) : '';

	$rows   = array();
	$values = array();

	foreach ( $buffer as $entry ) {

		$rows[]   = '(%s,%s,%s,%s,%s,%s,%d,%s,%s)';
		$values[] = $now;
		$values[] = $entry['level'];
		$values[] = $entry['channel'];
		$values[] = $entry['message'];
		$values[] = $entry['context'] ? wp_json_encode( $entry['context'], JSON_UNESCAPED_UNICODE ) : '';
		$values[] = $rid;
		$values[] = $uid;
		$values[] = $url;
		$values[] = $entry['source'];
	}

	$sql = "INSERT INTO {$table} (logged_at,level,channel,message,context,request_id,user_id,url,source) VALUES " . implode( ',', $rows );

	// phpcs:ignore WordPress.DB.PreparedSQL
	$wpdb->query( $wpdb->prepare( $sql, $values ) );
}

/**
 * گرفتن خطای مرگبار در لحظهٔ خاموشی.
 *
 * این تنها راهی است که وقتی صفحه سفید می‌شود چیزی بدانی. خطا از هر
 * افزونه‌ای که باشد گرفته می‌شود، نه فقط کد خودمان — و دقیقاً همان چیزی
 * است که در مقیاس چند افزونه و چند ویرایشگر لازم می‌شود.
 *
 * روی اولویت ۰ می‌نشیند تا پیش از تخلیهٔ بافر اجرا شود.
 */
add_action( 'shutdown', 'topersia_log_catch_fatal', 0 );

function topersia_log_catch_fatal() {

	if ( ! topersia_setting( 'log_php_errors' ) ) {
		return;
	}

	$error = error_get_last();

	if ( ! $error || ! in_array( $error['type'], array( E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR, E_USER_ERROR ), true ) ) {
		return;
	}

	topersia_log(
		$error['message'],
		'critical',
		'php',
		array(
			'file' => str_replace( ABSPATH, '', $error['file'] ),
			'line' => $error['line'],
			'type' => $error['type'],
		)
	);
}

/**
 * گرفتن هشدارها و نکته‌های PHP.
 *
 * عمداً هشدارها را به خطا تبدیل نمی‌کند و اجرا را متوقف نمی‌کند — فقط
 * ثبت می‌کند و کنترل را به مدیر خطای قبلی برمی‌گرداند. یک لاگر نباید
 * رفتار سایت را عوض کند.
 */
add_action( 'plugins_loaded', 'topersia_log_register_error_handler', 1 );

function topersia_log_register_error_handler() {

	if ( ! topersia_setting( 'log_php_errors' ) || ! topersia_setting( 'log_enabled' ) ) {
		return;
	}

	$levels = topersia_log_levels();

	if ( $levels[ topersia_setting( 'log_level' ) ] > $levels['warning'] ) {
		return; // آستانه بالاتر از هشدار است — ثبت هشدار بی‌معناست.
	}

	set_error_handler( 'topersia_log_error_handler', E_WARNING | E_USER_WARNING | E_DEPRECATED | E_USER_DEPRECATED );
}

function topersia_log_error_handler( $type, $message, $file = '', $line = 0 ) {

	$map = array(
		E_WARNING          => 'warning',
		E_USER_WARNING     => 'warning',
		E_DEPRECATED       => 'notice',
		E_USER_DEPRECATED  => 'notice',
	);

	topersia_log(
		$message,
		isset( $map[ $type ] ) ? $map[ $type ] : 'warning',
		'php',
		array(
			'file' => str_replace( ABSPATH, '', $file ),
			'line' => $line,
		)
	);

	return false; // مدیر خطای پیش‌فرض PHP هم کار خودش را بکند.
}

/**
 * هرس روزانه.
 *
 * دو سقف هم‌زمان: سن و تعداد. سقف زمانی برای سایت کم‌ترافیک کافی است؛
 * سقف تعدادی برای وقتی که چیزی خراب شده و در یک روز ده‌ها هزار سطر
 * ساخته است.
 */
add_action( 'topersia_log_prune', 'topersia_log_prune' );

function topersia_log_prune() {

	global $wpdb;

	if ( get_option( 'topersia_log_schema' ) !== TOPERSIA_LOG_SCHEMA ) {
		return;
	}

	$table = topersia_log_table();
	$days  = absint( topersia_setting( 'log_retain_days' ) );
	$max   = absint( topersia_setting( 'log_max_rows' ) );

	if ( $days ) {
		// phpcs:ignore WordPress.DB.PreparedSQL
		$wpdb->query( $wpdb->prepare( "DELETE FROM {$table} WHERE logged_at < DATE_SUB( NOW(), INTERVAL %d DAY )", $days ) );
	}

	if ( $max ) {

		// phpcs:ignore WordPress.DB.PreparedSQL
		$cut = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$table} ORDER BY id DESC LIMIT 1 OFFSET %d", $max ) );

		if ( $cut ) {
			// phpcs:ignore WordPress.DB.PreparedSQL
			$wpdb->query( $wpdb->prepare( "DELETE FROM {$table} WHERE id <= %d", $cut ) );
		}
	}
}

add_action( 'init', 'topersia_log_schedule' );


/* ==========================================================================
 * ۱۵-ب — خروجی لاگ و ثبت خطای مرورگر
 *
 * خروجی برای خوانده‌شدن ساخته می‌شود، نه برای وارد شدن به ابزار دیگر. سه
 * لایه دارد: محیط، خلاصهٔ آماری، و رویدادها بر پایهٔ شناسهٔ درخواست.
 *
 * چرا گروه‌بندی بر پایهٔ درخواست: یک خطای واحد معمولاً سه چهار سطر می‌سازد
 * و در فهرست خطی، سطرهای چند درخواست هم‌زمان در هم می‌روند.
 * ========================================================================== */

/** سقف سطرهای خروجی — بالاتر از این، فایل خوانده نمی‌شود و حافظه هم می‌برد. */
if ( ! defined( 'TOPERSIA_LOG_EXPORT_MAX' ) ) {
	define( 'TOPERSIA_LOG_EXPORT_MAX', 3000 );
}

/**
 * یک خط سربرگ خروجی.
 *
 * @param string $key   عنوان.
 * @param mixed  $value مقدار.
 * @return string
 */
function topersia_log_export_line( $key, $value ) {

	if ( is_bool( $value ) ) {
		$value = $value ? 'yes' : 'no';
	}

	if ( '' === $value || null === $value ) {
		$value = '—';
	}

	/* str_pad بایت می‌شمارد نه نویسه؛ با عنوان فارسی نقطه‌چین ناهم‌تراز می‌شود. */
	$key = (string) $key;
	$len = function_exists( 'mb_strlen' ) ? mb_strlen( $key, 'UTF-8' ) : strlen( $key );
	$pad = max( 1, 26 - $len );

	return $key . ' ' . str_repeat( '.', $pad ) . ' ' . $value . "\n";
}

/**
 * ساخت متن خروجی.
 *
 * @param array $filters level · channel · request · search
 * @return string
 */
function topersia_log_export_build( $filters = array() ) {

	global $wpdb;

	$table = topersia_log_table();

	$filters = wp_parse_args(
		$filters,
		array( 'level' => '', 'channel' => '', 'request' => '', 'search' => '' )
	);

	/* ── بند شرط، هم‌شکل با زبانهٔ لاگ ── */
	$where = array( '1=1' );
	$args  = array();

	if ( $filters['level'] ) {
		$where[] = 'level = %s';
		$args[]  = $filters['level'];
	}

	if ( $filters['channel'] ) {
		$where[] = 'channel = %s';
		$args[]  = $filters['channel'];
	}

	if ( $filters['request'] ) {
		$where[] = 'request_id = %s';
		$args[]  = $filters['request'];
	}

	if ( $filters['search'] ) {
		$where[] = '( message LIKE %s OR context LIKE %s OR source LIKE %s )';
		$like    = '%' . $wpdb->esc_like( $filters['search'] ) . '%';
		$args[]  = $like;
		$args[]  = $like;
		$args[]  = $like;
	}

	$clause = implode( ' AND ', $where );

	// phpcs:ignore WordPress.DB.PreparedSQL
	$matched = (int) ( $args
		? $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$table} WHERE {$clause}", $args ) )
		: $wpdb->get_var( "SELECT COUNT(*) FROM {$table}" ) );

	$q_args   = $args;
	$q_args[] = TOPERSIA_LOG_EXPORT_MAX;

	// phpcs:ignore WordPress.DB.PreparedSQL
	$rows = $wpdb->get_results(
		$wpdb->prepare( "SELECT * FROM {$table} WHERE {$clause} ORDER BY id DESC LIMIT %d", $q_args )
	);

	$rows = is_array( $rows ) ? $rows : array();

	/* ── لایهٔ یک: محیط ── */
	$out  = "=== ToPersia — خروجی لاگ رویدادها ===\n";
	$out .= topersia_log_export_line( 'تولید', gmdate( 'Y-m-d H:i' ) . ' UTC' );
	$out .= topersia_log_export_line( 'هستهٔ ToPersia', defined( 'TOPERSIA_CORE_VERSION' ) ? TOPERSIA_CORE_VERSION : '4.9.0' );
	$out .= topersia_log_export_line( 'WordPress', get_bloginfo( 'version' ) );
	$out .= topersia_log_export_line( 'PHP', PHP_VERSION );
	$out .= topersia_log_export_line( 'سایت', home_url( '/' ) );
	$out .= topersia_log_export_line( 'جدول', $table );
	$out .= topersia_log_export_line(
		'پیکربندی لاگ',
		( topersia_setting( 'log_enabled' ) ? 'فعال' : 'خاموش' )
			. ' · آستانه ' . topersia_setting( 'log_level' )
			. ' · PHP ' . ( topersia_setting( 'log_php_errors' ) ? 'on' : 'off' )
			. ' · JS ' . ( topersia_setting( 'log_js_errors' ) ? 'on' : 'off' )
			. ' · نگه‌داری ' . absint( topersia_setting( 'log_retain_days' ) ) . ' روز'
			. ' · سقف ' . absint( topersia_setting( 'log_max_rows' ) ) . ' سطر'
	);
	$out .= topersia_log_export_line(
		'فیلتر',
		'سطح=' . ( $filters['level'] ? $filters['level'] : 'همه' )
			. ' · کانال=' . ( $filters['channel'] ? $filters['channel'] : 'همه' )
			. ' · درخواست=' . ( $filters['request'] ? $filters['request'] : 'همه' )
			. ' · جست‌وجو=' . ( $filters['search'] ? $filters['search'] : '—' )
	);
	$out .= topersia_log_export_line( 'منطبق با فیلتر', $matched );
	$out .= topersia_log_export_line( 'صادرشده', count( $rows ) . ' (سقف ' . TOPERSIA_LOG_EXPORT_MAX . ')' );

	if ( $rows ) {
		$last  = $rows[0];
		$first = $rows[ count( $rows ) - 1 ];
		$out  .= topersia_log_export_line( 'بازهٔ زمانی', $first->logged_at . '  →  ' . $last->logged_at );
	}

	if ( ! $rows ) {
		return $out . "\nهیچ رویدادی با این فیلتر نیست.\n";
	}

	/* ── لایهٔ دو: خلاصه ── */
	$by_level   = array();
	$by_channel = array();
	$by_message = array();

	foreach ( $rows as $row ) {

		$lv = $row->level;
		$ch = $row->channel;

		$by_level[ $lv ]   = isset( $by_level[ $lv ] ) ? $by_level[ $lv ] + 1 : 1;
		$by_channel[ $ch ] = isset( $by_channel[ $ch ] ) ? $by_channel[ $ch ] + 1 : 1;

		$key = $lv . '/' . $ch . '|' . topersia_str_cut( $row->message, 110 );

		if ( isset( $by_message[ $key ] ) ) {
			$by_message[ $key ]['n']++;
		} else {
			$by_message[ $key ] = array( 'n' => 1, 'src' => $row->source );
		}
	}

	arsort( $by_level );
	arsort( $by_channel );
	uasort( $by_message, function ( $a, $b ) { return $b['n'] - $a['n']; } );

	$out .= "\n--- شمارش بر سطح ---\n";

	foreach ( $by_level as $lv => $n ) {
		$out .= topersia_log_export_line( $lv, $n );
	}

	$out .= "\n--- شمارش بر کانال ---\n";

	foreach ( $by_channel as $ch => $n ) {
		$out .= topersia_log_export_line( $ch, $n );
	}

	$out .= "\n--- پرتکرارترین پیام‌ها ---\n";

	$shown = 0;

	foreach ( $by_message as $key => $meta ) {

		if ( $shown >= 15 ) {
			break;
		}

		$parts = explode( '|', $key, 2 );

		$out .= sprintf(
			"%5d × %-16s %s\n              ↳ %s\n",
			$meta['n'],
			isset( $parts[0] ) ? $parts[0] : '',
			isset( $parts[1] ) ? $parts[1] : '',
			$meta['src']
		);

		$shown++;
	}

	/* ── لایهٔ سه: رویدادها، گروه‌بندی‌شده ── */
	$out .= "\n--- رویدادها — تازه‌ترین اول، گروه‌بندی بر پایهٔ درخواست ---\n";

	$groups = array();
	$order  = array();

	foreach ( $rows as $row ) {

		$rid = '' !== $row->request_id ? $row->request_id : 'بدون‌شناسه';

		if ( ! isset( $groups[ $rid ] ) ) {
			$groups[ $rid ] = array();
			$order[]        = $rid;
		}

		$groups[ $rid ][] = $row;
	}

	foreach ( $order as $rid ) {

		$items = $groups[ $rid ];
		$head  = $items[0];

		$out .= sprintf(
			"\n▼ درخواست %s · %s · کاربر %s · %s · %d رویداد\n",
			$rid,
			$head->logged_at,
			$head->user_id,
			'' !== $head->url ? $head->url : '—',
			count( $items )
		);

		foreach ( array_reverse( $items ) as $row ) {

			$out .= sprintf(
				"   #%s [%s] %s · %s\n        %s\n",
				$row->id,
				$row->level,
				$row->channel,
				'' !== $row->source ? $row->source : '—',
				topersia_str_cut( str_replace( array( "\r", "\n" ), ' ', $row->message ), 400 )
			);

			if ( '' !== (string) $row->context && '[]' !== (string) $row->context ) {
				$out .= '        ctx ' . topersia_str_cut( (string) $row->context, 600 ) . "\n";
			}
		}
	}

	return $out;
}

/**
 * تحویل فایل خروجی.
 *
 * روی admin_post می‌نشیند تا پیش از هر خروجی دیگری هدر بفرستد.
 *
 * @return void
 */
function topersia_log_export_handler() {

	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( 'دسترسی ندارید.' );
	}

	check_admin_referer( 'topersia_log_export' );

	$filters = array(
		'level'   => isset( $_GET['level'] ) ? sanitize_key( $_GET['level'] ) : '',
		'channel' => isset( $_GET['channel'] ) ? sanitize_key( $_GET['channel'] ) : '',
		'request' => isset( $_GET['request'] ) ? sanitize_key( $_GET['request'] ) : '',
		'search'  => isset( $_GET['search'] ) ? sanitize_text_field( wp_unslash( $_GET['search'] ) ) : '',
	);

	$body = topersia_log_export_build( $filters );
	$name = 'topersia-log-' . gmdate( 'Ymd-Hi' ) . '.txt';

	nocache_headers();
	header( 'Content-Type: text/plain; charset=utf-8' );
	header( 'Content-Disposition: attachment; filename="' . $name . '"' );
	header( 'Content-Length: ' . strlen( $body ) );

	echo $body; // phpcs:ignore WordPress.Security.EscapeOutput
	exit;
}
add_action( 'admin_post_topersia_log_export', 'topersia_log_export_handler' );

/**
 * گرفتن خطای مرورگر.
 *
 * فقط برای کاربر مدیر. دو دلیل: تزریق nonce در هر صفحه کش تمام‌صفحه را
 * می‌شکند، و بدون nonce هر بازدیدکننده‌ای می‌تواند جدول را پر کند.
 * عیب‌یابی هم همیشه با حساب مدیر انجام می‌شود.
 *
 * @return void
 */
function topersia_log_js_script() {

	if ( ! topersia_setting( 'log_enabled' ) || ! topersia_setting( 'log_js_errors' ) ) {
		return;
	}

	if ( ! function_exists( 'current_user_can' ) || ! current_user_can( 'manage_options' ) ) {
		return;
	}

	$url   = admin_url( 'admin-ajax.php' );
	$nonce = wp_create_nonce( 'topersia_log_js' );

	echo "<script>/* ToPersia js log */\n";
	echo "(function(){var U=" . wp_json_encode( $url ) . ",N=" . wp_json_encode( $nonce ) . ",sent=0;";
	echo "function send(m,s,l,c){if(sent>=10){return}sent++;try{var b=new FormData();";
	echo "b.append('action','topersia_log_js');b.append('_wpnonce',N);b.append('m',m);";
	echo "b.append('s',s||'');b.append('l',l||0);b.append('c',c||0);b.append('u',location.pathname+location.search);";
	echo "fetch(U,{method:'POST',body:b,credentials:'same-origin',keepalive:true})}catch(e){}}";
	echo "window.addEventListener('error',function(e){var t=e.target;";
	echo "if(t&&t!==window&&t.tagName){send('بارگذاری منبع شکست: '+t.tagName,String(t.src||t.href||''),0,0);return}";
	echo "send(String(e.message||'بدون پیام'),String(e.filename||''),e.lineno||0,e.colno||0)},true);";
	echo "window.addEventListener('unhandledrejection',function(e){";
	echo "send('وعدهٔ رسیدگی‌نشده: '+String((e.reason&&e.reason.message)||e.reason||''),'',0,0)});";
	echo "})();</script>\n";
}
add_action( 'wp_head', 'topersia_log_js_script', 2 );

/**
 * دریافت خطای مرورگر و نوشتنش در همان جدول.
 *
 * @return void
 */
function topersia_log_js_receive() {

	if ( ! current_user_can( 'manage_options' ) ) {
		wp_send_json_error( 'denied', 403 );
	}

	check_ajax_referer( 'topersia_log_js' );

	$message = isset( $_POST['m'] ) ? sanitize_text_field( wp_unslash( $_POST['m'] ) ) : '';

	if ( '' === $message ) {
		wp_send_json_error( 'empty', 400 );
	}

	$source = isset( $_POST['s'] ) ? esc_url_raw( wp_unslash( $_POST['s'] ) ) : '';
	$line   = isset( $_POST['l'] ) ? absint( $_POST['l'] ) : 0;
	$col    = isset( $_POST['c'] ) ? absint( $_POST['c'] ) : 0;
	$page   = isset( $_POST['u'] ) ? sanitize_text_field( wp_unslash( $_POST['u'] ) ) : '';

	topersia_log(
		topersia_str_cut( $message, 400 ),
		'error',
		'js',
		array(
			'file' => topersia_str_cut( $source, 300 ),
			'line' => $line,
			'col'  => $col,
			'page' => topersia_str_cut( $page, 200 ),
		)
	);

	topersia_log_flush();

	wp_send_json_success();
}
add_action( 'wp_ajax_topersia_log_js', 'topersia_log_js_receive' );

function topersia_log_schedule() {

	if ( ! wp_next_scheduled( 'topersia_log_prune' ) ) {
		wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', 'topersia_log_prune' );
	}
}

/**
 * نام متدهای در دسترس روی یک شیء رابطهٔ JetEngine.
 *
 * زبانهٔ تشخیص از این استفاده می‌کند تا API واقعی را گزارش کند، به‌جای
 * اینکه ما نامش را حدس بزنیم. همان روشی که برای کلیدهای واژه‌نامه جواب داد.
 */
function topersia_relation_methods( $relation ) {

	if ( ! is_object( $relation ) ) {
		return array();
	}

	$all  = get_class_methods( $relation );
	$keep = array();

	foreach ( (array) $all as $method ) {

		if ( preg_match( '/(rel|connect|delete|remove|update|attach|detach)/i', $method ) ) {
			$keep[] = $method;
		}
	}

	sort( $keep );

	return $keep;
}

/**
 * امضای یک متد روی شیء رابطه.
 *
 * زبانهٔ تشخیص از این استفاده می‌کند تا نشان دهد متد چند پارامتر می‌گیرد.
 * بدون آن، دانستنِ نام متد کافی نیست: اگر delete_rows به‌جای دو شناسه یک
 * آرایهٔ آرگومان بخواهد، فراخوانی ما یا کار نمی‌کند یا بدتر، دامنه‌اش از
 * یک یال فراتر می‌رود.
 */
function topersia_relation_signature( $relation, $method ) {

	if ( ! is_object( $relation ) || ! method_exists( $relation, $method ) ) {
		return '';
	}

	try {

		$reflection = new ReflectionMethod( $relation, $method );
		$parts      = array();

		foreach ( $reflection->getParameters() as $parameter ) {
			$parts[] = '$' . $parameter->getName() . ( $parameter->isOptional() ? '?' : '' );
		}

		return $method . '( ' . implode( ', ', $parts ) . ' )';

	} catch ( Throwable $error ) {

		return $method . '( ؟ )';
	}
}

/**
 * ساخت یک یال رابطه — با گارد.
 *
 * چرا با گارد: ساختار داخلی JetEngine مستند نیست و بین نسخه‌ها تغییر
 * می‌کند. فراخوانی متد ناموجود در PHP 8 خطای Error می‌دهد که اگر گرفته
 * نشود، کل ذخیرهٔ پست را می‌خواباند و ویرایشگر صفحهٔ سفید می‌بیند.
 *
 * @return bool آیا عملیات انجام شد.
 */
function topersia_relation_connect( $relation, $parent_id, $child_id ) {

	if ( ! is_object( $relation ) ) {
		return false;
	}

	foreach ( array( 'update', 'set_relation', 'add_relation' ) as $method ) {

		if ( ! method_exists( $relation, $method ) ) {
			continue;
		}

		try {

			$relation->$method( $parent_id, $child_id );

			return true;

		} catch ( Throwable $error ) {

			topersia_log( "ساخت یال با {$method} شکست خورد: " . $error->getMessage(), 'error', 'relation', array( 'parent' => $parent_id, 'child' => $child_id ) );

			return false;
		}
	}

	topersia_log( 'ساخت یال ناممکن — هیچ متد شناخته‌شده‌ای روی شیء رابطه نبود', 'error', 'relation', array( 'parent' => $parent_id, 'child' => $child_id ) );

	return false;
}

/**
 * برداشتن یک یال رابطه — با گارد.
 *
 * این تابع پس از یک خطای مرگبار واقعی نوشته شد. مسیر حذف یال از نسخهٔ
 * ۱.۰.۰ در کد بود ولی هرگز اجرا نشده بود، چون تا آن روز هیچ توقفی از هیچ
 * مسیری برداشته نشده بود. اولین باری که یک ردیف بازنشسته شد، ذخیرهٔ پست
 * خوابید.
 *
 * سومین بار در یک جلسه که همین الگو تکرار شد: کدی که اجرا نمی‌شود
 * «آزموده» نیست، فقط خاموش است. پس هر فراخوانی به API افزونهٔ ثالث باید
 * گارد داشته باشد، نه فقط آن‌هایی که به‌نظر خطرناک می‌رسند.
 *
 * @return bool آیا عملیات انجام شد.
 */
function topersia_relation_disconnect( $relation, $parent_id, $child_id ) {

	if ( ! is_object( $relation ) ) {
		return false;
	}

	/*
	 * ترتیب نامزدها بر پایهٔ API واقعی JetEngine 3.8.13.2 که در محیط زنده
	 * گزارش شد: delete_rows متد درست است. سه نام دیگر برای سازگاری با
	 * نسخه‌های احتمالی آینده و گذشته می‌مانند.
	 *
	 * cleanup_relation عمداً در این فهرست نیست. نامش می‌گوید کل رابطه را
	 * پاک می‌کند نه یک یال را؛ صدا زدنش به‌جای حذف یک پیوند، همهٔ یال‌های
	 * آن رابطه را در کل پروژه از بین می‌برد — بی‌صدا و بدون بازگشت.
	 */
	foreach ( array( 'delete_rows', 'delete_rel', 'remove_relation', 'delete_relation' ) as $method ) {

		if ( ! method_exists( $relation, $method ) ) {
			continue;
		}

		try {

			$relation->$method( $parent_id, $child_id );

			return true;

		} catch ( Throwable $error ) {

			topersia_log( "برداشتن یال با {$method} شکست خورد: " . $error->getMessage(), 'error', 'relation', array( 'parent' => $parent_id, 'child' => $child_id ) );

			return false;
		}
	}

	topersia_log( 'برداشتن یال ناممکن — هیچ متد شناخته‌شده‌ای روی شیء رابطه نبود', 'error', 'relation', array( 'parent' => $parent_id, 'child' => $child_id ) );

	return false;
}

/**
 * رشتهٔ شناسه‌ها را به آرایهٔ عددی یکتا تبدیل می‌کند.
 *
 * جداکننده‌های پذیرفته: ویرگول لاتین، ویرگول فارسی، فاصله، خط جدید.
 */
function topersia_parse_ids( $raw ) {

	if ( empty( $raw ) ) {
		return array();
	}

	$parts = preg_split( '/[\s,،]+/u', (string) $raw, -1, PREG_SPLIT_NO_EMPTY );
	$ids   = array();

	foreach ( $parts as $part ) {

		$id = absint( $part );

		if ( $id ) {
			$ids[] = $id;
		}
	}

	return array_values( array_unique( $ids ) );
}

/**
 * ردیف‌های فعال یک Repeater را برمی‌گرداند — P5-D121.
 *
 * چرا لازم است: آزمون P5-T008 ثابت کرد WPML ردیف‌های Repeater را با شمارهٔ
 * موقعیت دنبال می‌کند (field-<key>-0-item-N-<sub>). حذف یک ردیف، ترجمهٔ همهٔ
 * ردیف‌های بعدی را یک واحد جابه‌جا می‌کند — خاموش و در هر نُه زبان هم‌زمان.
 *
 * بنابراین ردیف هرگز حذف نمی‌شود؛ زیرفیلد <پیشوند>_row_status آن به
 * not_applicable تغییر می‌کند و این تابع آن را از رندر بیرون می‌گذارد.
 *
 * قطبیت عمدی: فیلتر «هر چیزی جز not_applicable» است، نه «فقط active».
 * مقدار خالی یعنی فعال. شکست این مکانیزم باید به سمت نمایش باشد نه
 * پنهان‌سازی — محتوای اضافه دیده و اصلاح می‌شود، محتوای ناپدید نه.
 *
 * @param mixed  $rows       آرایهٔ ردیف‌های Repeater، معمولاً خروجی get_post_meta.
 * @param string $status_key کلید وضعیت. خالی بگذارید تا خودکار تشخیص داده شود.
 *
 * @return array ردیف‌های فعال، با ترتیب اصلی.
 */
function topersia_active_rows( $rows, $status_key = '' ) {

	if ( ! is_array( $rows ) ) {
		return array();
	}

	$out = array();

	foreach ( $rows as $row ) {

		if ( ! is_array( $row ) ) {
			continue;
		}

		$status = '';

		if ( $status_key && isset( $row[ $status_key ] ) ) {

			$status = $row[ $status_key ];

		} else {

			// تشخیص خودکار کلید — نیازی به پیکربندی به‌ازای هر Repeater نیست.
			foreach ( $row as $key => $value ) {

				if ( '_row_status' === substr( $key, -11 ) ) {
					$status = $value;
					break;
				}
			}
		}

		if ( 'not_applicable' === $status ) {
			continue;
		}

		$out[] = $row;
	}

	return $out;
}

/**
 * هر شناسه را به معادلِ زبان پیش‌فرض برمی‌گرداند.
 *
 * فیلد ترتیب کلاس Copy دارد و ممکن است WPML شناسه‌ها را نگاشت کرده باشد یا
 * نکرده باشد. برای تطبیقِ ترتیب با یادداشت، به کلیدی نیاز داریم که در هر
 * زبان یکسان باشد — و آن، شناسهٔ نسخهٔ فارسی است.
 */
function topersia_src_id( $id ) {

	$id        = absint( $id );
	$post_type = get_post_type( $id );

	if ( ! $post_type || ! has_filter( 'wpml_default_language' ) ) {
		return $id;
	}

	$default = apply_filters( 'wpml_default_language', null );
	$origin  = apply_filters( 'wpml_object_id', $id, $post_type, true, $default );

	return $origin ? absint( $origin ) : $id;
}

/**
 * یک متای موجودیت را می‌خواند — همیشه از راه هستهٔ وردپرس.
 *
 * تا نسخهٔ ۴.۱.۳ این تابع اول jet_engine()->listings->data->get_meta() را
 * صدا می‌زد. آن مسیر حذف شد، به دو دلیل:
 *
 * ۱ — گاردش ناقص بود. فقط isset( jet_engine()->listings ) بررسی می‌شد، نه
 *     خودِ ->data و نه وجود متد. در PHP 8 فراخوانی متد روی null خطای
 *     مرگبار است، نه هشدار.
 *
 * ۲ — و مهم‌تر: این کد از نسخهٔ ۲.۰.۰ نوشته شده بود ولی هرگز اجرا نمی‌شد،
 *     چون متغیرهای سفارشی Rank Math ثبت می‌شدند و هیچ‌وقت به‌کار نمی‌رفتند
 *     (همان نقص F-13). نسخهٔ ۴.۱.۰ دو فیلتر frontend اضافه کرد و برای
 *     نخستین بار آن مسیر را زنده کرد — یعنی کدی که هرگز روی محیط زنده
 *     آزموده نشده بود، یک‌باره روی هر صفحهٔ موجودیت اجرا شد.
 *
 * فیلدهایی که اینجا خوانده می‌شوند — meta_title، meta_description،
 * short_summary، ai_summary — همه متن ساده‌اند. get_post_meta برایشان
 * کافی است و هیچ چیزی از لایهٔ JetEngine لازم ندارند. یک وابستگی که سود
 * نمی‌دهد ولی می‌تواند کل سایت را بخواباند، باید حذف شود.
 */
function topersia_entity_meta( $post_id, $key ) {

	$post_id = absint( $post_id );

	if ( ! $post_id || ! is_string( $key ) || '' === $key ) {
		return '';
	}

	$value = get_post_meta( $post_id, $key, true );

	if ( is_array( $value ) || is_object( $value ) ) {
		return '';
	}

	return trim( wp_strip_all_tags( (string) $value ) );
}

/**
 * گاردِ اجرای یک‌باره در هر درخواست، به‌ازای هر پست و هر کلید.
 *
 * تابع اسلاگ داخل خودش wp_update_post صدا می‌زند که save_post را دوباره
 * فایر می‌کند. بدون این گارد، منطق P9 در هر ذخیره دو بار اجرا می‌شود — که
 * خطا نمی‌دهد ولی کوئری اضافه می‌زند و لاگ دیتابیس را شلوغ می‌کند.
 */
function topersia_run_once( $key, $post_id ) {

	static $done = array();

	$signature = $key . ':' . $post_id;

	if ( isset( $done[ $signature ] ) ) {
		return false;
	}

	$done[ $signature ] = true;

	return true;
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۲ — اسلاگ لاتین از روی نام انگلیسیِ کیوریت‌شده
 * ═══════════════════════════════════════════════════════════════════════
 * چرا این مکانیزم و نه ترانسلیترهٔ خودکار (ICU / Cyr-To-Lat):
 * تست تجربی نشان داد ترانسلیترهٔ صوتی نتایج غلط می‌سازد — «ایران» → ayran،
 * «تخت جمشید» → tkht-jmshyd. اما این پروژه از قبل برای هر موجودیت یک فیلد
 * نام انگلیسیِ صحیح و انسانی دارد (official_name_en در G1، name_en در بقیه،
 * page_title در D1–D6) — همان منبع درست را مستقیم برای اسلاگ به کار می‌بریم.
 *
 * چون این فیلدها کلاس ترجمهٔ Copy دارند، هر سه نسخهٔ زبانی به یک ورودی
 * می‌رسند و خودبه‌خود یک اسلاگ یکسان می‌سازند.
 *
 * قاعدهٔ ایمنی: فقط وقتی اسلاگ فعلی هنوز لاتین/تنظیم‌شده نیست دست می‌زنیم.
 * یک اسلاگ لاتینِ موجود هرگز بازنویسی نمی‌شود؛ یعنی هیچ URL منتشرشده‌ای
 * بی‌خبر عوض نمی‌شود.
 *
 * نکتهٔ فنی (باگ نسخهٔ ۱.۰.۰): هستهٔ وردپرس برای عنوان‌های غیرلاتین، متن را
 * درصد-کدگذاری می‌کند و همان رشتهٔ ASCII-مانند را در post_name ذخیره می‌کند
 * («ایران» → %d8%a7%db%8c%d8%b1%d8%a7%d9%86). این رشته از نظر preg_match
 * ساده «کاملاً ASCII» به نظر می‌رسد. برای همین تشخیص «اسلاگ سالم» باید
 * صریحاً با الگوی مجاز وردپرس انجام شود، نه با «نبودِ کاراکتر غیرلاتین».
 */
add_action( 'save_post', 'topersia_slug_from_english_name', 999, 3 );

function topersia_slug_from_english_name( $post_id, $post, $update ) {

	static $running = false;

	if ( $running ) {
		return; // جلوگیری از حلقهٔ بازگشتی هنگام فراخوانی wp_update_post.
	}

	if ( wp_is_post_autosave( $post_id ) || wp_is_post_revision( $post_id ) ) {
		return;
	}

	if ( ! in_array( $post->post_status, array( 'publish', 'draft', 'pending', 'future' ), true ) ) {
		return;
	}

	// اسلاگ سالمِ موجود را دست نمی‌زنیم. رشته‌های درصد-کدشده عمداً از این
	// الگو رد نمی‌شوند، چون شامل کاراکتر % هستند.
	if ( ! empty( $post->post_name )
		&& preg_match( '/^[a-z0-9_-]+$/', $post->post_name )
		&& ! is_numeric( $post->post_name )
	) {
		return;
	}

	// ترتیب اولویت منبع نام انگلیسی.
	$english_name = get_post_meta( $post_id, 'official_name_en', true );

	if ( empty( $english_name ) ) {
		$english_name = get_post_meta( $post_id, 'name_en', true );
	}

	if ( empty( $english_name ) ) {
		$english_name = get_post_meta( $post_id, 'page_title', true );
	}

	if ( empty( $english_name ) ) {
		return; // فیلد انگلیسی هنوز پر نشده — در ذخیرهٔ بعدی اصلاح می‌شود.
	}

	$new_slug = sanitize_title( $english_name );

	if ( empty( $new_slug ) || $new_slug === $post->post_name ) {
		return;
	}

	$running = true;

	wp_update_post(
		array(
			'ID'        => $post_id,
			'post_name' => $new_slug,
		)
	);

	$running = false;
}

/**
 * اجرای مجدد منطق اسلاگ پس از تکمیل ترجمه.
 *
 * در ذخیرهٔ عادی ادمین، save_post همان لحظه فایر می‌شود. اما وقتی ترجمه از
 * طریق ویرایشگر ترجمه کامل می‌شود، طبق تأیید رسمی پشتیبانی WPML، save_post
 * همیشه به همان شکل فایر نمی‌شود — و حتی اگر فایر شود، ممکن است مقدار
 * فیلدهای Copy مثل name_en هنوز از زبان مبنا سینک نشده باشد، پس تابع بالا
 * زود خارج می‌شود و اسلاگ اصلاح‌نشده می‌ماند. این دقیقاً روی نسخهٔ عربی
 * «شیراز» مشاهده شد.
 */
add_action(
	'wpml_pro_translation_completed',
	function ( $post_id ) {

		$post = get_post( $post_id );

		if ( $post ) {
			topersia_slug_from_english_name( $post_id, $post, true );
		}
	}
);

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۳ — شناسهٔ یکتای موجودیت (entity_uid)
 * ═══════════════════════════════════════════════════════════════════════
 * قالب: https://topersia.com/e/{نوع}/{اسلاگ}
 *
 * چرا بخش «نوع» لازم است: وردپرس یکتایی اسلاگ را به‌ازای هر نوع پست بررسی
 * می‌کند، نه سراسری. پس استان اصفهان و شهر اصفهان هر دو post_name برابر
 * isfahan می‌گیرند. بدون بخش نوع، هر دو شناسهٔ یکسان می‌گرفتند و در JSON-LD
 * دو موجودیت متفاوت با یک @id ظاهر می‌شدند.
 *
 * این شناسه پس از ساخته‌شدن هرگز بازنویسی نمی‌شود — شناسه‌ای که با تغییر
 * اسلاگ عوض شود، پایدار نیست.
 *
 * افزونهٔ topersia-schema این مقدار را می‌خواند ولی هرگز نمی‌نویسد.
 */
add_action( 'save_post', 'topersia_fill_entity_uid', 1000, 3 );

function topersia_fill_entity_uid( $post_id, $post, $update ) {

	if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}

	if ( ! topersia_is_entity( $post->post_type ) ) {
		return;
	}

	if ( in_array( $post->post_status, array( 'auto-draft', 'trash' ), true ) ) {
		return;
	}

	// شناسه در همهٔ زبان‌ها یکسان است — فقط روی نسخهٔ فارسی ساخته می‌شود.
	if ( ! topersia_is_default_language( $post_id ) ) {
		return;
	}

	// ثابت است — اگر یک‌بار ساخته شد، هرگز بازنویسی نمی‌شود.
	if ( ! empty( get_post_meta( $post_id, 'entity_uid', true ) ) ) {
		return;
	}

	// اسلاگ را تازه بخوان، چون هوک تولید اسلاگ در اولویت ۹۹۹ اجرا شده.
	$slug = get_post_field( 'post_name', $post_id );

	if ( empty( $slug ) ) {
		return;
	}

	// اگر اسلاگ هنوز لاتین نشده، صبر کن تا ذخیرهٔ بعدی.
	if ( ! preg_match( '/^[a-z0-9_-]+$/', $slug ) ) {
		return;
	}

	$type_object = get_post_type_object( $post->post_type );

	if ( $type_object && ! empty( $type_object->rewrite['slug'] ) ) {
		$segment = $type_object->rewrite['slug'];
	} else {
		$segment = str_replace( 'tp_', '', $post->post_type );
	}

	update_post_meta(
		$post_id,
		'entity_uid',
		TOPERSIA_UID_BASE . '/' . $segment . '/' . $slug
	);
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۴ — هم‌سان‌سازی اسلاگ ترجمه‌ها با زبان اصلی
 * ═══════════════════════════════════════════════════════════════════════
 * WPML اسلاگ ترجمه را از عنوان همان زبان می‌سازد («The Silk Road in Iran»
 * → the-silk-road-in-iran) و چون نتیجه یک اسلاگ لاتین سالم است، هوک تولید
 * اسلاگ در اولویت ۹۹۹ آن را رد می‌کند. حاصل، واگرایی اسلاگ بین زبان‌هاست
 * بدون هیچ سود سئویی، چون این پروژه در هر سه زبان اسلاگ لاتین می‌سازد نه
 * اسلاگ بومی.
 */

/** وضعیت اجرای هم‌سان‌سازی — تا فیلتر یکتاسازی اسلاگ بداند کِی کنار بکشد. */
function topersia_slug_sync_state( $set = null ) {

	static $on = false;

	if ( null !== $set ) {
		$on = (bool) $set;
	}

	return $on;
}

/**
 * وردپرس اسلاگ تکراری را با پسوند -2 یکتا می‌کند. اینجا اجازه می‌دهیم
 * نسخهٔ ترجمه‌شده دقیقاً همان اسلاگ اصل را بگیرد — چون WPML زبان را در
 * جدول جدا نگه می‌دارد و مسیر با پیشوند زبان از هم تفکیک می‌شود.
 */
add_filter( 'wp_unique_post_slug', 'topersia_keep_translated_slug', 10, 6 );

function topersia_keep_translated_slug( $slug, $post_id, $post_status, $post_type, $post_parent, $original_slug ) {
	return topersia_slug_sync_state() ? $original_slug : $slug;
}

/** اسلاگ هر نسخهٔ ترجمه‌شده را با نسخهٔ زبان پیش‌فرض یکسان می‌کند. */
add_action( 'save_post', 'topersia_sync_translated_slug', 1001, 3 );

function topersia_sync_translated_slug( $post_id, $post, $update ) {

	static $running = false;

	if ( $running ) {
		return;
	}

	if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}

	if ( ! topersia_is_entity( $post->post_type ) ) {
		return;
	}

	if ( in_array( $post->post_status, array( 'auto-draft', 'trash' ), true ) ) {
		return;
	}

	// فقط روی نسخه‌های ترجمه‌شده اجرا شود، نه روی زبان پیش‌فرض.
	if ( topersia_is_default_language( $post_id ) ) {
		return;
	}

	$default = apply_filters( 'wpml_default_language', null );
	$origin  = apply_filters( 'wpml_object_id', $post_id, $post->post_type, false, $default );

	if ( ! $origin || absint( $origin ) === absint( $post_id ) ) {
		return;
	}

	$origin_slug = get_post_field( 'post_name', $origin );

	if ( empty( $origin_slug ) || ! preg_match( '/^[a-z0-9_-]+$/', $origin_slug ) ) {
		return; // اصل هنوز اسلاگ لاتین سالم ندارد — بعداً اصلاح می‌شود.
	}

	if ( get_post_field( 'post_name', $post_id ) === $origin_slug ) {
		return; // از قبل یکسان است.
	}

	$running = true;

	topersia_slug_sync_state( true );

	wp_update_post(
		array(
			'ID'        => $post_id,
			'post_name' => $origin_slug,
		)
	);

	topersia_slug_sync_state( false );

	$running = false;
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۵ — P5-D018: G4 (tp_county) گراف‌فقط
 * ═══════════════════════════════════════════════════════════════════════
 * شهرستان طبق CA-G-D002 / TA-REQ-D002 صفحهٔ مستقل نمی‌گیرد؛ فقط به‌عنوان
 * گرهٔ واسط در زنجیرهٔ گراف (G5→G4→G3→G1) زنده می‌ماند. بازدیدکننده‌ای که
 * مستقیماً به URL شهرستان برسد — لینک قدیمی، ایندکس اشتباه، حدس URL —
 * باید ۳۰۱ به استان والد برود، نه ۴۰۴ و نه صفحهٔ خالی.
 */

/**
 * یافتن رابطهٔ G3–G4 با اطمینان.
 *
 * چرا این تابع لازم شد: در بازسازی فاز ۵، شناسهٔ این رابطه از ۷ به ۷۲ تغییر
 * کرد ولی ثابت قدیمی در کد ماند و ریدایرکت بی‌صدا به صفحهٔ اصلی می‌افتاد،
 * بدون هیچ خطایی. حالا اول شناسه را امتحان می‌کنیم و اگر جواب نداد، از روی
 * نام می‌گردیم. نتیجه در حافظهٔ همان درخواست کش می‌شود.
 *
 * زبانهٔ تشخیص پنل مدیریت همین وضعیت را چشمی گزارش می‌دهد.
 */
function topersia_get_g3_g4_relation() {

	static $cached = null;

	if ( null !== $cached ) {
		return $cached;
	}

	$cached = false;

	if ( ! function_exists( 'jet_engine' ) || ! isset( jet_engine()->relations ) ) {
		return $cached;
	}

	// مسیر اول: شناسهٔ ثابت.
	$relation = topersia_relation( TOPERSIA_REL_PROVINCE_COUNTY );

	if ( $relation ) {
		$cached = $relation;
		return $cached;
	}

	// مسیر دوم: جست‌وجو بر اساس نام — وقتی شناسه عوض شده باشد.
	if ( method_exists( jet_engine()->relations, 'get_relations' ) ) {

		foreach ( (array) jet_engine()->relations->get_relations() as $item ) {

			$name = is_object( $item ) && method_exists( $item, 'get_arg' )
				? $item->get_arg( 'name' )
				: null;

			if ( $name && TOPERSIA_REL_NAME_PROVINCE_COUNTY === $name ) {
				$cached = $item;
				return $cached;
			}
		}
	}

	return $cached;
}

/** ریدایرکت ۳۰۱ صفحات شهرستان به استان والد. */
add_action(
	'template_redirect',
	function () {

		if ( is_admin() || ! is_singular( 'tp_county' ) ) {
			return;
		}

		$target   = home_url( '/' ); // fallback ایمن — با WPML به خانهٔ همان زبان می‌رود.
		$relation = topersia_get_g3_g4_relation();

		if ( $relation ) {

			$parents = $relation->get_parents( get_the_ID(), 'ids' );

			if ( ! empty( $parents ) ) {

				$parent_id = is_array( $parents ) ? reset( $parents ) : $parents;
				$permalink = get_permalink( $parent_id );

				if ( $permalink ) {
					$target = $permalink;
				}
			}
		}

		wp_redirect( $target, 301 );
		exit;
	}
);

/** حذف tp_county از سایت‌مپ — صفحات گراف‌فقط نباید ایندکس شوند. */
add_filter(
	'wp_sitemaps_post_types',
	function ( $post_types ) {
		unset( $post_types['tp_county'] );
		return $post_types;
	}
);

/**
 * لایهٔ دوم محافظت: هدر noindex روی صفحات G4.
 *
 * ریدایرکت فقط وقتی کار می‌کند که رابطهٔ والد وجود داشته باشد. اگر رکوردی
 * هنوز به استان وصل نشده باشد، کاربر به صفحهٔ اصلی می‌رود ولی خزنده ممکن
 * است پیش از ریدایرکت چیزی را کش کند.
 */
add_action(
	'template_redirect',
	function () {

		if ( ! is_admin() && is_singular( 'tp_county' ) && ! headers_sent() ) {
			header( 'X-Robots-Tag: noindex, follow', true );
		}
	},
	1
);

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۶ — P9: مسیرهای گردشگری
 * ═══════════════════════════════════════════════════════════════════════
 * معماری (تصمیم‌های P5-D068 تا P5-D076):
 *
 * ترتیب توقف‌ها در فیلد route_stops_order روی خودِ مسیر ذخیره می‌شود — یک
 * فیلد Copy با فهرست مرتب شناسه‌ها. متای یال رابطه استفاده نمی‌شود، چون
 * جدول wp_jet_rel_*_meta ستون زبان ندارد و WPML هیچ قلابی به آن ندارد.
 *
 * یادداشت هر توقف در Repeater جداگانه (route_stop_notes) است که با شناسهٔ
 * توقف کلید می‌خورد، نه با موقعیت ردیف.
 *
 * رابطه‌های واقعی R03 از فیلد ترتیب مشتق می‌شوند — یک منبع حقیقت، و رابطه
 * به‌عنوان ایندکس کوئری معکوس («کدام مسیرها از این شهر می‌گذرند»).
 *
 * بازنشستگی ردیف (P5-D121): ردیف یادداشت هرگز حذف نمی‌شود؛ زیرفیلد
 * stop_row_status آن به not_applicable تغییر می‌کند.
 */

/**
 * نگاشت نوع پست مقصد به شناسهٔ رابطهٔ R03.
 *
 * tp_province عمداً اینجا نیست. استان از فهرست ترتیب نمی‌آید — از زنجیرهٔ
 * جغرافیایی مشتق می‌شود (بخش ۷) یا دستی وصل می‌شود.
 */
function topersia_p9_rel_map() {

	return array(
		'tp_city'    => TOPERSIA_REL_ROUTE_CITY,
		'tp_village' => TOPERSIA_REL_ROUTE_VILLAGE,
		'tp_island'  => TOPERSIA_REL_ROUTE_ISLAND,
	);
}

/** فیلد ترتیب را می‌خواند و رابطه‌های واقعی R03 را از روی آن بازسازی می‌کند. */
add_action( 'save_post_tp_route', 'topersia_p9_sync_relations', 20, 3 );

function topersia_p9_sync_relations( $post_id, $post, $update ) {

	if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}

	if ( ! topersia_run_once( 'p9_relations', $post_id ) ) {
		return;
	}

	if ( ! function_exists( 'jet_engine' ) || ! isset( jet_engine()->relations ) ) {
		return;
	}

	if ( ! topersia_is_default_language( $post_id ) ) {
		return;
	}

	$ids = topersia_parse_ids( get_post_meta( $post_id, 'route_stops_order', true ) );
	$map = topersia_p9_rel_map();

	// شناسه‌ها را بر اساس نوع پست گروه‌بندی کن.
	$wanted = array();

	foreach ( $ids as $id ) {

		$post_type = get_post_type( $id );

		if ( $post_type && isset( $map[ $post_type ] ) ) {
			$wanted[ $map[ $post_type ] ][] = $id;
		}
	}

	foreach ( $map as $post_type => $relation_id ) {

		$relation = topersia_relation( $relation_id );

		if ( ! $relation ) {
			continue;
		}

		$current = $relation->get_children( $post_id, 'ids' );
		$current = is_array( $current ) ? array_map( 'absint', $current ) : array();
		$target  = isset( $wanted[ $relation_id ] ) ? $wanted[ $relation_id ] : array();

		foreach ( array_diff( $target, $current ) as $add ) {
			topersia_relation_connect( $relation, $post_id, $add );
		}

		foreach ( array_diff( $current, $target ) as $remove ) {
			topersia_relation_disconnect( $relation, $post_id, $remove );
		}
	}
}

/**
 * توقف‌های مسیر را مرتب و نگاشت‌شده به زبان جاری برمی‌گرداند.
 *
 * نگاشت با wpml_object_id بی‌قید و شرط انجام می‌شود، مستقل از این‌که WPML
 * خودش شناسه‌ها را نگاشت کرده باشد یا نه. اگر کرده باشد، این عملیات بی‌اثر
 * است؛ اگر نکرده باشد، ما درستش می‌کنیم. وابستگی به رفتار تأییدنشده صفر.
 *
 * @param int|null $route_id شناسهٔ مسیر. خالی یعنی پست جاری.
 *
 * @return array فهرستی از آرایه‌ها با کلیدهای: position, id, title, url, note
 */
function topersia_p9_stops( $route_id = null ) {

	$route_id = $route_id ? absint( $route_id ) : get_the_ID();

	if ( ! $route_id ) {
		return array();
	}

	$ids   = topersia_parse_ids( get_post_meta( $route_id, 'route_stops_order', true ) );
	$notes = topersia_active_rows( get_post_meta( $route_id, 'route_stop_notes', true ) );

	// یادداشت‌ها را با کلید زبان‌مستقل ایندکس کن.
	$note_map = array();

	foreach ( $notes as $row ) {

		if ( empty( $row['stop_id'] ) ) {
			continue;
		}

		$key              = topersia_src_id( $row['stop_id'] );
		$note_map[ $key ] = isset( $row['stop_note'] ) ? $row['stop_note'] : '';
	}

	$out      = array();
	$position = 1;

	foreach ( $ids as $raw_id ) {

		$post_type = get_post_type( $raw_id );

		if ( ! $post_type ) {
			continue;
		}

		$key  = topersia_src_id( $raw_id );
		$view = apply_filters( 'wpml_object_id', $raw_id, $post_type, true );

		if ( ! $view || 'publish' !== get_post_status( $view ) ) {
			continue;
		}

		$out[] = array(
			'position' => $position ++,
			'id'       => absint( $view ),
			'title'    => get_the_title( $view ),
			'url'      => get_permalink( $view ),
			'note'     => isset( $note_map[ $key ] ) ? $note_map[ $key ] : '',
		);
	}

	return $out;
}

/**
 * هشدار برای یادداشت‌هایی که توقف متناظرشان از فهرست ترتیب حذف شده.
 *
 * حذف یک توقف از فهرست ترتیب، ردیف یادداشتش را حذف نمی‌کند. یادداشت یتیم
 * می‌ماند و هرگز نمایش داده نمی‌شود — یک شکست خاموش.
 *
 * ردیف‌های عمداً بازنشسته (P5-D121) از این بررسی کنار گذاشته می‌شوند، وگرنه
 * هشدار ویرایشگر را وسوسه می‌کرد ردیفی را حذف کند که نباید حذف شود.
 */
add_action( 'admin_notices', 'topersia_p9_orphan_notice' );

function topersia_p9_orphan_notice() {

	if ( ! function_exists( 'get_current_screen' ) ) {
		return;
	}

	$screen = get_current_screen();

	if ( ! $screen || 'tp_route' !== $screen->post_type || 'post' !== $screen->base ) {
		return;
	}

	$post_id = isset( $_GET['post'] ) ? absint( $_GET['post'] ) : 0;

	if ( ! $post_id || ! current_user_can( 'edit_post', $post_id ) ) {
		return;
	}

	$ids   = topersia_parse_ids( get_post_meta( $post_id, 'route_stops_order', true ) );
	$notes = topersia_active_rows( get_post_meta( $post_id, 'route_stop_notes', true ) );

	$orphans = array();

	foreach ( $notes as $row ) {

		if ( empty( $row['stop_id'] ) ) {
			continue;
		}

		if ( ! in_array( absint( $row['stop_id'] ), $ids, true ) ) {
			$orphans[] = absint( $row['stop_id'] );
		}
	}

	if ( $orphans ) {
		printf(
			'<div class="notice notice-warning"><p>%s <code>%s</code></p></div>',
			esc_html__( 'یادداشت بدون توقف متناظر — این شناسه‌ها در فهرست ترتیب نیستند:', 'topersia-core' ),
			esc_html( implode( '، ', $orphans ) )
		);
	}
}

/* ───────────────────────────────────────────────────────────────────────
 *  بخش ۶-ب — یال‌های مشتق‌شده از زیرفیلد ریپیتر (P5-D114)
 * ───────────────────────────────────────────────────────────────────────
 * همان اصل بخش ۶، در شکلی عمومی‌تر: یک زیرفیلد ریپیتر شناسهٔ پست مقصد را
 * نگه می‌دارد، و یال واقعی رابطه از روی آن ساخته می‌شود. فیلد منبع حقیقت
 * است؛ رابطه فقط ایندکس کوئری معکوس است.
 *
 * چرا این الگو و نه رابطهٔ مستقیم: هر ردیف ریپیتر داده‌ای همراه خودش دارد
 * (اینجا یادداشت منطقه‌ای) که باید ترجمه‌پذیر باشد. آزمون P5-T003 ثابت کرد
 * متای یال رابطه با WPML کار نمی‌کند، چون جدول یال ستون زبان ندارد. پس
 * داده در ریپیتر می‌ماند و رابطه از آن مشتق می‌شود.
 *
 * چرا جدا از بخش ۶ و نه ادغام با آن: شکل مسئله فرق دارد. P9 یک فیلد مسطح
 * دارد که بسته به نوع پستِ مقصد به سه رابطهٔ مختلف می‌رود. اینجا یک زیرفیلد
 * ریپیتر است که به یک رابطهٔ مشخص می‌رود. ادغام اجباری این دو، هر دو را
 * پیچیده‌تر می‌کرد بدون اینکه چیزی ساده شود.
 *
 * افزودن مورد تازه: فقط یک بلوک به topersia_derived_edges_map() اضافه کن.
 */

/**
 * نگاشت نوع پست به یال‌هایی که باید از ریپیترهایش مشتق شوند.
 *
 * کلیدهای هر بلوک:
 *   repeater   نام فیلد ریپیتر روی همین نوع پست
 *   id_field   زیرفیلدی که شناسهٔ پست مقصد را نگه می‌دارد
 *   relation   شناسهٔ رابطهٔ JetEngine
 *   expect     نوع پستی که شناسه باید به آن تعلق داشته باشد
 *   role       نقش پستِ جاری در رابطه: 'child' یا 'parent'
 *
 * role چرا لازم است: در رابطهٔ applies_g3_p2 والد استان است و فرزند ارز.
 * پس شناسه‌ای که در ریپیترِ ارز نوشته می‌شود، والد است و خودِ پست ارز فرزند.
 * در P9 برعکس است. اشتباه گرفتن جهت، یال را در جهت وارونه می‌سازد و
 * کوئری معکوس هرگز جواب نمی‌دهد — بدون هیچ خطایی.
 */
function topersia_derived_edges_map() {

	$map = array(

		/* P2 — ارز و روش‌های پرداخت · یادداشت‌های استانی */
		'tp_currency' => array(
			array(
				'repeater' => 'regional_notes',
				'id_field' => 'rn_g3_id',
				'relation' => TOPERSIA_REL_PROVINCE_CURRENCY,
				'expect'   => 'tp_province',
				'role'     => 'child',
			),
		),
	);

	return apply_filters( 'topersia_derived_edges_map', $map );
}

/**
 * شناسه‌های معتبرِ مقصد را از یک ریپیتر بیرون می‌کشد.
 *
 * ردیف‌های بازنشسته (P5-D121) کنار گذاشته می‌شوند: یادداشت بازنشسته یعنی
 * آن استان دیگر یادداشتی ندارد، پس نباید یالی هم داشته باشد.
 *
 * شناسه‌ای که به نوع پست انتظارشده تعلق نداشته باشد یا منتشر نشده باشد،
 * رد می‌شود — و در $invalid برمی‌گردد تا هشدار ادمین بتواند نشانش دهد.
 * بدون این، یک شناسهٔ اشتباه فقط باعث می‌شود یال ساخته نشود، بی‌هیچ نشانه‌ای.
 *
 * @return array آرایه‌ای با دو کلید: valid و invalid
 */
function topersia_derived_edge_ids( $post_id, $spec ) {

	$rows    = topersia_active_rows( get_post_meta( $post_id, $spec['repeater'], true ) );
	$valid   = array();
	$invalid = array();

	foreach ( $rows as $row ) {

		if ( empty( $row[ $spec['id_field'] ] ) ) {
			continue;
		}

		$target = absint( $row[ $spec['id_field'] ] );

		if ( ! $target ) {
			continue;
		}

		if ( get_post_type( $target ) !== $spec['expect'] || 'publish' !== get_post_status( $target ) ) {
			$invalid[] = $target;
			continue;
		}

		$valid[] = $target;
	}

	return array(
		'valid'   => array_values( array_unique( $valid ) ),
		'invalid' => array_values( array_unique( $invalid ) ),
	);
}

/** یال‌های مشتق‌شده را با محتوای ریپیتر همگام می‌کند. */
add_action( 'save_post', 'topersia_sync_derived_edges', 25, 3 );

function topersia_sync_derived_edges( $post_id, $post, $update ) {

	if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}

	$map = topersia_derived_edges_map();

	if ( ! isset( $map[ $post->post_type ] ) ) {
		return;
	}

	if ( ! topersia_run_once( 'derived_edges', $post_id ) ) {
		return;
	}

	if ( ! function_exists( 'jet_engine' ) || ! isset( jet_engine()->relations ) ) {
		return;
	}

	// یال‌ها زبان‌مستقل‌اند — فقط از روی نسخهٔ فارسی ساخته می‌شوند.
	if ( ! topersia_is_default_language( $post_id ) ) {
		return;
	}

	foreach ( $map[ $post->post_type ] as $spec ) {

		$relation = topersia_relation( $spec['relation'] );

		if ( ! $relation ) {
			continue;
		}

		$ids    = topersia_derived_edge_ids( $post_id, $spec );
		$target = $ids['valid'];

		if ( 'child' === $spec['role'] ) {

			// پست جاری فرزند است؛ شناسه‌های ریپیتر والدند.
			$current = $relation->get_parents( $post_id, 'ids' );
			$current = is_array( $current ) ? array_map( 'absint', $current ) : array();

			foreach ( array_diff( $target, $current ) as $add ) {
				topersia_relation_connect( $relation, $add, $post_id );
			}

			foreach ( array_diff( $current, $target ) as $remove ) {
				topersia_relation_disconnect( $relation, $remove, $post_id );
			}
		} else {

			// پست جاری والد است؛ شناسه‌های ریپیتر فرزندند.
			$current = $relation->get_children( $post_id, 'ids' );
			$current = is_array( $current ) ? array_map( 'absint', $current ) : array();

			foreach ( array_diff( $target, $current ) as $add ) {
				topersia_relation_connect( $relation, $post_id, $add );
			}

			foreach ( array_diff( $current, $target ) as $remove ) {
				topersia_relation_disconnect( $relation, $post_id, $remove );
			}
		}
	}
}

/**
 * هشدار برای شناسه‌های نامعتبر در ریپیترهای یال‌ساز.
 *
 * چرا لازم است: زیرفیلد شناسه از نوع number است، پس ویرایشگر می‌تواند هر
 * عددی بنویسد. یک عدد اشتباه فقط باعث می‌شود یال ساخته نشود — بدون خطا،
 * بدون هیچ نشانه‌ای در صفحه. همان دسته شکست خاموشی که کل این پروژه با آن
 * درگیر بوده.
 */
add_action( 'admin_notices', 'topersia_derived_edges_notice' );

function topersia_derived_edges_notice() {

	if ( ! function_exists( 'get_current_screen' ) ) {
		return;
	}

	$screen = get_current_screen();

	if ( ! $screen || 'post' !== $screen->base ) {
		return;
	}

	$map = topersia_derived_edges_map();

	if ( ! isset( $map[ $screen->post_type ] ) ) {
		return;
	}

	$post_id = isset( $_GET['post'] ) ? absint( $_GET['post'] ) : 0;

	if ( ! $post_id || ! current_user_can( 'edit_post', $post_id ) ) {
		return;
	}

	foreach ( $map[ $screen->post_type ] as $spec ) {

		$ids = topersia_derived_edge_ids( $post_id, $spec );

		if ( empty( $ids['invalid'] ) ) {
			continue;
		}

		printf(
			'<div class="notice notice-warning"><p>%s <code>%s</code> — %s</p></div>',
			esc_html(
				sprintf(
					/* translators: نام ریپیتر */
					__( 'شناسهٔ نامعتبر در ریپیتر «%s»:', 'topersia-core' ),
					$spec['repeater']
				)
			),
			esc_html( implode( '، ', $ids['invalid'] ) ),
			esc_html(
				sprintf(
					/* translators: نوع پست انتظارشده */
					__( 'هر شناسه باید به یک پست منتشرشده از نوع %s تعلق داشته باشد. تا اصلاح نشود، یال رابطه برای آن ردیف ساخته نمی‌شود.', 'topersia-core' ),
					$spec['expect']
				)
			)
		);
	}
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۷ — استخراج خودکار استان از شهرهای مسیر
 * ═══════════════════════════════════════════════════════════════════════
 * 🔴 با فلگ «استخراج خودکار استان» در پنل کنترل می‌شود و پیش‌فرض خاموش است.
 *
 * دلیل خاموش‌بودن: زنجیرهٔ G5 شهر ← G4 شهرستان ← G3 استان هنوز در داده
 * برقرار نیست (DEBT-P9-001). با زنجیرهٔ ناقص، تابع فهرست خالی برمی‌گرداند و
 * استان‌هایی را که دستی وصل شده‌اند در هر ذخیره پاک می‌کند — بی‌صدا.
 *
 * وقتی هر شهر به شهرستانش و هر شهرستان به استانش وصل شد، فقط فلگ را در پنل
 * روشن کن. خودِ توابع سالم‌اند و آزموده شده‌اند.
 */

/**
 * استان یک شهر را از راه شهرستان پیدا می‌کند.
 *
 * رابطهٔ مستقیم عمومیِ استان ← شهر وجود ندارد. رابطهٔ capital_of_province
 * فقط «این شهر مرکز استان است» را می‌گوید و One to one است، پس برای این کار
 * مناسب نیست.
 *
 * این تابع عمداً عمومی نوشته شده — هر موجودیتی که به شهر وصل می‌شود
 * (جاذبه، رویداد، غذای محلی) می‌تواند از آن استفاده کند.
 *
 * @return int شناسهٔ استان، یا صفر اگر زنجیره ناقص باشد.
 */
function topersia_province_of_city( $city_id ) {

	$county_relation = topersia_relation( TOPERSIA_REL_COUNTY_CITY );

	if ( ! $county_relation ) {
		return 0;
	}

	$counties = $county_relation->get_parents( absint( $city_id ), 'ids' );

	if ( empty( $counties ) ) {
		return 0; // شهر به هیچ شهرستانی وصل نیست — زنجیره ناقص.
	}

	$province_relation = topersia_relation( TOPERSIA_REL_PROVINCE_COUNTY );

	if ( ! $province_relation ) {
		return 0;
	}

	foreach ( (array) $counties as $county_id ) {

		$provinces = $province_relation->get_parents( absint( $county_id ), 'ids' );

		if ( ! empty( $provinces ) ) {
			return absint( reset( $provinces ) );
		}
	}

	return 0;
}

/** پس از همگام‌سازی شهرها، استان‌ها را از آن‌ها استخراج و وصل می‌کند. */
add_action( 'save_post_tp_route', 'topersia_p9_sync_provinces', 30, 3 );

function topersia_p9_sync_provinces( $post_id, $post, $update ) {

	if ( ! TOPERSIA_AUTO_PROVINCE ) {
		return; // خاموش تا تکمیل زنجیرهٔ جغرافیایی — DEBT-P9-001.
	}

	if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}

	if ( ! topersia_run_once( 'p9_provinces', $post_id ) ) {
		return;
	}

	if ( ! function_exists( 'jet_engine' ) || ! isset( jet_engine()->relations ) ) {
		return;
	}

	if ( ! topersia_is_default_language( $post_id ) ) {
		return;
	}

	$ids = topersia_parse_ids( get_post_meta( $post_id, 'route_stops_order', true ) );

	if ( empty( $ids ) ) {
		return;
	}

	$provinces = array();

	foreach ( $ids as $id ) {

		if ( 'tp_city' !== get_post_type( $id ) ) {
			continue;
		}

		$province_id = topersia_province_of_city( $id );

		if ( $province_id ) {
			$provinces[] = $province_id;
		}
	}

	$provinces = array_values( array_unique( $provinces ) );

	// گارد ایمنی: اگر زنجیره هیچ استانی نداد، چیزی را پاک نکن.
	// بدون این، یک زنجیرهٔ شکسته همهٔ روابط دستی را از بین می‌برد.
	if ( empty( $provinces ) ) {
		return;
	}

	$relation = topersia_relation( TOPERSIA_REL_ROUTE_PROVINCE );

	if ( ! $relation ) {
		return;
	}

	$current = $relation->get_children( $post_id, 'ids' );
	$current = is_array( $current ) ? array_map( 'absint', $current ) : array();

	foreach ( array_diff( $provinces, $current ) as $add ) {
		topersia_relation_connect( $relation, $post_id, $add );
	}

	foreach ( array_diff( $current, $provinces ) as $remove ) {
		topersia_relation_disconnect( $relation, $post_id, $remove );
	}
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۸ — یکپارچگی Rank Math
 * ═══════════════════════════════════════════════════════════════════════
 * سه کار: (الف) ثبت متغیرهای سفارشی برای خواندن عنوان و توضیح متا از
 * متاباکس JetEngine، (ب) اعمال خودکار همان‌ها روی همهٔ موجودیت‌ها، و (ج)
 * همگام‌سازی hero_image با تصویر شاخص وردپرس.
 *
 * چرا متغیر سفارشی و نه %customfield%: پشتیبانی رسمی Rank Math تأیید کرده
 * که %customfield% با JetEngine قابل اتکا نیست.
 *
 * چرا فیلتر و نه پیکربندی پنل Rank Math: پروژه ۴۲ نوع پست دارد و به ۹ زبان
 * می‌رود. تنظیم دستی یعنی ۸۴ تغییر که در دیتابیس دفن می‌شوند، در هیچ فایلی
 * ثبت نمی‌شوند، پس از هر حادثه باید از نو زده شوند، و برای نوع پست تازه
 * فراموش می‌شوند.
 *
 * تا پیش از نسخهٔ ۴.۱.۰ دقیقاً همین اتفاق افتاده بود: متغیرها از نسخهٔ
 * ۲.۰.۰ ثبت می‌شدند ولی هیچ‌وقت به‌کار نرفته بودند، و کل سایت بدون هیچ تگ
 * توضیح متایی منتشر می‌شد — در حالی که همان داده در JSON-LD درست بود.
 *
 * چهار فیلتر خاموش‌کنندهٔ شِمای Rank Math اینجا نیستند — در افزونهٔ
 * topersia-schema هستند، چون فقط زمانی معنا دارند که موتور ما جایشان را پر
 * کند. اگر آن افزونه غیرفعال شود، شِمای بومی Rank Math برمی‌گردد و صفحه
 * بدون هیچ دادهٔ ساختاریافته‌ای نمی‌ماند.
 *
 * گاردِ $busy روی هر دو فیلتر: اگر خواندن متا به هر دلیلی دوباره همان
 * فیلتر را فایر کند، حلقهٔ بی‌پایان می‌شود و حافظه تمام می‌کند — که در
 * مرورگر به شکل «خطای مهم» دیده می‌شود، بدون هیچ نشانه‌ای از علت. یک
 * پرچم استاتیک ساده کل این دسته خطا را حذف می‌کند.
 *
 * هر دو فیلتر با فلگ در پنل قابل خاموش‌کردن‌اند. این عمدی است: اگر روزی
 * رفتار Rank Math عوض شود و این مسیر سایت را بشکند، باید بشود بدون
 * دسترسی به سرور خاموشش کرد.
 */
add_action(
	'rank_math/vars/register_extra_replacements',
	function () {

		rank_math_register_var_replacement(
			'custom_meta_title',
			array(
				'name'        => esc_html__( 'ToPersia Meta Title', 'topersia-core' ),
				'description' => esc_html__( 'meta_title از متاباکس JetEngine', 'topersia-core' ),
				'variable'    => 'custom_meta_title',
				'example'     => 'عنوان نمونه',
			),
			'topersia_meta_title_cb'
		);

		rank_math_register_var_replacement(
			'custom_meta_description',
			array(
				'name'        => esc_html__( 'ToPersia Meta Description', 'topersia-core' ),
				'description' => esc_html__( 'meta_description از متاباکس JetEngine', 'topersia-core' ),
				'variable'    => 'custom_meta_description',
				'example'     => 'توضیح نمونه',
			),
			'topersia_meta_desc_cb'
		);
	}
);

/**
 * عنوان متا — با زنجیرهٔ پشتیبان.
 *
 * زنجیره: meta_title ← عنوان پست. هرگز رشتهٔ خالی برنمی‌گرداند، چون یک تگ
 * title خالی از یک تگ غیربهینه بدتر است.
 */
function topersia_meta_title_cb() {

	$post_id = get_queried_object_id();

	if ( ! $post_id ) {
		return '';
	}

	$value = topersia_entity_meta( $post_id, 'meta_title' );

	if ( '' === $value ) {
		$value = wp_strip_all_tags( get_the_title( $post_id ) );
	}

	return $value;
}

/**
 * توضیح متا — با زنجیرهٔ پشتیبان.
 *
 * زنجیره: meta_description ← short_summary ← ai_summary.
 *
 * چرا این ترتیب: meta_description عمداً برای SERP نوشته شده. اگر نبود،
 * short_summary نزدیک‌ترین جایگزین انسانی است. ai_summary آخرین پناه است
 * چون برای موتور پاسخ نوشته شده نه برای انسان و معمولاً بلندتر از حد
 * اسنیپت است — ولی از هیچ بهتر است.
 */
function topersia_meta_desc_cb() {

	$post_id = get_queried_object_id();

	if ( ! $post_id ) {
		return '';
	}

	foreach ( array( 'meta_description', 'short_summary', 'ai_summary' ) as $key ) {

		$value = topersia_entity_meta( $post_id, $key );

		if ( '' !== $value ) {
			return $value;
		}
	}

	return '';
}

/** اعمال خودکار عنوان روی همهٔ موجودیت‌ها. */
add_filter( 'rank_math/frontend/title', 'topersia_seo_title', 20 );

function topersia_seo_title( $title ) {

	static $busy = false;

	if ( $busy || ! topersia_setting( 'seo_title_filter' ) || ! is_singular() ) {
		return $title;
	}

	if ( ! topersia_is_entity( get_post_type( get_queried_object_id() ) ) ) {
		return $title;
	}

	$busy   = true;
	$custom = topersia_meta_title_cb();
	$busy   = false;

	if ( '' === $custom ) {
		return $title;
	}

	return topersia_seo_append_brand( $custom );
}

/**
 * شمارش نویسه‌های یک رشتهٔ UTF-8.
 *
 * mbstring روی هر میزبانی نصب نیست. بدون گارد، فراخوانی mb_strlen خطای
 * مرگبار می‌دهد — همان دسته خطایی که نسخهٔ ۴.۱.۴ برای رفعش نوشته شد.
 *
 * اما پشتیبانِ ساده هم غلط است: strlen بایت می‌شمارد، و متن فارسی حدود ۱٫۸
 * برابرِ شمار نویسه‌هایش بایت دارد. یک عنوان ۵۴ نویسه‌ای صد بایت می‌شود و
 * از سقف هفتاد رد می‌شود — یعنی روی میزبانی بدون mbstring، پسوند برند برای
 * هر عنوان فارسی بی‌صدا خاموش می‌ماند. این باگ در آزمون واحد کشف شد، نه در
 * محیط زنده.
 *
 * پس پشتیبان، PCRE با پرچم /u است: عملاً همه‌جا در دسترس است و خودِ
 * وردپرس هم در نبود mbstring به همین تکیه می‌کند.
 */
function topersia_str_len( $text ) {

	if ( function_exists( 'mb_strlen' ) ) {
		return mb_strlen( $text, 'UTF-8' );
	}

	$count = preg_match_all( '/./u', $text );

	// اگر رشته UTF-8 معتبر نبود، PCRE مقدار false می‌دهد.
	return false === $count ? strlen( $text ) : $count;
}

/**
 * آیا رشته شامل زیررشته است — بدون حساسیت به بزرگی و کوچکی حروف.
 *
 * پشتیبانِ stripos اینجا بی‌خطر است: بایت‌های غیر-ASCII در UTF-8 همه بالای
 * 0x7F هستند و تابع کوچک‌سازیِ بایتی دست‌نخورده ردشان می‌کند. پس تطبیق
 * دقیق برای متن فارسی درست کار می‌کند و بی‌حساسیتی فقط روی بخش لاتین
 * اعمال می‌شود — که همان چیزی است که برای نام برند لازم داریم.
 */
function topersia_str_has( $haystack, $needle ) {

	if ( '' === $needle || '' === $haystack ) {
		return false;
	}

	if ( function_exists( 'mb_stripos' ) ) {
		return false !== mb_stripos( $haystack, $needle, 0, 'UTF-8' );
	}

	return false !== stripos( $haystack, $needle );
}

/**
 * پسوند برند را به عنوان سئو می‌افزاید — تصمیم F-17.
 *
 * چرا لازم شد: فیلتر عنوان، کل عنوان را جایگزین می‌کند، پس الگوی
 * %sitename% که Rank Math پیش‌تر اضافه می‌کرد از بین رفت و نام ToPersia از
 * هر نتیجهٔ جستجو حذف شد. برای پروژه‌ای که هدفش مرجع‌شدن است، دیده‌شدن
 * مکرر نام برند در SERP ارزش واقعی دارد.
 *
 * چرا خودکار و نه دستی: گزینهٔ «ویرایشگر خودش در meta_title بنویسد» روی
 * ۱۹۴٬۰۰۰ صفحه و نُه زبان عملاً یعنی هرگز — همان استدلالی که فیلتر عنوان
 * را جایگزین ۸۴ تنظیم دستی کرد.
 *
 * سه گارد:
 *   ۱. اگر نام برند از قبل در عنوان باشد، دوباره افزوده نمی‌شود.
 *   ۲. اگر مجموع از سقف نویسه بگذرد، پسوند حذف می‌شود — عنوانِ بریده از
 *      عنوانِ بدون برند بدتر است، چون کلیدواژه را می‌بُرد.
 *   ۳. پسوند خالی یعنی از نام سایت وردپرس ساخته شود.
 */
function topersia_seo_append_brand( $title ) {

	if ( ! topersia_setting( 'seo_title_brand' ) || '' === $title ) {
		return $title;
	}

	$suffix = trim( (string) topersia_setting( 'seo_brand_suffix' ) );

	if ( '' === $suffix ) {
		$suffix = '— ' . wp_strip_all_tags( get_bloginfo( 'name' ) );
	}

	// نامِ خالصِ برند، بدون جداکنندهٔ ابتدایی.
	$brand = trim( $suffix, " \t\n\r—–-|·،" );

	if ( topersia_str_has( $title, $brand ) ) {
		return $title; // از قبل هست.
	}

	$candidate = $title . ' ' . $suffix;
	$max       = absint( topersia_setting( 'seo_title_max' ) );

	if ( $max && topersia_str_len( $candidate ) > $max ) {
		return $title;
	}

	return $candidate;
}

/** اعمال خودکار توضیح متا روی همهٔ موجودیت‌ها. */
add_filter( 'rank_math/frontend/description', 'topersia_seo_description', 20 );

function topersia_seo_description( $description ) {

	static $busy = false;

	if ( $busy || ! topersia_setting( 'seo_desc_filter' ) || ! is_singular() ) {
		return $description;
	}

	if ( ! topersia_is_entity( get_post_type( get_queried_object_id() ) ) ) {
		return $description;
	}

	$busy   = true;
	$custom = topersia_meta_desc_cb();
	$busy   = false;

	return '' !== $custom ? $custom : $description;
}

/**
 * همگام‌سازی hero_image با تصویر شاخص وردپرس.
 *
 * این پروژه تصویر شاخص را در فیلد hero_image متاباکس مشترک نگه می‌دارد.
 * Rank Math — و هر ابزار دیگری، از فید RSS تا لیست‌های JetEngine تا
 * اشتراک‌گذاری شبکه‌های اجتماعی — تصویر شاخص وردپرس را می‌خواند. بدون این
 * همگام‌سازی، هر صفحه که در تلگرام یا واتساپ یا لینکدین به اشتراک گذاشته
 * شود، کارت بی‌تصویر و شکسته نشان می‌دهد.
 *
 * منبع حقیقت همچنان hero_image است. _thumbnail_id فقط ایندکس مشتق‌شده است
 * — همان الگوی مشتق‌کردن یال رابطه از فیلد ترتیب در بخش ۶.
 *
 * روی هر زبان اجرا می‌شود، نه فقط زبان پیش‌فرض: hero_image کلاس Copy دارد
 * پس شناسهٔ رسانه در هر سه زبان یکی است، و هر نسخهٔ زبانی به تصویر شاخص
 * مستقل خودش نیاز دارد.
 */
add_action( 'save_post', 'topersia_sync_featured_image', 1002, 3 );

function topersia_sync_featured_image( $post_id, $post, $update ) {

	if ( ! topersia_setting( 'sync_featured_image' ) ) {
		return;
	}

	if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}

	if ( ! topersia_is_entity( $post->post_type ) ) {
		return;
	}

	if ( in_array( $post->post_status, array( 'auto-draft', 'trash' ), true ) ) {
		return;
	}

	$hero = absint( get_post_meta( $post_id, 'hero_image', true ) );

	if ( ! $hero || 'attachment' !== get_post_type( $hero ) ) {
		return;
	}

	if ( absint( get_post_thumbnail_id( $post_id ) ) === $hero ) {
		return; // از قبل یکسان است.
	}

	set_post_thumbnail( $post_id, $hero );
}

/* ───────────────────────────────────────────────────────────────────────
 *  بخش ۸-ب — بستن جعبهٔ Custom Fields روی موجودیت‌ها (F-19)
 * ───────────────────────────────────────────────────────────────────────
 * جعبهٔ استاندارد وردپرس همهٔ متاکلیدهای خام را با دکمهٔ ویرایش و حذف نشان
 * می‌دهد. روی این پروژه دو خطر مشخص دارد:
 *
 * ۱ — ریپیترها آرایهٔ سریال‌شده‌اند. ویرایش regional_notes یا faq_items
 *     به‌عنوان متن ساده، کل ساختار را خراب می‌کند و بازیابی فقط از بکاپ
 *     ممکن است. هیچ هشداری هم در کار نیست.
 *
 * ۲ — entity_uid قابل ویرایش است. کل معماری @id روی پایداری آن بنا شده و
 *     بخش ۳ عمداً هرگز مقدار موجود را بازنویسی نمی‌کند — پس یک تغییر
 *     تصادفی برای همیشه می‌ماند و پیوند میان‌زبانی آن موجودیت را می‌شکند.
 *
 * سند تحویل ادعا می‌کند نوع‌های پست با «Supports Title Only» ساخته شده‌اند.
 * حضور این جعبه با آن ادعا مغایر است — یک نمونهٔ دیگر از فاصلهٔ سند و
 * دیتابیس.
 *
 * جایگزین امن برای عیب‌یابی: پیش‌نمایش گراف در زبانهٔ شِمای پنل، که فقط
 * می‌خواند و هیچ چیزی نمی‌نویسد.
 *
 * فلگ دارد چون ممکن است روزی برای مهاجرت داده لازم شود — ولی پیش‌فرض
 * بسته است، چون هزینهٔ یک خرابی از هزینهٔ روشن‌کردن موقتش بیشتر است.
 */
add_action( 'init', 'topersia_hide_custom_fields_box', 100 );

function topersia_hide_custom_fields_box() {

	if ( ! topersia_setting( 'hide_custom_fields' ) ) {
		return;
	}

	foreach ( get_post_types( array(), 'names' ) as $post_type ) {

		if ( topersia_is_entity( $post_type ) ) {
			remove_post_type_support( $post_type, 'custom-fields' );
		}
	}
}

/* ───────────────────────────────────────────────────────────────────────
 *  بخش ۸-ج — محافظ حذف ردیف Repeater (P5-D121)
 * ───────────────────────────────────────────────────────────────────────
 * قاعدهٔ P5-D121 می‌گوید ردیف Repeater ترجمه‌شدنی هرگز حذف نمی‌شود، چون
 * WPML ردیف‌ها را با شمارهٔ موقعیت دنبال می‌کند: حذف ردیف دوم از پنج ردیف،
 * ترجمهٔ ردیف‌های سه تا پنج را یک واحد بالا می‌کشد — در هر نُه زبان، خاموش
 * و بدون هیچ خطایی.
 *
 * تا امروز این فقط یک قاعدهٔ ادیتوریال بود. یک ویرایشگر در یک ثانیه
 * می‌توانست نقضش کند.
 *
 * ── چرا سمت سرور و نه پنهان‌کردن دکمه ─────────────────────────────────
 * پنهان‌کردن دکمهٔ حذف نیازمند حدس‌زدن کلاس‌های CSS جت‌انجین است، و اگر
 * افزونه نشانه‌گذاری‌اش را عوض کند محافظ بی‌صدا از کار می‌افتد — بدون
 * اینکه کسی بفهمد. این دقیقاً همان دسته شکستی است که P5-D136 هشدارش را
 * می‌دهد. سمت سرور به هیچ نشانه‌گذاری‌ای وابسته نیست.
 *
 * ── چطور کار می‌کند ──────────────────────────────────────────────────
 * پیش از نوشتن مقدار تازه، با مقدار قبلی مقایسه می‌شود. اگر ردیفی حذف
 * شده باشد، همان ردیف در همان موقعیت برمی‌گردد و وضعیتش not_applicable
 * می‌شود. یعنی حذف به بازنشستگی تبدیل می‌شود، بدون اینکه موقعیت هیچ
 * ردیفی جابه‌جا شود.
 *
 * ── چرا فقط وقتی ترجمه وجود دارد ──────────────────────────────────────
 * اگر پستی هنوز هیچ ترجمه‌ای ندارد، حذف ردیف بی‌ضرر است — ترجمهٔ بعدی از
 * وضعیت فعلی ساخته می‌شود. اعمال محافظ در آن حالت فقط اصطکاک بی‌دلیل
 * برای ورود دادهٔ اولیه می‌سازد، آن هم در مقیاس ۱۹۴٬۰۰۰ رکورد.
 */
add_filter( 'update_post_metadata', 'topersia_guard_row_delete', 10, 5 );

function topersia_guard_row_delete( $check, $post_id, $meta_key, $meta_value, $prev_value ) {

	if ( ! topersia_setting( 'guard_row_delete' ) ) {
		return $check;
	}

	/*
	 * مقدار غیرآرایه‌ای هم بررسی می‌شود.
	 *
	 * استک‌تریس محیط زنده نشان داد جت‌انجین از مسیر Cherry_X_Post_Meta و
	 * update_post_meta می‌نویسد — یعنی هوک درست بود. ولی وقتی همهٔ ردیف‌ها
	 * برداشته می‌شوند، مقدارِ نوشته‌شده آرایهٔ خالی نیست؛ رشتهٔ خالی است.
	 * شرط is_array در نسخهٔ قبل دقیقاً همان‌جا گارد را کنار می‌گذاشت —
	 * یعنی بدترین حالت بی‌محافظ می‌ماند.
	 *
	 * ایمنی از جای دیگری می‌آید: اگر مقدار قبلی Repeater نباشد یا زیرفیلد
	 * وضعیت نداشته باشد، تابع چند خط پایین‌تر خارج می‌شود. پس فیلدهای
	 * ساده هرگز به منطق ادغام نمی‌رسند.
	 */
	if ( ! topersia_is_entity( get_post_type( $post_id ) ) ) {
		return $check;
	}

	$incoming = is_array( $meta_value ) ? array_values( $meta_value ) : array();
	$old      = get_post_meta( $post_id, $meta_key, true );

	if ( ! is_array( $old ) || empty( $old ) || count( $old ) <= count( $incoming ) ) {
		return $check; // چیزی حذف نشده.
	}

	$status_key = topersia_row_status_key( $old );

	if ( ! $status_key ) {
		return $check; // این Repeater تحت قاعده نیست.
	}

	/*
	 * چرا این شرط، و چرا باید دیده شود.
	 *
	 * تا وقتی پستی ترجمه ندارد، حذف ردیف بی‌ضرر است — ترجمهٔ بعدی از وضعیت
	 * فعلی ساخته می‌شود. اعمال محافظ در آن حالت فقط اصطکاک بی‌دلیل برای
	 * ورود دادهٔ اولیه می‌سازد، آن هم در مقیاس ۱۹۴٬۰۰۰ رکورد.
	 *
	 * اما کنارکشیدن خاموش، خودش یک نقص است: ویرایشگر ردیفی را حذف می‌کند،
	 * هیچ اتفاقی نمی‌افتد، و هرگز نمی‌فهمد که محافظی وجود داشته و چرا
	 * دخالت نکرده. پس اینجا هم ردپا می‌ماند.
	 */
	if ( ! topersia_setting( 'guard_row_always' ) && ! topersia_has_translations( $post_id ) ) {

		set_transient(
			'topersia_row_guard_' . $post_id,
			array(
				'key'     => $meta_key,
				'retired' => 0,
				'mode'    => 'skipped_no_translation',
				'removed' => count( $old ) - count( $incoming ),
			),
			120
		);

		topersia_log( 'محافظ ردیف کنار کشید — پست ترجمه ندارد', 'info', 'guard', array( 'post' => $post_id, 'field' => $meta_key, 'removed' => count( $old ) - count( $incoming ) ) );

		return $check;
	}

	/*
	 * تفکیک دو حالت — چون از روی محتوا نمی‌شود فهمید کدام ردیف حذف شده و
	 * کدام ویرایش.
	 *
	 * اگر ویرایشگر هم‌زمان یک ردیف را حذف و ردیف دیگری را ویرایش کند،
	 * تطبیق ترتیبی از هم می‌پاشد و ردیف‌های سالم هم بازنشسته می‌شوند.
	 * این باگ در آزمون واحد کشف شد، نه در محیط زنده.
	 *
	 *   حذف خالص  — هر ردیف تازه دقیقاً با یک ردیف قدیمی می‌خواند.
	 *                تکلیف روشن است: ردیف‌های جامانده بازنشسته می‌شوند.
	 *
	 *   حذف + ویرایش — تکلیف مبهم است. نوشتن متوقف می‌شود و مقدار قبلی
	 *                  دست‌نخورده می‌ماند، با توضیح برای ویرایشگر.
	 *
	 * حدس‌زدن در حالت مبهم یعنی خراب‌کردن دادهٔ سالم — دقیقاً چیزی که این
	 * محافظ برای جلوگیری‌اش نوشته شده.
	 */
	$new     = $incoming;
	$merged  = array();
	$cursor  = 0;
	$retired = 0;

	foreach ( array_values( $old ) as $row ) {

		if ( ! is_array( $row ) ) {
			continue;
		}

		$candidate = isset( $new[ $cursor ] ) ? $new[ $cursor ] : null;

		if ( is_array( $candidate ) && topersia_rows_match( $row, $candidate, $status_key ) ) {

			$merged[] = $candidate;
			$cursor ++;

		} else {

			$row[ $status_key ] = 'not_applicable';
			$merged[]           = $row;
			$retired ++;
		}
	}

	// اگر همهٔ ردیف‌های تازه مصرف نشده‌اند، تطبیق ابهام داشته است.
	$ambiguous = $cursor < count( $new );

	if ( $ambiguous ) {

		set_transient(
			'topersia_row_guard_' . $post_id,
			array(
				'key'       => $meta_key,
				'retired'   => 0,
				'ambiguous' => true,
			),
			120
		);

		topersia_log( 'تطبیق مبهم — نوشتن متوقف شد تا دادهٔ سالم خراب نشود', 'warning', 'guard', array( 'post' => $post_id, 'field' => $meta_key ) );

		return true; // نوشتن متوقف؛ مقدار قبلی دست‌نخورده می‌ماند.
	}

	if ( ! $retired ) {
		return $check;
	}

	set_transient(
		'topersia_row_guard_' . $post_id,
		array(
			'key'       => $meta_key,
			'retired'   => $retired,
			'ambiguous' => false,
		),
		120
	);

	topersia_log( 'حذف ردیف به بازنشستگی تبدیل شد', 'notice', 'guard', array( 'post' => $post_id, 'field' => $meta_key, 'retired' => $retired ) );

	update_post_meta( $post_id, $meta_key, $merged );

	return true; // نوشتن اصلی را متوقف کن — خودمان نوشتیم.
}

/**
 * حذف کامل متای یک Repeater هم مسدود می‌شود.
 *
 * چرا این هوک جدا لازم است: وقتی آخرین ردیف یک Repeater برداشته می‌شود،
 * جت‌انجین به‌جای نوشتن آرایهٔ خالی، خودِ متا را حذف می‌کند. آن مسیر از
 * update_post_metadata عبور نمی‌کند، پس محافظ اصلاً اجرا نمی‌شد — و
 * بدترین حالت، یعنی خالی‌کردن کل Repeater، بی‌محافظ می‌ماند.
 *
 * فرض‌کردن مسیر نوشتن بدون دیدنش، همان اشتباهی است که P5-D136 هشدارش را
 * می‌دهد.
 */
add_filter( 'delete_post_metadata', 'topersia_guard_row_wipe', 10, 5 );

function topersia_guard_row_wipe( $check, $post_id, $meta_key, $meta_value, $delete_all ) {

	if ( $delete_all || ! topersia_setting( 'guard_row_delete' ) ) {
		return $check;
	}

	if ( ! topersia_is_entity( get_post_type( $post_id ) ) ) {
		return $check;
	}

	$old = get_post_meta( $post_id, $meta_key, true );

	if ( ! is_array( $old ) || empty( $old ) ) {
		return $check;
	}

	$status_key = topersia_row_status_key( $old );

	if ( ! $status_key ) {
		return $check;
	}

	if ( ! topersia_setting( 'guard_row_always' ) && ! topersia_has_translations( $post_id ) ) {

		topersia_log( 'محافظ خالی‌سازی کنار کشید — پست ترجمه ندارد', 'info', 'guard', array( 'post' => $post_id, 'field' => $meta_key ) );

		return $check;
	}

	$merged = array();

	foreach ( array_values( $old ) as $row ) {

		if ( ! is_array( $row ) ) {
			continue;
		}

		$row[ $status_key ] = 'not_applicable';
		$merged[]           = $row;
	}

	set_transient(
		'topersia_row_guard_' . $post_id,
		array(
			'key'     => $meta_key,
			'retired' => count( $merged ),
			'mode'    => 'wipe',
		),
		120
	);

	topersia_log( 'خالی‌سازی کامل Repeater به بازنشستگی تبدیل شد', 'warning', 'guard', array( 'post' => $post_id, 'field' => $meta_key, 'retired' => count( $merged ) ) );

	update_post_meta( $post_id, $meta_key, $merged );

	return true; // حذف متوقف شد.
}

/**
 * ثبت هر نوشتن متای آرایه‌ای روی موجودیت‌ها — فقط در حالت اشکال‌زدایی.
 *
 * چرا: وقتی محافظ اجرا نمی‌شود، باید بشود دید جت‌انجین اصلاً از کدام مسیر
 * می‌نویسد. بدون این، تنها راه حدس‌زدن است.
 */
add_filter( 'update_post_metadata', 'topersia_trace_meta_write', 5, 5 );

function topersia_trace_meta_write( $check, $post_id, $meta_key, $meta_value, $prev ) {

	if ( defined( 'WP_DEBUG' ) && WP_DEBUG && is_array( $meta_value ) && topersia_is_entity( get_post_type( $post_id ) ) ) {

		$old = get_post_meta( $post_id, $meta_key, true );

		topersia_log(
			sprintf(
				'meta trace: update %s روی %d — قدیم %s ردیف · جدید %s ردیف',
				$meta_key,
				$post_id,
				is_array( $old ) ? count( $old ) : 'غیرآرایه',
				count( $meta_value )
			)
		);
	}

	return $check;
}

add_filter( 'delete_post_metadata', 'topersia_trace_meta_delete', 5, 5 );

function topersia_trace_meta_delete( $check, $post_id, $meta_key, $meta_value, $delete_all ) {

	if ( defined( 'WP_DEBUG' ) && WP_DEBUG && ! $delete_all && topersia_is_entity( get_post_type( $post_id ) ) ) {

		$old = get_post_meta( $post_id, $meta_key, true );

		if ( is_array( $old ) ) {
			topersia_log( sprintf( 'meta trace: delete %s روی %d — %d ردیف', $meta_key, $post_id, count( $old ) ) );
		}
	}

	return $check;
}

/** کلید وضعیت را از اولین ردیف یک Repeater پیدا می‌کند. */
function topersia_row_status_key( $rows ) {

	foreach ( (array) $rows as $row ) {

		if ( ! is_array( $row ) ) {
			continue;
		}

		foreach ( array_keys( $row ) as $key ) {

			if ( '_row_status' === substr( $key, -11 ) ) {
				return $key;
			}
		}
	}

	return '';
}

/** دو ردیف را بدون درنظرگرفتن وضعیت مقایسه می‌کند. */
function topersia_rows_match( $a, $b, $status_key ) {

	unset( $a[ $status_key ], $b[ $status_key ] );

	foreach ( $a as $key => $value ) {

		if ( ! array_key_exists( $key, $b ) ) {
			return false;
		}

		if ( (string) $value !== (string) $b[ $key ] ) {
			return false;
		}
	}

	return true;
}

/**
 * آیا این پست ترجمه‌ای دارد؟
 *
 * هر فراخوانی WPML با گارد — P5-D138.
 */
function topersia_has_translations( $post_id ) {

	if ( ! has_filter( 'wpml_element_type' ) || ! has_filter( 'wpml_get_element_translations' ) ) {
		return false;
	}

	$post_type = get_post_type( $post_id );

	if ( ! $post_type ) {
		return false;
	}

	try {

		$type    = apply_filters( 'wpml_element_type', $post_type );
		$trid    = apply_filters( 'wpml_element_trid', null, $post_id, $type );

		if ( ! $trid ) {
			return false;
		}

		$all = apply_filters( 'wpml_get_element_translations', null, $trid, $type );

		return is_array( $all ) && count( $all ) > 1;

	} catch ( Throwable $error ) {

		topersia_log( 'بررسی ترجمه شکست خورد: ' . $error->getMessage(), 'warning', 'wpml', array( 'post' => $post_id ) );

		return false;
	}
}

/** اطلاع‌رسانی به ویرایشگر که حذف به بازنشستگی تبدیل شد. */
add_action( 'admin_notices', 'topersia_row_guard_notice' );

function topersia_row_guard_notice() {

	$post_id = isset( $_GET['post'] ) ? absint( $_GET['post'] ) : 0;

	if ( ! $post_id ) {
		return;
	}

	$data = get_transient( 'topersia_row_guard_' . $post_id );

	if ( ! $data ) {
		return;
	}

	delete_transient( 'topersia_row_guard_' . $post_id );

	if ( isset( $data['mode'] ) && 'skipped_no_translation' === $data['mode'] ) {

		printf(
			'<div class="notice notice-info is-dismissible"><p><strong>%s</strong> %s</p></div>',
			esc_html(
				sprintf(
					/* translators: ۱ شمار ردیف · ۲ نام فیلد */
					__( '%1$s ردیف از «%2$s» حذف شد.', 'topersia-core' ),
					number_format_i18n( $data['removed'] ),
					$data['key']
				)
			),
			esc_html__( 'محافظ ردیف دخالت نکرد چون این پست هنوز هیچ ترجمه‌ای ندارد و حذف در این حالت بی‌ضرر است. از لحظه‌ای که ترجمه ساخته شود، حذف ردیف خودکار به بازنشستگی تبدیل می‌شود. اگر می‌خواهی همین حالا هم سخت‌گیرانه باشد، گزینهٔ «محافظ ردیف حتی بدون ترجمه» را در تنظیمات روشن کن.', 'topersia-core' )
		);

		return;
	}

	if ( isset( $data['mode'] ) && 'wipe' === $data['mode'] ) {

		printf(
			'<div class="notice notice-warning is-dismissible"><p><strong>%s</strong> %s</p></div>',
			esc_html(
				sprintf(
					/* translators: ۱ شمار ردیف · ۲ نام فیلد */
					__( 'هر %1$s ردیف «%2$s» بازنشسته شد، نه حذف.', 'topersia-core' ),
					number_format_i18n( $data['retired'] ),
					$data['key']
				)
			),
			esc_html__( 'خالی‌کردن کامل یک Repeater همان اثر حذف تک‌ردیف را دارد و ترجمه‌ها را در هر زبان از هم می‌پاشد. همهٔ ردیف‌ها سر جایشان ماندند و وضعیتشان «بازنشسته» شد؛ در فرانت نمایش داده نمی‌شوند.', 'topersia-core' )
		);

		return;
	}

	if ( ! empty( $data['ambiguous'] ) ) {

		printf(
			'<div class="notice notice-error"><p><strong>%s</strong> %s</p></div>',
			esc_html(
				sprintf(
					/* translators: نام فیلد */
					__( 'تغییرات «%s» ذخیره نشد.', 'topersia-core' ),
					$data['key']
				)
			),
			esc_html__( 'در یک ذخیره هم ردیف حذف شده بود و هم محتوای ردیفی عوض شده بود، و تشخیص اینکه کدام کدام است ممکن نبود. مقدار قبلی دست‌نخورده ماند تا دادهٔ سالم خراب نشود. لطفاً دو مرحله انجام بده: اول وضعیت ردیف‌های ناخواسته را «بازنشسته» کن و ذخیره کن؛ بعد بقیهٔ ویرایش‌ها را انجام بده.', 'topersia-core' )
		);

		return;
	}

	printf(
		'<div class="notice notice-warning is-dismissible"><p><strong>%s</strong> %s</p></div>',
		esc_html(
			sprintf(
				/* translators: ۱ شمار ردیف · ۲ نام فیلد */
				__( '%1$s ردیف در «%2$s» بازنشسته شد، نه حذف.', 'topersia-core' ),
				number_format_i18n( $data['retired'] ),
				$data['key']
			)
		),
		esc_html__( 'این پست ترجمه دارد و حذف ردیف، ترجمهٔ ردیف‌های بعدی را در هر زبان جابه‌جا می‌کند. ردیف در همان موقعیت ماند و وضعیتش «بازنشسته» شد؛ در فرانت نمایش داده نمی‌شود. اگر واقعاً باید برگردد، وضعیتش را «فعال» کن.', 'topersia-core' )
	);
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۹ — موتور دادهٔ ساختاریافته → منتقل شد
 * ═══════════════════════════════════════════════════════════════════════
 * از نسخهٔ ۴.۰.۰، کل موتور JSON-LD در افزونهٔ جداگانهٔ topersia-schema
 * زندگی می‌کند.
 *
 * آنچه افزونهٔ شِما از این فایل مصرف می‌کند — قرارداد عمومی هسته:
 *   topersia_relation()     topersia_p9_stops()    topersia_active_rows()
 *   topersia_setting()      topersia_entity_meta() topersia_is_entity()
 *   TOPERSIA_SITE_ID        TOPERSIA_UID_BASE      TOPERSIA_CORE_VERSION
 *   TOPERSIA_REL_COUNTY_CITY                       TOPERSIA_REL_PROVINCE_COUNTY
 *   متای entity_uid (که بخش ۳ می‌سازد)
 *   فیلتر topersia_admin_tabs (که بخش ۱۳ فراهم می‌کند)
 *
 * تغییر یا حذف هر کدام از این‌ها بدون هماهنگی، افزونهٔ شِما را می‌شکند.
 *
 * شمارهٔ این بخش عمداً خالی نگه داشته شده تا شمارهٔ بخش‌های ۱۰ و ۱۱ و ۱۲ که
 * در اسناد پروژه ارجاع دارند تغییر نکند.
 */

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۱۰ — پاک‌سازی head
 * ═══════════════════════════════════════════════════════════════════════
 * حذف تگ‌هایی که هیچ مصرفی ندارند و مسیر داخلی نصب را لو می‌دهند.
 * RSD به xmlrpc.php اشاره می‌کند و wlwmanifest به Windows Live Writer —
 * ابزاری که سال‌هاست منسوخ شده.
 */
remove_action( 'wp_head', 'rsd_link' );
remove_action( 'wp_head', 'wlwmanifest_link' );

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۱۱ — پنهان‌سازی مسیر نصب وردپرس
 * ═══════════════════════════════════════════════════════════════════════
 * وردپرس در زیرپوشهٔ /geo نصب است ولی آدرس سایت ریشهٔ دامنه است. نتیجه:
 * آدرس صفحات تمیز است اما هر دارایی‌ای که از فایل‌های وردپرس می‌آید — تصویر،
 * CSS قالب، JS افزونه، jQuery — مسیر /geo/ را در HTML عمومی نشت می‌دهد.
 *
 * راهکار سه‌لایه:
 *   لایهٔ ۱ — Apache: دو مسیر عمومی تمیز که بی‌صدا به مسیر واقعی نگاشت
 *             می‌شوند. در public_html/.htaccess تعریف شده.
 *   لایهٔ ۲ — ثابت WP_CONTENT_URL در wp-config.php.
 *   لایهٔ ۳ — همین بخش: فیلترها برای wp-includes، به‌علاوهٔ جاروی خروجی.
 *
 * لایهٔ سوم عمداً هست: افزونه‌ها گاهی آدرس را دور از API وردپرس می‌سازند و
 * فقط جاروی خروجی می‌تواند تضمین بدهد که هیچ نشتی باقی نمانده.
 *
 * مسیر /geo/wp-admin/ عمداً ماسک نمی‌شود: تبدیلش به /wp-admin/ لینک‌های
 * نوار مدیریت را برای کاربر واردشده می‌شکند، و بازدیدکنندهٔ ناشناس اصلاً
 * چنین لینکی در صفحه‌اش ندارد.
 *
 * ثابت‌های این بخش در بخش ۰ تعریف و از پنل قابل تغییرند.
 */

/**
 * جدول جایگزینی مسیرها.
 *
 * سه شکل هر مسیر پوشش داده می‌شود:
 *   عادی        /geo/wp-content/
 *   اسکیپ‌شده   \/geo\/wp-content\/   ← داخل JSON، مثل دادهٔ المنتور
 *   کدشده       %2Fgeo%2Fwp-content%2F ← داخل رشتهٔ کوئری
 */
function topersia_mask_pairs() {

	static $pairs = null;

	if ( null !== $pairs ) {
		return $pairs;
	}

	$dir    = TOPERSIA_WP_DIR;
	$assets = TOPERSIA_ASSETS_PATH;
	$core   = TOPERSIA_CORE_PATH;

	$pairs = array(
		"/{$dir}/wp-content/"  => "/{$assets}/",
		"/{$dir}/wp-includes/" => "/{$core}/",

		"\\/{$dir}\\/wp-content\\/"  => "\\/{$assets}\\/",
		"\\/{$dir}\\/wp-includes\\/" => "\\/{$core}\\/",

		"%2F{$dir}%2Fwp-content%2F"  => "%2F{$assets}%2F",
		"%2F{$dir}%2Fwp-includes%2F" => "%2F{$core}%2F",
	);

	return $pairs;
}

/** یک آدرس را ماسک می‌کند. */
function topersia_mask_url( $url ) {

	if ( ! is_string( $url ) || '' === $url ) {
		return $url;
	}

	return strtr( $url, topersia_mask_pairs() );
}

add_filter( 'includes_url', 'topersia_mask_url', 99 );
add_filter( 'content_url', 'topersia_mask_url', 99 );
add_filter( 'plugins_url', 'topersia_mask_url', 99 );
add_filter( 'script_loader_src', 'topersia_mask_url', 99 );
add_filter( 'style_loader_src', 'topersia_mask_url', 99 );
add_filter( 'wp_get_attachment_url', 'topersia_mask_url', 99 );
add_filter( 'stylesheet_directory_uri', 'topersia_mask_url', 99 );
add_filter( 'template_directory_uri', 'topersia_mask_url', 99 );

/** srcset آرایه‌ای از آدرس‌هاست و فیلتر جداگانه لازم دارد. */
add_filter( 'wp_calculate_image_srcset', 'topersia_mask_srcset', 99 );

function topersia_mask_srcset( $sources ) {

	if ( ! is_array( $sources ) ) {
		return $sources;
	}

	foreach ( $sources as $key => $source ) {

		if ( isset( $source['url'] ) ) {
			$sources[ $key ]['url'] = topersia_mask_url( $source['url'] );
		}
	}

	return $sources;
}

/**
 * جاروی نهایی روی کل خروجی فرانت‌اند.
 *
 * چرا لازم است با وجود فیلترهای بالا: المنتور و JetEngine بخشی از آدرس‌ها
 * را در CSS درون‌خطی و دادهٔ JSON تولید می‌کنند که از هیچ‌کدام از فیلترهای
 * وردپرس عبور نمی‌کند. این تنها راه تضمین صفر نشتی است.
 *
 * فقط دو رشتهٔ بسیار مشخص جایگزین می‌شوند، پس امکان برخورد تصادفی با
 * محتوای واقعی عملاً صفر است.
 */
add_action( 'template_redirect', 'topersia_mask_output_start', 1 );

function topersia_mask_output_start() {

	if ( ! TOPERSIA_MASK_OUTPUT ) {
		return;
	}

	if ( is_admin() || is_feed() || is_robots() || wp_doing_ajax() ) {
		return;
	}

	ob_start( 'topersia_mask_output_filter' );
}

function topersia_mask_output_filter( $html ) {

	if ( ! is_string( $html ) || '' === $html ) {
		return $html;
	}

	$html = strtr( $html, topersia_mask_pairs() );

	/*
	 * حذف همهٔ تگ‌های generator، از هر منبعی.
	 *
	 * remove_action روی wp_generator فقط تگ خودِ وردپرس را می‌گیرد. WPML و
	 * المنتور تگ generator خودشان را با شمارهٔ نسخهٔ دقیق منتشر می‌کنند — و
	 * همین دقیقاً چیزی است که یک مهاجم برای یافتن اکسپلویتِ متناظر لازم
	 * دارد. حذفشان از راه هوک نیازمند ارجاع به شیء افزونه است که شکننده
	 * است؛ حذف از خروجی قطعی و پایدار است.
	 */
	$html = preg_replace( '#<meta[^>]+name=["\']generator["\'][^>]*>\s*#i', '', $html );

	/* امضای XFN — بازماندهٔ سال ۲۰۰۴ و بی‌مصرف. */
	$html = str_replace( '<link rel="profile" href="https://gmpg.org/xfn/11">' . "\n", '', $html );

	/*
	 * نشتی /geo در بلوک قواعد پیش‌بارگذاری — F-18.
	 *
	 * وردپرس ۶٫۸ فهرست مسیرهای مستثنا از پیش‌واکشی را در فوتر منتشر می‌کند و
	 * آن فهرست شامل «/geo/wp-admin/*» و «/geo/wp-*.php» است.
	 *
	 * چرا فیلتر wp_speculation_rules_href_exclude_paths جوابگو نبود: هستهٔ
	 * وردپرس پس از اجرای فیلتر، مسیرهای پیش‌فرض را دوباره ادغام می‌کند تا
	 * هیچ افزونه‌ای نتواند حذفشان کند. آن فیلتر به‌طراحی قابل دور زدن نیست،
	 * پس تابع بخش ۱۲ که در نسخهٔ ۳.۱.۰ برای همین نوشته شد هرگز اثری نداشت —
	 * و چون حالت تعمیر روشن بود، خروجی ناشناس تا امروز دیده نشد.
	 *
	 * راه‌حل: فقط داخل همان یک بلوک اسکریپت، پیشوند پوشه حذف می‌شود. نتیجه
	 * «/wp-admin/*» است که همچنان یک الگوی استثنای معتبر است و برای
	 * بازدیدکنندهٔ ناشناس هیچ تفاوت رفتاری ندارد، چون در صفحهٔ او اصلاً
	 * لینکی به آن مسیرها وجود ندارد.
	 *
	 * فقط برای کاربر واردنشده: کاربر واردشده لینک‌های واقعی نوار مدیریت را
	 * دارد و استثنای درست برایش لازم است تا مرورگر آدرس‌های مدیریتی را
	 * پیش‌واکشی نکند.
	 */
	if ( ! is_user_logged_in() ) {

		$html = preg_replace_callback(
			'#<script[^>]+type=["\']speculationrules["\'][^>]*>.*?</script>#is',
			function ( $matches ) {

				return str_replace(
					array( '/' . TOPERSIA_WP_DIR . '/', '\\/' . TOPERSIA_WP_DIR . '\\/' ),
					array( '/', '\\/' ),
					$matches[0]
				);
			},
			$html
		);
	}

	return $html;
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۱۲ — کاهش اثر انگشت
 * ═══════════════════════════════════════════════════════════════════════
 * هدف: کم‌کردن نویز اسکن خودکار، نه امنیت واقعی.
 *
 * اکثر حملات وردپرس هدفمند نیستند؛ ربات‌ها دنبال امضاهای شناخته‌شده می‌گردند
 * و اگر پیدا نکردند سراغ هدف بعدی می‌روند. حذف این امضاها حجم زیادی از
 * تلاش‌های خودکار را خنثی می‌کند.
 *
 * اما گمنامی امنیت نیست. دفاع واقعی این‌هاست: به‌روزرسانی مداوم، احراز هویت
 * دومرحله‌ای، محدودیت تلاش ورود، DISALLOW_FILE_EDIT، و WAF.
 *
 * آنچه با هیچ کدی قابل پنهان‌شدن نیست: کلاس‌های CSS المنتور و JetEngine.
 * تغییرشان یعنی شکستن خودِ افزونه.
 */

/** تگ generator که نام و نسخهٔ وردپرس را اعلام می‌کند. */
remove_action( 'wp_head', 'wp_generator' );
add_filter( 'the_generator', '__return_empty_string' );

/** لینک‌های کشف فید — خودِ فیدها فعال می‌مانند. */
remove_action( 'wp_head', 'feed_links', 2 );
remove_action( 'wp_head', 'feed_links_extra', 3 );

/** لینک کوتاه و لینک‌های نوشتهٔ قبلی/بعدی — بی‌مصرف و افشاگر. */
remove_action( 'wp_head', 'wp_shortlink_wp_head', 10 );
remove_action( 'wp_head', 'adjacent_posts_rel_link_wp_head', 10 );

/** لینک کشف REST API — خودِ REST فعال می‌ماند. */
remove_action( 'wp_head', 'rest_output_link_wp_head', 10 );
remove_action( 'template_redirect', 'rest_output_link_header', 11 );

/** کشف oEmbed و اسکریپت میزبان آن. */
remove_action( 'wp_head', 'wp_oembed_add_discovery_links' );
remove_action( 'wp_head', 'wp_oembed_add_host_js' );

/** dns-prefetch به s.w.org — یک اعلان آشکار «اینجا وردپرس است». */
add_filter( 'wp_resource_hints', 'topersia_strip_wp_hints', 10, 2 );

function topersia_strip_wp_hints( $hints, $relation ) {

	if ( 'dns-prefetch' !== $relation ) {
		return $hints;
	}

	foreach ( $hints as $key => $hint ) {

		if ( false !== strpos( (string) $hint, 's.w.org' ) ) {
			unset( $hints[ $key ] );
		}
	}

	return array_values( $hints );
}

/**
 * اسکریپت ایموجی.
 *
 * هم یک درخواست اضافه است، هم Twemoji در فهرست شناسایی Wappalyzer ظاهر
 * می‌شود. مرورگرهای امروزی ایموجی را بومی نمایش می‌دهند.
 */
remove_action( 'wp_head', 'print_emoji_detection_script', 7 );
remove_action( 'wp_print_styles', 'print_emoji_styles' );
remove_action( 'admin_print_scripts', 'print_emoji_detection_script' );
remove_action( 'admin_print_styles', 'print_emoji_styles' );
remove_filter( 'the_content_feed', 'wp_staticize_emoji' );
remove_filter( 'comment_text_rss', 'wp_staticize_emoji' );
remove_filter( 'wp_mail', 'wp_staticize_emoji_for_email' );

add_filter( 'tiny_mce_plugins', 'topersia_strip_emoji_tinymce' );

function topersia_strip_emoji_tinymce( $plugins ) {
	return is_array( $plugins ) ? array_diff( $plugins, array( 'wpemoji' ) ) : array();
}

/** اسکریپت wp-embed — فقط برای جاسازی نوشته‌های وردپرسی دیگر لازم است. */
add_action( 'wp_footer', 'topersia_dequeue_wp_embed' );

function topersia_dequeue_wp_embed() {
	wp_dequeue_script( 'wp-embed' );
}

/**
 * نسخهٔ افزونه‌ها و قالب در رشتهٔ ?ver=.
 *
 * چرا حذف کامل نمی‌کنیم: بدون نسخه، مرورگر پس از هر به‌روزرسانی فایل قدیمی
 * کش‌شده را نشان می‌دهد. به‌جایش زمان آخرین تغییر فایل را می‌گذاریم — هم کش
 * درست باطل می‌شود، هم شمارهٔ نسخه فاش نمی‌شود.
 */
add_filter( 'script_loader_src', 'topersia_version_to_mtime', 100 );
add_filter( 'style_loader_src', 'topersia_version_to_mtime', 100 );

function topersia_version_to_mtime( $src ) {

	if ( is_admin() || ! is_string( $src ) || false === strpos( $src, 'ver=' ) ) {
		return $src;
	}

	$home = untrailingslashit( home_url() );

	// فقط دارایی‌های همین سایت — منابع بیرونی دست‌نخورده می‌مانند.
	if ( 0 !== strpos( $src, $home ) ) {
		return $src;
	}

	$clean = strtok( str_replace( $home, '', $src ), '?' );

	$path = str_replace(
		array( '/' . TOPERSIA_ASSETS_PATH . '/', '/' . TOPERSIA_CORE_PATH . '/' ),
		array( '/wp-content/', '/wp-includes/' ),
		$clean
	);

	$file = untrailingslashit( ABSPATH ) . $path;

	if ( ! file_exists( $file ) ) {
		return remove_query_arg( 'ver', $src );
	}

	return add_query_arg( 'ver', filemtime( $file ), remove_query_arg( 'ver', $src ) );
}

/**
 * XML-RPC.
 *
 * مسیر کلاسیک حملهٔ brute force توزیع‌شده و تقویت DDoS. این سایت از
 * اپلیکیشن موبایل وردپرس یا پینگ‌بک استفاده نمی‌کند، پس نیازی نیست.
 */
add_filter( 'xmlrpc_enabled', '__return_false' );
add_filter( 'wp_headers', 'topersia_strip_pingback_header' );

function topersia_strip_pingback_header( $headers ) {

	unset( $headers['X-Pingback'] );

	return $headers;
}

/**
 * پیام خطای ورود.
 *
 * پیام پیش‌فرض وردپرس تفکیک می‌کند که نام کاربری اشتباه است یا رمز — یعنی
 * به مهاجم می‌گوید کدام نام کاربری واقعی است.
 */
add_filter( 'login_errors', 'topersia_generic_login_error' );

function topersia_generic_login_error() {
	return __( 'اطلاعات ورود نادرست است.', 'topersia-core' );
}

/**
 * قواعد پیش‌بارگذاری (Speculative Loading).
 *
 * وردپرس ۶٫۸ به بعد یک بلوک JSON در فوتر منتشر می‌کند که مسیرهای مستثنا از
 * پیش‌واکشی را فهرست می‌کند — و آن فهرست شامل «/geo/wp-admin/» است. این
 * تنها جایی است که مسیر نصب هنوز نشت می‌کند.
 *
 * چرا ماسکش نمی‌کنیم: اگر /geo/wp-admin/ را به /wp-admin/ تبدیل کنیم،
 * لینک‌های نوار مدیریت برای کاربر واردشده می‌شکنند، چون /wp-admin/ در ریشه
 * وجود ندارد.
 *
 * راه‌حل: برای بازدیدکنندهٔ عادی این استثناها را حذف می‌کنیم — چون در صفحهٔ
 * او اصلاً لینک مدیریتی وجود ندارد که نیاز به استثنا داشته باشد. برای کاربر
 * واردشده دست‌نخورده می‌ماند، چون او خودش ادمین است.
 */
add_filter( 'wp_speculation_rules_href_exclude_paths', 'topersia_clean_speculation_paths' );

function topersia_clean_speculation_paths( $paths ) {

	if ( is_user_logged_in() || ! is_array( $paths ) ) {
		return $paths;
	}

	$needle = '/' . TOPERSIA_WP_DIR . '/';

	return array_values(
		array_filter(
			$paths,
			function ( $path ) use ( $needle ) {
				return false === strpos( (string) $path, $needle );
			}
		)
	);
}

/**
 * استایل‌های ویرایشگر بلوک.
 *
 * این سایت با ویرایشگر کلاسیک و المنتور ساخته می‌شود و هیچ بلوکی ندارد، ولی
 * وردپرس همچنان کتابخانهٔ کامل CSS بلوک‌ها را بارگذاری می‌کند — حدود ۴۰
 * کیلوبایت بی‌مصرف که هم سرعت را می‌گیرد و هم امضای آشکار وردپرس است.
 *
 * اگر پس از این تغییر جایی از استایل شکست، فلگش را در پنل خاموش کن.
 */
add_action( 'wp_enqueue_scripts', 'topersia_drop_block_styles', 100 );

function topersia_drop_block_styles() {

	if ( ! TOPERSIA_DROP_BLOCK_CSS || is_admin() ) {
		return;
	}

	wp_dequeue_style( 'wp-block-library' );
	wp_dequeue_style( 'wp-block-library-theme' );
	wp_dequeue_style( 'classic-theme-styles' );
}

/** فهرست کاربران از REST API — مسیر رایج کشف نام کاربری ادمین. */
add_filter( 'rest_endpoints', 'topersia_block_user_enumeration' );

function topersia_block_user_enumeration( $endpoints ) {

	if ( is_user_logged_in() ) {
		return $endpoints;
	}

	unset( $endpoints['/wp/v2/users'] );
	unset( $endpoints['/wp/v2/users/(?P<id>[\d]+)'] );

	return $endpoints;
}

/** کشف نام کاربری از راه ?author=1 */
add_action( 'template_redirect', 'topersia_block_author_scan' );

function topersia_block_author_scan() {

	if ( is_admin() || is_user_logged_in() ) {
		return;
	}

	if ( isset( $_GET['author'] ) && '' !== $_GET['author'] ) {
		wp_safe_redirect( home_url(), 301 );
		exit;
	}
}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۱۳ — پنل مدیریت ToPersia
 * ═══════════════════════════════════════════════════════════════════════
 * سه زبانه: تنظیمات · تشخیص · راهنما. افزونهٔ شِما زبانهٔ خودش را از راه
 * فیلتر topersia_admin_tabs اضافه می‌کند؛ اگر غیرفعال باشد، زبانه‌اش
 * خودبه‌خود ناپدید می‌شود.
 *
 * ── آنچه اینجا هست ────────────────────────────────────────────────────
 * پیکربندی‌ای که به‌ندرت ولی حتماً عوض می‌شود: شناسهٔ رابطه‌ها، فلگ‌های
 * رفتاری، مسیرهای ماسک. اینها تنها چیزی بودند که رفتن به سرور را لازم
 * می‌کردند.
 *
 * و مهم‌تر: تشخیص خودکار. همان بررسی‌هایی که تا امروز فقط با اسکریپت و
 * به‌صورت دستی انجام می‌شد. پنج نقص خاموشی که در ممیزی ۳۱ اوت ۲۰۲۶ کشف شد
 * — واژه‌نامهٔ هم‌نام تکراری، متاکلید مشترک با دو واژه‌نامهٔ متفاوت،
 * Repeater بدون row_status، تنظیم اعمال‌نشده — همگی از این نوع بودند: نه
 * خطا می‌دادند، نه در هیچ صفحه‌ای دیده می‌شدند.
 *
 * ── آنچه عمداً اینجا نیست ─────────────────────────────────────────────
 * ویرایشگر کد. سه دلیل:
 *
 * ۱. یک خطای نحوی در ویرایشگر زنده یعنی صفحهٔ سفید روی کل سایت، و تنها راه
 *    نجاتش دسترسی مستقیم به فایل است. پس ویرایشگر پیشخوان وابستگی به سرور
 *    را حذف نمی‌کند — فقط یک راه تازه برای ساختن آن اضطرار اضافه می‌کند.
 * ۲. بخش ۱۲ همین فایل کل فلسفه‌اش کاهش سطح حمله است. ویرایشگر کد در
 *    پیشخوان دقیقاً برعکس آن است.
 * ۳. حاکمیت این پروژه بر «هر چیزی یک فایل نسخه‌دار و بازتولیدپذیر است» بنا
 *    شده. ویرایش مستقیم در دیتابیس، آن را نابود می‌کند.
 */

/** ثبت منوی سطح‌بالا. */
add_action( 'admin_menu', 'topersia_admin_menu' );

function topersia_admin_menu() {

	/* جای ۲ یعنی بلافاصله زیر پیشخوان. همهٔ افزونه‌های ToPersia زیر همین
	   یک منو جمع می‌شوند تا منوی وردپرس بالا و پایین نشود.  P5-D166 */
	add_menu_page(
		'ToPersia Core',
		'ToPersia Core',
		'manage_options',
		'topersia',
		'topersia_admin_page',
		'dashicons-admin-site-alt3',
		2
	);

	/* زیرمنوی نخست هم‌نام صفحهٔ اصلی است، وگرنه وردپرس «ToPersia Core» را
	   دو بار نشان می‌دهد. */
	add_submenu_page( 'topersia', 'هسته', 'هسته', 'manage_options', 'topersia', 'topersia_admin_page' );
}

/**
 * شیوه‌نامهٔ مرجع پنل مدیریت.
 *
 * این تابع منبع واحد زبان بصری پنل‌های ToPersia است. افزونهٔ نمایش و افزونهٔ
 * کاربر همین را صدا می‌زنند، پس اگر رنگ یا شعاع گوشه اینجا عوض شود، هر سه
 * پنل با هم عوض می‌شوند. جهت وابستگی درست است: آن‌ها به هسته تکیه می‌کنند،
 * نه برعکس.
 *
 * رنگ‌ها از ستون «روز» پالت پروژه‌اند.  P5-D166
 *
 * @return string
 */
function topersia_admin_css() {

	return '
.tp-admin{
  --c-bg:#F4EFE6; --c-card:#FAF7F1; --c-line:#DDD5C8;
  --c-ink:#2A2A28; --c-ink-2:#6F6B64;
  --c-teal:#177E7A; --c-teal-deep:#0F6461; --c-amber:#B9871A; --c-red:#73292C;
  --c-green:#3F7C4E; --c-radius:12px;
  max-inline-size:1240px; color:var(--c-ink); font-size:14px; line-height:1.9;
}
.tp-admin *{box-sizing:border-box}
.tp-admin__head{display:flex; align-items:flex-end; gap:1rem; flex-wrap:wrap; margin-block:1rem .4rem}
.tp-admin__head h1{margin:0; font-size:1.6rem; font-weight:800; color:var(--c-ink)}
.tp-admin__head p{margin:0; color:var(--c-ink-2); max-inline-size:58ch}

.tp-tabs{display:inline-flex; gap:2px; padding:3px; margin-block:1.1rem .9rem; flex-wrap:wrap;
  background:var(--c-bg); border:1px solid var(--c-line); border-radius:999px}
.tp-tabs a,.tp-tabs button{font:inherit; font-weight:700; font-size:13.5px; cursor:pointer;
  padding:.42rem 1.05rem; border:0; border-radius:999px; background:transparent;
  color:var(--c-ink-2); text-decoration:none; line-height:1.9}
.tp-tabs a:hover,.tp-tabs button:hover{color:var(--c-teal)}
.tp-tabs a.is-on,.tp-tabs button[aria-selected="true"]{background:var(--c-teal); color:#fff}
.tp-tabs a:focus-visible,.tp-tabs button:focus-visible{outline:3px solid var(--c-teal); outline-offset:2px}

.tp-panel[hidden]{display:none}
.tp-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(330px,1fr)); gap:1.1rem; align-items:start}
.tp-card{background:var(--c-card); border:1px solid var(--c-line); border-radius:var(--c-radius);
  padding:1.1rem 1.2rem 1.2rem}
.tp-card h2{margin:0 0 .2rem; font-size:.95rem; font-weight:800; color:var(--c-ink)}
.tp-card p.hint{margin:0 0 .9rem; font-size:12.5px; color:var(--c-ink-2)}
.tp-card--wide{grid-column:1/-1}

.tp-field{display:grid; grid-template-columns:1fr auto; gap:.35rem .8rem;
  align-items:center; padding-block:.55rem; border-block-start:1px solid var(--c-line)}
.tp-field:first-of-type{border-block-start:0}
.tp-field label{font-weight:600}
.tp-field .note{grid-column:1/-1; margin:0; font-size:12px; color:var(--c-ink-2)}
.tp-field--stack{grid-template-columns:1fr}

.tp-admin :is(input[type="text"],input[type="url"],input[type="number"],input[type="password"],input[type="search"],select,textarea){
  font:inherit; padding:.35rem .6rem; border:1px solid var(--c-line); border-radius:8px;
  background:#fff; color:var(--c-ink); max-inline-size:100%}
.tp-admin input[type="number"]{inline-size:5.5rem; text-align:center}
.tp-admin :is(input,select,textarea):focus{border-color:var(--c-teal);
  outline:2px solid rgba(23,126,122,.25); outline-offset:0}

.tp-admin table.widefat{border-color:var(--c-line); border-radius:var(--c-radius); overflow:hidden}
.tp-admin table.widefat th{background:var(--c-bg); color:var(--c-ink); font-weight:700}
.tp-admin table.form-table th{color:var(--c-ink); font-weight:700}

.tp-pill{display:inline-flex; align-items:center; gap:.4rem; padding:.28rem .8rem;
  border-radius:999px; font-weight:700; font-size:12.5px; border:1.5px solid currentColor}
.tp-pill--ok{color:var(--c-green)} .tp-pill--warn{color:var(--c-amber)} .tp-pill--bad{color:var(--c-red)}

.tp-save{position:sticky; inset-block-end:0; margin-block-start:1.2rem; padding:.9rem 0;
  background:linear-gradient(to top, #F4EFE6 65%, rgba(244,239,230,0))}
.tp-admin .button-primary{background:var(--c-teal); border-color:var(--c-teal); box-shadow:none;
  border-radius:999px; padding-inline:1.4rem; height:auto; line-height:2.1}
.tp-admin .button-primary:hover{background:var(--c-teal-deep); border-color:var(--c-teal-deep)}
.tp-admin .button{border-radius:999px}
';
}

/** زبانه‌های موجود. افزونه‌های دیگر با این فیلتر زبانه اضافه می‌کنند. */
function topersia_admin_tabs() {

	$tabs = array(
		'settings'    => array(
			'label'    => 'تنظیمات',
			'callback' => 'topersia_admin_tab_settings',
		),
		'diagnostics' => array(
			'label'    => 'تشخیص',
			'callback' => 'topersia_admin_tab_diagnostics',
		),
	);

	$tabs = apply_filters( 'topersia_admin_tabs', $tabs );

	// راهنما همیشه آخرین زبانه است.
	$tabs['help'] = array(
		'label'    => 'راهنما',
		'callback' => 'topersia_admin_tab_help',
	);

	return $tabs;
}

/** صفحهٔ اصلی — ذخیرهٔ فرم و رندر زبانه‌ها. */
function topersia_admin_page() {

	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( esc_html__( 'دسترسی ندارید.', 'topersia-core' ) );
	}

	$tabs    = topersia_admin_tabs();
	$current = isset( $_GET['tab'] ) ? sanitize_key( wp_unslash( $_GET['tab'] ) ) : 'settings';

	if ( ! isset( $tabs[ $current ] ) ) {
		$current = 'settings';
	}

	echo '<style>' . topersia_admin_css() . '</style>';
	echo '<div class="wrap tp-admin" dir="rtl">';

	echo '<div class="tp-admin__head"><h1>ToPersia Core</h1>'
		. '<p>' . esc_html( 'هستهٔ دانشنامه: تنظیمات، ثبت رویداد، اسکلت جغرافیایی و ابزارهای تشخیص.' ) . '</p></div>';

	topersia_admin_handle_save();

	echo '<nav class="tp-tabs" aria-label="' . esc_attr( 'زبانه‌های پنل' ) . '">';

	foreach ( $tabs as $slug => $tab ) {
		printf(
			'<a href="%s" class="%s"%s>%s</a>',
			esc_url( admin_url( 'admin.php?page=topersia&tab=' . $slug ) ),
			$slug === $current ? 'is-on' : '',
			$slug === $current ? ' aria-current="page"' : '',
			esc_html( $tab['label'] )
		);
	}

	echo '</nav>';

	if ( is_callable( $tabs[ $current ]['callback'] ) ) {
		call_user_func( $tabs[ $current ]['callback'] );
	}

	echo '</div>';
}

/** ذخیرهٔ فرم تنظیمات. */
function topersia_admin_handle_save() {

	if ( empty( $_POST['topersia_save'] ) ) {
		return;
	}

	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}

	if ( ! isset( $_POST['topersia_nonce'] )
		|| ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['topersia_nonce'] ) ), 'topersia_settings' )
	) {
		echo '<div class="notice notice-error"><p>توکن امنیتی نامعتبر است. صفحه را دوباره باز کن و از نو تلاش کن.</p></div>';
		return;
	}

	$schema = topersia_settings_schema();
	$clean  = array();

	foreach ( $schema as $key => $spec ) {

		if ( 'bool' === $spec['type'] ) {
			$clean[ $key ] = ! empty( $_POST[ 'topersia_' . $key ] );
			continue;
		}

		$raw = isset( $_POST[ 'topersia_' . $key ] ) ? wp_unslash( $_POST[ 'topersia_' . $key ] ) : '';

		if ( 'int' === $spec['type'] ) {

			$clean[ $key ] = absint( $raw );

		} elseif ( 'select' === $spec['type'] ) {

			$raw           = sanitize_text_field( (string) $raw );
			$clean[ $key ] = isset( $spec['choices'][ $raw ] ) ? $raw : $spec['default'];

		} elseif ( isset( $spec['sanitize'] ) && 'slug' === $spec['sanitize'] ) {

			/*
			 * مسیرهای ماسک فقط حروف و عدد و خط تیره می‌پذیرند — هر کاراکتر
			 * دیگری جدول جایگزینی را می‌شکند و نشتی /geo برمی‌گردد.
			 */
			$clean[ $key ] = preg_replace( '/[^a-z0-9_-]/i', '', sanitize_text_field( (string) $raw ) );

		} else {

			/*
			 * بقیهٔ فیلدهای متنی متن انسانی‌اند — مثل پسوند برند که خط تیرهٔ
			 * بلند و حرف فارسی دارد. تا نسخهٔ ۴.۱.۴ همان پاک‌سازی سختِ مسیرها
			 * روی همهٔ فیلدهای متنی اجرا می‌شد؛ اگر آن‌وقت فیلد متنی دیگری
			 * اضافه می‌شد، مقدارش بی‌صدا خالی ذخیره می‌شد.
			 */
			$clean[ $key ] = sanitize_text_field( (string) $raw );
		}
	}

	update_option( TOPERSIA_OPTION_KEY, $clean, true );

	echo '<div class="notice notice-success"><p><strong>تنظیمات ذخیره شد.</strong> ثابت‌ها در بارگذاری بعدی صفحه اعمال می‌شوند — یک بار صفحه را تازه کن.</p></div>';
}

/**
 * اگر تنظیمی در wp-config قفل شده، مقدار مؤثرش را برمی‌گرداند.
 *
 * چرا لازم است: بدون این، کاربر مقداری را در فرم عوض می‌کند، ذخیره هم
 * می‌شود، ولی هیچ اثری ندارد — و هیچ‌جا هم گفته نمی‌شود چرا. یک شکست خاموش
 * دیگر، دقیقاً از همان جنسی که این پنل برای کشفشان ساخته شده.
 *
 * @return string|false مقدار مؤثر اگر قفل است، وگرنه false.
 */
function topersia_admin_constant_for( $key ) {

	$map = array(
		'rel_province_county' => 'TOPERSIA_REL_PROVINCE_COUNTY',
		'rel_county_city'     => 'TOPERSIA_REL_COUNTY_CITY',
		'rel_route_province'  => 'TOPERSIA_REL_ROUTE_PROVINCE',
		'rel_route_city'      => 'TOPERSIA_REL_ROUTE_CITY',
		'rel_route_village'   => 'TOPERSIA_REL_ROUTE_VILLAGE',
		'rel_route_island'    => 'TOPERSIA_REL_ROUTE_ISLAND',
		'rel_province_currency' => 'TOPERSIA_REL_PROVINCE_CURRENCY',
		'glossary_row_status'   => 'TOPERSIA_GLOSSARY_ROW_STATUS',
		'auto_province'       => 'TOPERSIA_AUTO_PROVINCE',
		'wp_dir'              => 'TOPERSIA_WP_DIR',
		'assets_path'         => 'TOPERSIA_ASSETS_PATH',
		'core_path'           => 'TOPERSIA_CORE_PATH',
		'mask_output'         => 'TOPERSIA_MASK_OUTPUT',
		'drop_block_css'      => 'TOPERSIA_DROP_BLOCK_CSS',
	);

	if ( ! isset( $map[ $key ] ) || ! defined( $map[ $key ] ) ) {
		return false;
	}

	$effective = constant( $map[ $key ] );
	$stored    = topersia_setting( $key );

	$as_string = function ( $value ) {
		if ( is_bool( $value ) ) {
			return $value ? '1' : '0';
		}
		return (string) $value;
	};

	// اگر مقدار مؤثر با مقدار تنظیم یکی است، قفلی در کار نیست.
	if ( $as_string( $effective ) === $as_string( $stored ) ) {
		return false;
	}

	return is_bool( $effective ) ? ( $effective ? 'روشن' : 'خاموش' ) : (string) $effective;
}

/** زبانهٔ تنظیمات. */
function topersia_admin_tab_settings() {

	$schema = topersia_settings_schema();
	$values = topersia_settings();

	$groups = array(
		'relations' => 'شناسه‌های رابطه و واژه‌نامه',
		'behaviour' => 'رفتار',
		'logging'   => 'ثبت رویداد',
		'masking'   => 'پنهان‌سازی مسیر و بهینه‌سازی',
	);

	echo '<p style="max-width:62em">ترتیب تقدم: <code>define</code> در <code>wp-config.php</code> ← تنظیم همین صفحه ← پیش‌فرض کد. اگر تنظیمی اینجا اثر نکرد، در <code>wp-config.php</code> قفل شده و همین‌جا با نشان 🔒 علامت می‌خورد.</p>';

	echo '<form method="post">';
	wp_nonce_field( 'topersia_settings', 'topersia_nonce' );

	foreach ( $groups as $group => $title ) {

		echo '<h2>' . esc_html( $title ) . '</h2>';
		echo '<table class="form-table" role="presentation"><tbody>';

		foreach ( $schema as $key => $spec ) {

			if ( $spec['group'] !== $group ) {
				continue;
			}

			$name   = 'topersia_' . $key;
			$value  = $values[ $key ];
			$locked = topersia_admin_constant_for( $key );

			echo '<tr><th scope="row"><label for="' . esc_attr( $name ) . '">' . esc_html( $spec['label'] ) . '</label></th><td>';

			if ( 'bool' === $spec['type'] ) {

				printf(
					'<label><input type="checkbox" id="%1$s" name="%1$s" value="1" %2$s %3$s /> فعال</label>',
					esc_attr( $name ),
					checked( $value, true, false ),
					$locked ? 'disabled' : ''
				);

			} elseif ( 'select' === $spec['type'] ) {

				printf( '<select id="%1$s" name="%1$s" %2$s>', esc_attr( $name ), $locked ? 'disabled' : '' );

				foreach ( $spec['choices'] as $ck => $cl ) {
					printf( '<option value="%s" %s>%s</option>', esc_attr( $ck ), selected( $value, $ck, false ), esc_html( $cl ) );
				}

				echo '</select>';

			} else {
				printf(
					'<input type="%1$s" id="%2$s" name="%2$s" value="%3$s" class="regular-text" %4$s />',
					'int' === $spec['type'] ? 'number' : 'text',
					esc_attr( $name ),
					esc_attr( $value ),
					$locked ? 'disabled' : ''
				);
			}

			if ( $locked ) {
				echo '<p class="description" style="color:#b32d2e">🔒 در <code>wp-config.php</code> قفل شده است. مقدار مؤثر: <code>' . esc_html( $locked ) . '</code></p>';
			}

			echo '<p class="description">' . esc_html( $spec['help'] ) . '</p>';
			echo '</td></tr>';
		}

		echo '</tbody></table>';
	}

	submit_button( 'ذخیرهٔ تنظیمات', 'primary', 'topersia_save' );
	echo '</form>';
}

/* ─── ابزارهای زبانهٔ تشخیص ─── */

/** یک ردیف نتیجه با وضعیت رنگی چاپ می‌کند. */
function topersia_diag_row( $label, $status, $detail = '' ) {

	$colors = array(
		'ok'   => array( '#00a32a', '✅' ),
		'warn' => array( '#dba617', '⚠️' ),
		'fail' => array( '#d63638', '🔴' ),
		'info' => array( '#2271b1', 'ℹ️' ),
	);

	$c = isset( $colors[ $status ] ) ? $colors[ $status ] : $colors['info'];

	printf(
		'<tr><td style="width:20em"><strong>%s</strong></td><td style="width:3em;color:%s">%s</td><td>%s</td></tr>',
		esc_html( $label ),
		esc_attr( $c[0] ),
		esc_html( $c[1] ),
		wp_kses_post( $detail )
	);
}

/** همهٔ متاباکس‌های JetEngine را برمی‌گرداند. */
function topersia_diag_meta_boxes() {

	if ( ! function_exists( 'jet_engine' ) || ! isset( jet_engine()->meta_boxes ) ) {
		return array();
	}

	$items = jet_engine()->meta_boxes->get_items();

	return is_array( $items ) ? $items : array();
}

/**
 * نگاشت شناسهٔ رابطه به نام و جهت، مستقیم از جدول JetEngine.
 *
 * چرا از جدول و نه از شیء رابطه: نسخهٔ ۴.۱.۲ سه متد مختلف روی شیء را
 * امتحان کرد و هر سه خالی برگشتند — ستون نام در جدول تشخیص خالی ماند.
 * به‌جای امتحان‌کردن متد چهارم، همان مسیری استفاده می‌شود که برای
 * واژه‌نامه‌ها اثبات شده است: خواندن ردیف خام و رمزگشایی labels و args.
 *
 * جهت رابطه هم برمی‌گردد. بدون آن، یک شناسهٔ اشتباه که تصادفاً به رابطهٔ
 * موجودِ دیگری اشاره کند، سبز نشان داده می‌شد. با دیدن «tp_province ←
 * tp_county» می‌فهمی شناسه درست است، نه فقط معتبر.
 *
 * @return array نگاشت شناسه به array( name, parent, child )
 */
function topersia_diag_relation_map() {

	static $map = null;

	if ( null !== $map ) {
		return $map;
	}

	$map = array();

	if ( ! function_exists( 'jet_engine' ) || ! isset( jet_engine()->relations ) ) {
		return $map;
	}

	if ( ! isset( jet_engine()->relations->data ) ) {
		return $map;
	}

	$items = jet_engine()->relations->data->get_items();

	if ( ! is_array( $items ) ) {
		return $map;
	}

	foreach ( $items as $item ) {

		if ( is_object( $item ) ) {
			$item = get_object_vars( $item );
		}

		if ( ! is_array( $item ) || empty( $item['id'] ) ) {
			continue;
		}

		$labels = topersia_diag_decode( isset( $item['labels'] ) ? $item['labels'] : '' );
		$args   = topersia_diag_decode( isset( $item['args'] ) ? $item['args'] : '' );

		$name = '';

		$candidates = array(
			isset( $labels['name'] ) ? $labels['name'] : null,
			isset( $args['name'] ) ? $args['name'] : null,
			isset( $item['slug'] ) ? $item['slug'] : null,
		);

		foreach ( $candidates as $candidate ) {

			if ( ! empty( $candidate ) && is_string( $candidate ) ) {
				$name = $candidate;
				break;
			}
		}

		$strip = function ( $value ) {
			return is_string( $value ) ? str_replace( 'posts::', '', $value ) : '';
		};

		$map[ (string) $item['id'] ] = array(
			'name'   => $name,
			'parent' => $strip( isset( $args['parent_object'] ) ? $args['parent_object'] : '' ),
			'child'  => $strip( isset( $args['child_object'] ) ? $args['child_object'] : '' ),
		);
	}

	return $map;
}

/**
 * نام خوانای یک رابطه، از هر مسیری که در دسترس باشد.
 *
 * چرا چند مسیر: ساختار داخلی JetEngine مستند نیست و بین نسخه‌ها تغییر
 * می‌کند. نسخهٔ ۴.۱.۰ فقط get_arg('labels') را امتحان می‌کرد و روی محیط
 * زنده خالی برمی‌گشت — ستون نام در جدول رابطه‌ها خالی می‌ماند بدون اینکه
 * معلوم باشد چرا.
 *
 * @return string نام، یا رشتهٔ خالی اگر هیچ مسیری جواب نداد.
 */
function topersia_diag_relation_name( $relation ) {

	if ( ! is_object( $relation ) ) {
		return '';
	}

	if ( method_exists( $relation, 'get_arg' ) ) {

		$labels = topersia_diag_decode( $relation->get_arg( 'labels' ) );

		if ( ! empty( $labels['name'] ) ) {
			return (string) $labels['name'];
		}

		foreach ( array( 'name', 'slug' ) as $key ) {

			$value = $relation->get_arg( $key );

			if ( ! empty( $value ) && is_string( $value ) ) {
				return $value;
			}
		}
	}

	if ( method_exists( $relation, 'get_labels' ) ) {

		$labels = topersia_diag_decode( $relation->get_labels() );

		if ( ! empty( $labels['name'] ) ) {
			return (string) $labels['name'];
		}
	}

	return '';
}

/**
 * یک مقدار کدشدهٔ JetEngine را به آرایه برمی‌گرداند.
 *
 * جدول‌های JetEngine همه یک شکل دارند — id · slug · status · labels · args ·
 * meta_fields — و سه ستون آخر رشتهٔ کدشده‌اند. بسته به نوع موجودیت، گاهی
 * PHP-serialized و گاهی JSON. هر دو امتحان می‌شوند.
 *
 * unserialize با allowed_classes = false صدا زده می‌شود. بدون این پرچم، یک
 * رشتهٔ دستکاری‌شده می‌تواند نمونهٔ شیء بسازد و متد __wakeup آن اجرا شود.
 * اینجا داده از پایگاه‌دادهٔ خودمان می‌آید و صفحه هم فقط برای مدیر باز
 * می‌شود، ولی محدودکردن هزینه‌ای ندارد و یک سطح حمله را می‌بندد.
 */
function topersia_diag_decode( $value ) {

	if ( is_array( $value ) ) {
		return $value;
	}

	if ( is_object( $value ) ) {
		return get_object_vars( $value );
	}

	if ( ! is_string( $value ) || '' === $value ) {
		return array();
	}

	// فقط آرایهٔ سریال‌شده — نه شیء.
	if ( 0 === strpos( $value, 'a:' ) ) {

		$un = @unserialize( $value, array( 'allowed_classes' => false ) );

		if ( is_array( $un ) ) {
			return $un;
		}
	}

	$json = json_decode( $value, true );

	return is_array( $json ) ? $json : array();
}

/**
 * یک آیتم واژه‌نامه را به شکل یکدست درمی‌آورد.
 *
 * چرا این تابع دو بار بازنویسی شد:
 *
 * نسخهٔ ۴.۱.۰ فرض کرده بود آیتم‌ها همان شکل فایل export را دارند
 * (id · name · fields). روی محیط زنده فقط id جواب داد، پس هر ۷۴ واژه‌نامه
 * زیر یک نام خالی گروه‌بندی شدند و بررسیِ «نام تکراری» روی یک نصب سالم
 * هشدار قرمز داد.
 *
 * نسخهٔ ۴.۱.۱ به‌جای حدس دوباره، کلیدهای واقعی را گزارش کرد:
 * id · slug · status · labels · args · meta_fields — یعنی شکل جدول عمومی
 * JetEngine، که در آن slug همیشه خالی است و نام در labels کدشده زندگی
 * می‌کند. همان الگویی که پیش‌تر برای روابط ثابت شده بود.
 *
 * درس: وقتی ساختار دادهٔ یک افزونهٔ ثالث مستند نیست، ابزار تشخیص باید
 * شکل واقعی را گزارش کند، نه اینکه با فرض غلط نتیجهٔ غلط بدهد.
 *
 * @return array|null آرایه با کلیدهای id · name · fields · keys · probed
 */
function topersia_diag_normalize_glossary( $item ) {

	if ( is_object( $item ) ) {
		$item = get_object_vars( $item );
	}

	if ( ! is_array( $item ) ) {
		return null;
	}

	$labels = topersia_diag_decode( isset( $item['labels'] ) ? $item['labels'] : '' );
	$args   = topersia_diag_decode( isset( $item['args'] ) ? $item['args'] : '' );

	/* شناسه */
	$id = '';

	foreach ( array( 'id', 'ID', 'glossary_id', 'term_id' ) as $key ) {

		if ( isset( $item[ $key ] ) && '' !== $item[ $key ] && ! is_array( $item[ $key ] ) ) {
			$id = (string) $item[ $key ];
			break;
		}
	}

	/* نام — به ترتیب احتمال */
	$name       = '';
	$candidates = array(
		isset( $labels['name'] ) ? $labels['name'] : null,
		isset( $args['name'] ) ? $args['name'] : null,
		isset( $item['name'] ) ? $item['name'] : null,
		isset( $item['slug'] ) ? $item['slug'] : null,
		isset( $labels['plural_name'] ) ? $labels['plural_name'] : null,
		isset( $item['title'] ) ? $item['title'] : null,
	);

	foreach ( $candidates as $candidate ) {

		if ( ! empty( $candidate ) && is_string( $candidate ) ) {
			$name = $candidate;
			break;
		}
	}

	/* مقادیر */
	$fields = array();

	foreach ( array( 'meta_fields', 'fields' ) as $key ) {

		if ( isset( $item[ $key ] ) ) {

			$decoded = topersia_diag_decode( $item[ $key ] );

			if ( ! empty( $decoded ) ) {
				$fields = $decoded;
				break;
			}
		}
	}

	if ( empty( $fields ) && ! empty( $args['fields'] ) ) {
		$fields = topersia_diag_decode( $args['fields'] );
	}

	// گاهی آرایه یک سطح تودرتوست: array( array( value, label ), ... )
	if ( ! empty( $fields ) && ! isset( $fields[0] ) && isset( $fields['fields'] ) ) {
		$fields = topersia_diag_decode( $fields['fields'] );
	}

	return array(
		'id'     => $id,
		'name'   => $name,
		'fields' => is_array( $fields ) ? $fields : array(),
		'keys'   => array_keys( $item ),
		'probed' => array(
			'labels' => array_keys( $labels ),
			'args'   => array_keys( $args ),
		),
	);
}

/** همهٔ واژه‌نامه‌های JetEngine، یکدست‌شده. */
function topersia_diag_glossaries() {

	if ( ! function_exists( 'jet_engine' ) || ! isset( jet_engine()->glossaries ) ) {
		return array();
	}

	$items = jet_engine()->glossaries->data->get_items();

	if ( ! is_array( $items ) ) {
		return array();
	}

	$out = array();

	foreach ( $items as $item ) {

		$clean = topersia_diag_normalize_glossary( $item );

		if ( $clean && '' !== $clean['id'] ) {
			$out[] = $clean;
		}
	}

	return $out;
}

/**
 * همهٔ فیلدها را از همهٔ متاباکس‌ها، مسطح‌شده، برمی‌گرداند.
 *
 * هر ردیف: box · name · type · glossary · is_sub · parent
 */
function topersia_diag_all_fields() {

	static $cache = null;

	if ( null !== $cache ) {
		return $cache;
	}

	$cache = array();

	foreach ( topersia_diag_meta_boxes() as $box ) {

		$args   = isset( $box['args'] ) ? $box['args'] : array();
		$args   = is_string( $args ) ? json_decode( $args, true ) : $args;
		$name   = is_array( $args ) && ! empty( $args['name'] ) ? $args['name'] : '—';
		$fields = isset( $box['meta_fields'] ) ? $box['meta_fields'] : array();
		$fields = is_string( $fields ) ? json_decode( $fields, true ) : $fields;

		if ( ! is_array( $fields ) ) {
			continue;
		}

		foreach ( $fields as $field ) {

			if ( empty( $field['name'] ) ) {
				continue;
			}

			$type = isset( $field['type'] ) ? $field['type'] : '';

			$cache[] = array(
				'box'      => $name,
				'name'     => $field['name'],
				'type'     => $type,
				'glossary' => isset( $field['glossary_id'] ) ? (string) $field['glossary_id'] : '',
				'is_sub'   => false,
				'parent'   => '',
			);

			if ( 'repeater' !== $type ) {
				continue;
			}

			$subs = isset( $field['repeater-fields'] ) ? $field['repeater-fields'] : array();

			foreach ( (array) $subs as $sub ) {

				if ( empty( $sub['name'] ) ) {
					continue;
				}

				$cache[] = array(
					'box'      => $name,
					'name'     => $sub['name'],
					'type'     => isset( $sub['type'] ) ? $sub['type'] : '',
					'glossary' => isset( $sub['glossary_id'] ) ? (string) $sub['glossary_id'] : '',
					'is_sub'   => true,
					'parent'   => $field['name'],
				);
			}
		}
	}

	return $cache;
}

/** زبانهٔ تشخیص. */
function topersia_admin_tab_diagnostics() {

	echo '<p style="max-width:62em">این بررسی‌ها همان چیزهایی را می‌گردند که خطا نمی‌دهند و در هیچ صفحه‌ای دیده نمی‌شوند. هر پنج نقصی که در ممیزی ۳۱ اوت ۲۰۲۶ کشف شد از همین نوع بود.</p>';

	/* ═══ محیط ═══ */
	echo '<h2>محیط</h2><table class="widefat striped"><tbody>';

	topersia_diag_row( 'نسخهٔ هسته', 'info', '<code>' . esc_html( TOPERSIA_CORE_VERSION ) . '</code>' );

	if ( defined( 'TOPERSIA_SCHEMA_VERSION' ) ) {
		topersia_diag_row( 'افزونهٔ شِما', 'ok', 'فعال — نسخهٔ <code>' . esc_html( TOPERSIA_SCHEMA_VERSION ) . '</code>' );
	} else {
		topersia_diag_row( 'افزونهٔ شِما', 'fail', 'غیرفعال است. هیچ JSON-LD منتشر نمی‌شود. چون فیلترهای خاموش‌کنندهٔ Rank Math هم در همان افزونه‌اند، شِمای بومی Rank Math برمی‌گردد و صفحه بی‌شِما نمی‌ماند.' );
	}

	topersia_diag_row(
		'JetEngine',
		function_exists( 'jet_engine' ) ? 'ok' : 'fail',
		function_exists( 'jet_engine' ) ? 'فعال' : 'غیرفعال — تقریباً هیچ‌کدام از بررسی‌های زیر معنا ندارند'
	);

	$wpml_on = has_filter( 'wpml_default_language' );

	topersia_diag_row(
		'WPML',
		$wpml_on ? 'ok' : 'warn',
		$wpml_on
			? 'فعال — زبان پیش‌فرض: <code>' . esc_html( (string) apply_filters( 'wpml_default_language', null ) ) . '</code>'
			: 'غیرفعال — منطق چندزبانه غیرفعال است'
	);

	topersia_diag_row(
		'Rank Math',
		class_exists( 'RankMath' ) ? 'ok' : 'warn',
		class_exists( 'RankMath' ) ? 'فعال' : 'غیرفعال — عنوان و توضیح متا از فیلترهای بخش ۸ عبور نمی‌کنند'
	);

	echo '</tbody></table>';

	/* ═══ شناسه‌های رابطه ═══ */
	echo '<h2>شناسه‌های رابطه</h2>';
	echo '<p style="max-width:62em">شناسهٔ رابطهٔ استان ← شهرستان یک بار از ۷ به ۷۲ عوض شد و چون در کد قفل بود، ریدایرکت G4 بی‌صدا شکست تا مدت‌ها بعد. این جدول همان اتفاق را در لحظه نشان می‌دهد.</p>';
	echo '<table class="widefat striped"><tbody>';

	$relations = array(
		'استان ← شهرستان' => TOPERSIA_REL_PROVINCE_COUNTY,
		'شهرستان ← شهر'   => TOPERSIA_REL_COUNTY_CITY,
		'مسیر ← استان'    => TOPERSIA_REL_ROUTE_PROVINCE,
		'مسیر ← شهر'      => TOPERSIA_REL_ROUTE_CITY,
		'مسیر ← روستا'    => TOPERSIA_REL_ROUTE_VILLAGE,
		'مسیر ← جزیره'    => TOPERSIA_REL_ROUTE_ISLAND,
		'استان ← ارز'     => TOPERSIA_REL_PROVINCE_CURRENCY,
	);

	foreach ( $relations as $label => $id ) {

		$relation = topersia_relation( $id );

		if ( ! $relation ) {
			topersia_diag_row( $label, 'fail', 'شناسهٔ <code>' . absint( $id ) . '</code> هیچ رابطهٔ فعالی نیست' );
			continue;
		}

		$map   = topersia_diag_relation_map();
		$entry = isset( $map[ (string) $id ] ) ? $map[ (string) $id ] : array();
		$rname = ! empty( $entry['name'] ) ? $entry['name'] : topersia_diag_relation_name( $relation );

		$direction = '';

		if ( ! empty( $entry['parent'] ) && ! empty( $entry['child'] ) ) {
			$direction = ' · <code>' . esc_html( $entry['parent'] ) . '</code> ← <code>' . esc_html( $entry['child'] ) . '</code>';
		}

		topersia_diag_row(
			$label,
			'ok',
			'شناسهٔ <code>' . absint( $id ) . '</code>' .
			( $rname ? ' — <code>' . esc_html( $rname ) . '</code>' : ' — <em>نام خوانده نشد</em>' ) .
			$direction
		);
	}

	/*
	 * API واقعی شیء رابطه.
	 *
	 * چرا این ردیف هست: فراخوانی delete_rel در نسخهٔ ۴.۳.۰ خطای مرگبار داد،
	 * چون نامش حدس زده شده بود و هرگز اجرا نشده بود تا کشف شود. به‌جای حدس
	 * دوباره، متدهای واقعی گزارش می‌شوند — همان روشی که برای کلیدهای
	 * واژه‌نامه جواب داد.
	 */
	$sample = topersia_relation( TOPERSIA_REL_PROVINCE_COUNTY );

	if ( $sample ) {

		$methods = topersia_relation_methods( $sample );

		$has_connect    = array_intersect( $methods, array( 'update', 'set_relation', 'add_relation' ) );
		$has_disconnect = array_intersect( $methods, array( 'delete_rows', 'delete_rel', 'remove_relation', 'delete_relation' ) );

		$signatures = array();

		foreach ( array_merge( $has_connect, $has_disconnect ) as $method ) {

			$signature = topersia_relation_signature( $sample, $method );

			if ( $signature ) {
				$signatures[] = '<code>' . esc_html( $signature ) . '</code>';
			}
		}

		topersia_diag_row(
			'متدهای شیء رابطه',
			$has_connect && $has_disconnect ? 'ok' : 'warn',
			'<code>' . esc_html( implode( '، ', $methods ) ) . '</code><br>' .
			'ساخت یال: ' . ( $has_connect ? '<code>' . esc_html( implode( '، ', $has_connect ) ) . '</code>' : '⚠️ هیچ متد شناخته‌شده‌ای' ) . ' · ' .
			'برداشتن یال: ' . ( $has_disconnect ? '<code>' . esc_html( implode( '، ', $has_disconnect ) ) . '</code>' : '⚠️ هیچ متد شناخته‌شده‌ای' ) .
			( $signatures ? '<br>امضا: ' . implode( ' · ', $signatures ) : '' ) .
			( $has_connect && $has_disconnect ? '' : '<br><em>همین فهرست را بفرست تا نام درست در کد جایگزین شود.</em>' ) .
			'<br><em>متد <code>cleanup_relation</code> عمداً هرگز صدا زده نمی‌شود — کل رابطه را پاک می‌کند، نه یک یال را.</em>'
		);
	}

	echo '</tbody></table>';

	$fields = topersia_diag_all_fields();

	/* ═══ واژه‌نامه‌ها ═══ */
	echo '<h2>واژه‌نامه‌ها</h2><table class="widefat striped"><tbody>';

	$glossaries = topersia_diag_glossaries();

	if ( empty( $glossaries ) ) {

		topersia_diag_row( 'خواندن واژه‌نامه‌ها', 'warn', 'JetEngine فهرست واژه‌نامه‌ها را برنگرداند' );

	} else {

		topersia_diag_row( 'تعداد', 'info', number_format_i18n( count( $glossaries ) ) . ' واژه‌نامه' );

		// آیا اصلاً نام واژه‌نامه‌ها قابل خواندن است؟
		$named = 0;

		foreach ( $glossaries as $g ) {
			if ( '' !== $g['name'] ) {
				$named ++;
			}
		}

		if ( 0 === $named ) {

			$sample = isset( $glossaries[0] ) ? $glossaries[0] : array();

			topersia_diag_row(
				'خواندن نام واژه‌نامه‌ها',
				'warn',
				'نام هیچ واژه‌نامه‌ای از ساختار دادهٔ JetEngine خوانده نشد، پس بررسی نام تکراری انجام نمی‌شود.<br>' .
				'کلیدهای آیتم: <code>' . esc_html( implode( '، ', isset( $sample['keys'] ) ? $sample['keys'] : array() ) ) . '</code><br>' .
				'کلیدهای <code>labels</code>: <code>' . esc_html( implode( '، ', isset( $sample['probed']['labels'] ) ? $sample['probed']['labels'] : array() ) ) . '</code><br>' .
				'کلیدهای <code>args</code>: <code>' . esc_html( implode( '، ', isset( $sample['probed']['args'] ) ? $sample['probed']['args'] : array() ) ) . '</code><br>' .
				'<em>هشدار دربارهٔ خودِ ابزار تشخیص است، نه دربارهٔ داده. همین سه فهرست را بفرست تا نگاشت قطعی شود.</em>'
			);

		} else {

			// نام تکراری — همان نقصی که مکانیزم بازنشستگی ردیف را روی P1 شکسته بود.
			$by_name = array();

			foreach ( $glossaries as $g ) {

				if ( '' === $g['name'] ) {
					continue; // بی‌نام‌ها هرگز به‌عنوان تکراری شمرده نمی‌شوند.
				}

				$by_name[ $g['name'] ][] = $g['id'];
			}

			$dupes = array();

			foreach ( $by_name as $gname => $ids ) {

				if ( count( $ids ) > 1 ) {
					$dupes[] = '<code>' . esc_html( $gname ) . '</code> → شناسه‌های ' . esc_html( implode( '، ', $ids ) );
				}
			}

			topersia_diag_row(
				'نام تکراری',
				$dupes ? 'fail' : 'ok',
				$dupes
					? implode( '<br>', $dupes ) . '<br><em>واژه‌نامهٔ هم‌نام یعنی مقداری که به یکی اضافه می‌کنی ممکن است در آن یکی بنشیند و هیچ فیلدی نبیندش.</em>'
					: 'هیچ — ' . number_format_i18n( $named ) . ' واژه‌نامه با نام یکتا'
			);

			// پیشوند نام‌گذاری — P5-D127.
			$unprefixed = array();

			foreach ( $glossaries as $g ) {

				if ( '' === $g['name'] ) {
					continue;
				}

				if ( ! preg_match( '/^(tp_|[a-z]{1,3}\d{0,2}_)/', $g['name'] ) ) {
					$unprefixed[] = '<code>' . esc_html( $g['name'] ) . '</code> (' . esc_html( $g['id'] ) . ')';
				}
			}

			topersia_diag_row(
				'بدون پیشوند استاندارد',
				$unprefixed ? 'warn' : 'ok',
				$unprefixed
					? implode( '، ', $unprefixed ) . '<br><em>واژه‌نامهٔ سراسری باید پیشوند <code>tp_</code> بگیرد و واژه‌نامهٔ تک‌موجودیتی پیشوند همان موجودیت (P5-D127).</em>'
					: 'همه پیشوند دارند'
			);
		}

		// واژه‌نامهٔ یتیم.
		$used = array();

		foreach ( $fields as $f ) {
			if ( '' !== $f['glossary'] ) {
				$used[ $f['glossary'] ] = true;
			}
		}

		$orphans = array();

		foreach ( $glossaries as $g ) {

			if ( ! isset( $used[ $g['id'] ] ) ) {
				$orphans[] = ( '' !== $g['name'] ? '<code>' . esc_html( $g['name'] ) . '</code> ' : '' ) . '(' . esc_html( $g['id'] ) . ')';
			}
		}

		topersia_diag_row(
			'بدون هیچ ارجاع',
			$orphans ? 'warn' : 'ok',
			$orphans ? implode( '، ', $orphans ) : 'هیچ'
		);

		// واژه‌نامهٔ وضعیت ردیف.
		$row_status = null;

		foreach ( $glossaries as $g ) {

			if ( $g['id'] === (string) TOPERSIA_GLOSSARY_ROW_STATUS ) {
				$row_status = $g;
				break;
			}
		}

		if ( ! $row_status ) {

			topersia_diag_row(
				'واژه‌نامهٔ وضعیت ردیف',
				'fail',
				'شناسهٔ <code>' . absint( TOPERSIA_GLOSSARY_ROW_STATUS ) . '</code> پیدا نشد. در زبانهٔ تنظیمات اصلاحش کن.'
			);

		} else {

			$vals = array();

			foreach ( $row_status['fields'] as $item ) {

				if ( is_array( $item ) && isset( $item['value'] ) ) {
					$vals[] = (string) $item['value'];
				}
			}

			if ( empty( $vals ) ) {

				topersia_diag_row(
					'واژه‌نامهٔ وضعیت ردیف',
					'warn',
					'شناسهٔ <code>' . absint( TOPERSIA_GLOSSARY_ROW_STATUS ) . '</code> وجود دارد ولی مقادیرش از ساختار دادهٔ JetEngine خوانده نشد.<br>' .
					'کلیدهای آیتم: <code>' . esc_html( implode( '، ', $row_status['keys'] ) ) . '</code> · ' .
					'<code>args</code>: <code>' . esc_html( implode( '، ', $row_status['probed']['args'] ) ) . '</code><br>' .
					'<em>هشدار دربارهٔ ابزار تشخیص است، نه داده. خودِ متاباکس‌ها مستقیم به شناسه ارجاع می‌دهند و مستقل از این بررسی کار می‌کنند.</em>'
				);

			} else {

				$has_both = in_array( 'active', $vals, true ) && in_array( 'not_applicable', $vals, true );
				$first_ok = 'active' === $vals[0];

				topersia_diag_row(
					'واژه‌نامهٔ وضعیت ردیف',
					$has_both && $first_ok ? 'ok' : 'warn',
					( '' !== $row_status['name'] ? '<code>' . esc_html( $row_status['name'] ) . '</code> — ' : '' ) .
					'مقادیر: <code>' . esc_html( implode( '، ', $vals ) ) . '</code>' .
					( $first_ok ? '' : '<br><em>مقدار اول باید active باشد، وگرنه هر ردیف تازه از ابتدا بازنشسته ساخته می‌شود.</em>' ) .
					( $has_both ? '' : '<br><em>هر دو مقدار active و not_applicable لازم‌اند.</em>' )
				);
			}
		}
	}

	echo '</tbody></table>';

	/* ═══ متاباکس‌ها و Repeaterها ═══ */
	echo '<h2>متاباکس‌ها و Repeaterها</h2><table class="widefat striped"><tbody>';

	$boxes = topersia_diag_meta_boxes();

	topersia_diag_row( 'تعداد متاباکس', 'info', number_format_i18n( count( $boxes ) ) . ' متاباکس' );

	// hide_field_names خاموش.
	$hidden_off = array();

	foreach ( $boxes as $box ) {

		$args = isset( $box['args'] ) ? $box['args'] : array();
		$args = is_string( $args ) ? json_decode( $args, true ) : $args;

		if ( ! is_array( $args ) ) {
			continue;
		}

		if ( empty( $args['hide_field_names'] ) ) {
			$hidden_off[] = ! empty( $args['name'] ) ? $args['name'] : '—';
		}
	}

	topersia_diag_row(
		'نمایش نام متاکلید',
		$hidden_off ? 'warn' : 'ok',
		$hidden_off
			? count( $hidden_off ) . ' متاباکس هنوز نام متاکلید را نشان می‌دهند: ' . esc_html( implode( '، ', array_slice( $hidden_off, 0, 8 ) ) ) . ( count( $hidden_off ) > 8 ? ' و بیشتر' : '' ) . '<br><em>در چیدمان RTL این خط با توضیح فیلد هم‌پوشانی می‌کند و هر دو ناخوانا می‌شوند.</em>'
			: 'روی همهٔ متاباکس‌ها پنهان است'
	);

	// Repeater بدون row_status.
	$reps_missing = array();

	foreach ( $fields as $f ) {

		if ( 'repeater' !== $f['type'] ) {
			continue;
		}

		$has = false;

		foreach ( $fields as $s ) {
			if ( $s['is_sub'] && $s['parent'] === $f['name'] && $s['box'] === $f['box']
				&& '_row_status' === substr( $s['name'], -11 )
			) {
				$has = true;
				break;
			}
		}

		if ( ! $has ) {
			$reps_missing[] = esc_html( $f['box'] ) . ' › <code>' . esc_html( $f['name'] ) . '</code>';
		}
	}

	topersia_diag_row(
		'Repeater بدون زیرفیلد وضعیت',
		$reps_missing ? 'fail' : 'ok',
		$reps_missing
			? implode( '<br>', $reps_missing ) . '<br><em>حذف ردیف از این Repeaterها ترجمهٔ همهٔ ردیف‌های بعدی را در هر زبان جابه‌جا می‌کند — خاموش و بدون خطا (P5-D121).</em>'
			: 'هر Repeater زیرفیلد وضعیت دارد'
	);

	/*
	 * متاکلید مشترک با چند واژه‌نامه.
	 *
	 * نسخهٔ ۴.۱.۰ این را «ناسازگار» می‌نامید و هشدار می‌داد. آن قضاوت غلط
	 * بود: بررسی اسناد CA-A و CA-C و CA-P نشان داد متاکلید مشترک با
	 * واژه‌نامهٔ اختصاصی هر موجودیت، الگوی عمدی و تصویب‌شدهٔ پروژه است
	 * (P5-D141). ۴۲ متاکلید از ۴۵ متاکلید مشترک همین وضع را دارند.
	 *
	 * ریسک واقعی جای دیگری است: اگر دو واژه‌نامه مقدار یکسانی داشته باشند،
	 * کوئری روی آن متاکلید نتیجهٔ مبهم می‌دهد و نگاشت Schema نمی‌تواند
	 * تشخیص دهد مقدار از کدام مجموعه آمده.
	 *
	 * پس این بخش دو چیز جدا گزارش می‌کند: وضعیت (اطلاعاتی) و تصادم (خطا).
	 */
	$sig = array();

	foreach ( $fields as $f ) {

		if ( '' === $f['glossary'] ) {
			continue;
		}

		$sig[ $f['name'] ][ $f['glossary'] ][] = $f['box'];
	}

	$multi = array();

	foreach ( $sig as $key => $glossaries ) {

		if ( count( $glossaries ) > 1 ) {
			$multi[ $key ] = array_keys( $glossaries );
		}
	}

	topersia_diag_row(
		'متاکلید مشترک با چند واژه‌نامه',
		'info',
		$multi
			? implode( '<br>', array_map(
				function ( $key, $ids ) {
					return '<code>' . esc_html( $key ) . '</code> — ' . count( $ids ) . ' واژه‌نامه';
				},
				array_keys( $multi ),
				$multi
			) ) . '<br><em>الگوی عمدی پروژه (P5-D141): هر موجودیت مجموعهٔ بستهٔ خودش را دارد.</em>'
			: 'هیچ'
	);

	/*
	 * تصادم مقدار — این ریسک واقعی است.
	 *
	 * شرط پایداری P5-D141: مقادیر همهٔ واژه‌نامه‌هایی که زیر یک متاکلید
	 * می‌نشینند باید سراسری یکتا بمانند. افزودن یک مقدار تکراری به یکی از
	 * مجموعه‌ها، کوئری را بی‌صدا مبهم می‌کند.
	 */
	$gloss_values = array();

	foreach ( topersia_diag_glossaries() as $g ) {

		$values = array();

		foreach ( $g['fields'] as $item ) {

			if ( is_array( $item ) && isset( $item['value'] ) ) {
				$values[] = (string) $item['value'];
			}
		}

		$gloss_values[ $g['id'] ] = array(
			'name'   => $g['name'],
			'values' => $values,
		);
	}

	$collisions = array();

	foreach ( $multi as $key => $ids ) {

		$owner = array();

		foreach ( $ids as $gid ) {

			if ( ! isset( $gloss_values[ $gid ] ) ) {
				continue;
			}

			$label = '' !== $gloss_values[ $gid ]['name'] ? $gloss_values[ $gid ]['name'] : $gid;

			foreach ( $gloss_values[ $gid ]['values'] as $value ) {

				// not_applicable عمداً در همهٔ مجموعه‌ها هست — P5-D109.
				if ( 'not_applicable' === $value ) {
					continue;
				}

				$owner[ $value ][] = $label;
			}
		}

		foreach ( $owner as $value => $owners ) {

			if ( count( $owners ) > 1 ) {
				$collisions[] = '<code>' . esc_html( $key ) . '</code> · مقدار <code>' . esc_html( $value ) . '</code> در ' . esc_html( implode( '، ', $owners ) );
			}
		}
	}

	topersia_diag_row(
		'تصادم مقدار میان واژه‌نامه‌های هم‌کلید',
		$collisions ? 'fail' : 'ok',
		$collisions
			? implode( '<br>', $collisions ) . '<br><em>شرط پایداری P5-D141 نقض شده: کوئری روی این متاکلید دیگر نمی‌تواند تشخیص دهد مقدار از کدام موجودیت آمده.</em>'
			: 'هیچ — هر مقدار فقط به یک مجموعه تعلق دارد'
	);

	echo '</tbody></table>';

	/* ═══ سلامت داده ═══ */
	echo '<h2>سلامت داده</h2><table class="widefat striped"><tbody>';

	global $wpdb;

	$entity_types = array();

	foreach ( get_post_types( array(), 'names' ) as $type ) {
		if ( topersia_is_entity( $type ) ) {
			$entity_types[] = $type;
		}
	}

	if ( empty( $entity_types ) ) {

		topersia_diag_row( 'موجودیت‌ها', 'warn', 'هیچ نوع پستی با پیشوند <code>tp_</code> ثبت نشده' );

	} else {

		$in = "'" . implode( "','", array_map( 'esc_sql', $entity_types ) ) . "'";

		/*
		 * چرا پیش‌نویس هم شمرده می‌شود: واردکنندهٔ بخش ۱۴ هزار رکورد
		 * جغرافیایی را به‌صورت پیش‌نویس می‌سازد. اگر بررسی‌های سلامت فقط
		 * منتشرشده‌ها را ببینند، آن هزار رکورد از دید ابزار تشخیص نامرئی
		 * می‌مانند — و مشکلاتشان تازه در لحظهٔ انتشار یک‌جا بیرون می‌زند.
		 */
		/*
		 * این یکی عمداً فقط publish می‌شمرد.
		 *
		 * نسخهٔ ۴.۶.۰ با یک جایگزینی سراسری همهٔ کوئری‌ها را به
		 * publish+draft تبدیل کرد تا پیش‌نویس‌های واردکننده دیده شوند —
		 * ولی همین کوئری را هم گرفت و برچسب «منتشرشده» عدد مجموع را نشان
		 * می‌داد. جایگزینی سراسری بدون بررسی تک‌تک موارد، همان حدس‌زدن است.
		 */
		$total = (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type IN ({$in}) AND post_status = 'publish'" );
		$draft = (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type IN ({$in}) AND post_status = 'draft'" );

		topersia_diag_row(
			'موجودیت',
			'info',
			number_format_i18n( $total ) . ' منتشرشده · ' . number_format_i18n( $draft ) . ' پیش‌نویس · در ' . number_format_i18n( count( $entity_types ) ) . ' نوع پست'
		);

		$no_uid = (int) $wpdb->get_var(
			"SELECT COUNT(*) FROM {$wpdb->posts} p
			 LEFT JOIN {$wpdb->postmeta} m ON m.post_id = p.ID AND m.meta_key = 'entity_uid'
			 WHERE p.post_type IN ({$in}) AND p.post_status IN ( 'publish', 'draft' )
			 AND ( m.meta_id IS NULL OR m.meta_value = '' )"
		);

		topersia_diag_row(
			'بدون entity_uid',
			$no_uid ? 'warn' : 'ok',
			$no_uid
				? number_format_i18n( $no_uid ) . ' موجودیت — تا وقتی اسلاگ لاتین نشده باشد ساخته نمی‌شود. یک بار ذخیرهٔ مجدد معمولاً حلش می‌کند.'
				: 'همه دارند'
		);

		$bad_slug = (int) $wpdb->get_var(
			"SELECT COUNT(*) FROM {$wpdb->posts}
			 WHERE post_type IN ({$in}) AND post_status IN ( 'publish', 'draft' )
			 AND ( post_name = '' OR post_name LIKE '%\%%' )"
		);

		topersia_diag_row(
			'اسلاگ غیرلاتین یا خالی',
			$bad_slug ? 'warn' : 'ok',
			$bad_slug
				? number_format_i18n( $bad_slug ) . ' موجودیت — فیلد <code>name_en</code> یا <code>official_name_en</code> آن‌ها هنوز پر نشده'
				: 'همه لاتین‌اند'
		);

		$no_thumb = (int) $wpdb->get_var(
			"SELECT COUNT(*) FROM {$wpdb->posts} p
			 INNER JOIN {$wpdb->postmeta} hero ON hero.post_id = p.ID AND hero.meta_key = 'hero_image' AND hero.meta_value != ''
			 LEFT JOIN {$wpdb->postmeta} th ON th.post_id = p.ID AND th.meta_key = '_thumbnail_id'
			 WHERE p.post_type IN ({$in}) AND p.post_status IN ( 'publish', 'draft' )
			 AND ( th.meta_id IS NULL OR th.meta_value != hero.meta_value )"
		);

		topersia_diag_row(
			'تصویر شاخص همگام‌نشده',
			$no_thumb ? 'warn' : 'ok',
			$no_thumb
				? number_format_i18n( $no_thumb ) . ' موجودیت — بدون تصویر شاخص، <code>og:image</code> ساخته نمی‌شود و هر اشتراک‌گذاری کارت بی‌تصویر می‌دهد. یک بار ذخیرهٔ مجدد کافی است.'
				: 'همه همگام‌اند'
		);

		/*
		 * توضیح متا — بر پایهٔ زنجیرهٔ مؤثر، نه یک فیلد.
		 *
		 * نسخهٔ ۴.۱.۲ فقط meta_description را می‌شمرد و «همه دارند» گزارش
		 * می‌داد، در حالی که خروجی زندهٔ یک صفحه هیچ توضیحی نداشت. یک فیلد
		 * خالی وقتی پشتیبان دارد اصلاً مشکل نیست؛ مشکل واقعی وقتی است که
		 * هر سه حلقهٔ زنجیره خالی باشند و صفحه بدون توضیح منتشر شود.
		 *
		 * پس به‌جای شمردن یک فیلد، همان منطقی بررسی می‌شود که بخش ۸ در
		 * زمان رندر اجرا می‌کند — و نمونه‌ها نام‌به‌نام فهرست می‌شوند تا
		 * قابل پیگیری باشند.
		 */
		$desc_sql = "FROM {$wpdb->posts} p
			 LEFT JOIN {$wpdb->postmeta} md ON md.post_id = p.ID AND md.meta_key = 'meta_description'
			 LEFT JOIN {$wpdb->postmeta} ss ON ss.post_id = p.ID AND ss.meta_key = 'short_summary'
			 LEFT JOIN {$wpdb->postmeta} ai ON ai.post_id = p.ID AND ai.meta_key = 'ai_summary'
			 WHERE p.post_type IN ({$in}) AND p.post_status IN ( 'publish', 'draft' )";

		/*
		 * پیش‌نویس از منتشرشده جدا می‌شود.
		 *
		 * پیش‌نویسِ بدون توضیح یک نقص نیست — کار ناتمام است. پس از ورود
		 * اسکلت جغرافیایی، هزار و پانصد پیش‌نویس بدون توضیح وجود دارد و
		 * علامت‌زدنشان به‌عنوان خطا، ردیف را برای همیشه قرمز نگه می‌دارد و
		 * هشدارِ واقعی را زیر نویز دفن می‌کند.
		 *
		 * آنچه واقعاً اهمیت دارد: صفحه‌ای که منتشر شده و توضیح ندارد.
		 */
		$blank_pub = $wpdb->get_results(
			"SELECT p.ID, p.post_title {$desc_sql}
			 AND p.post_status = 'publish'
			 AND TRIM( COALESCE( md.meta_value, '' ) ) = ''
			 AND TRIM( COALESCE( ss.meta_value, '' ) ) = ''
			 AND TRIM( COALESCE( ai.meta_value, '' ) ) = ''
			 ORDER BY p.ID LIMIT 25"
		);

		$blank_draft = (int) $wpdb->get_var(
			"SELECT COUNT(*) {$desc_sql}
			 AND p.post_status = 'draft'
			 AND TRIM( COALESCE( md.meta_value, '' ) ) = ''
			 AND TRIM( COALESCE( ss.meta_value, '' ) ) = ''
			 AND TRIM( COALESCE( ai.meta_value, '' ) ) = ''"
		);

		if ( $blank_pub ) {

			$names = array();

			foreach ( $blank_pub as $row ) {
				$names[] = esc_html( $row->post_title ) . ' <code>' . absint( $row->ID ) . '</code>';
			}

			topersia_diag_row(
				'منتشرشده بدون توضیح مؤثر',
				'fail',
				implode( '، ', $names ) . ( 25 === count( $blank_pub ) ? ' و احتمالاً بیشتر' : '' ) .
				'<br><em>هر سه حلقهٔ زنجیره خالی‌اند، پس این صفحات بدون تگ توضیح متا منتشر می‌شوند و گوگل خودش از متن صفحه تکه‌ای برمی‌دارد.</em>'
			);

		} else {

			topersia_diag_row( 'منتشرشده بدون توضیح مؤثر', 'ok', 'هر صفحهٔ منتشرشده دست‌کم یک حلقهٔ زنجیره را پر دارد' );
		}

		topersia_diag_row(
			'پیش‌نویس بدون توضیح',
			'info',
			$blank_draft
				? number_format_i18n( $blank_draft ) . ' پیش‌نویس هنوز توضیحی ندارند — کار ناتمام، نه نقص. پیش از انتشار باید پر شوند.'
				: 'هیچ'
		);

		$fallback = (int) $wpdb->get_var(
			"SELECT COUNT(*) {$desc_sql}
			 AND TRIM( COALESCE( md.meta_value, '' ) ) = ''
			 AND ( TRIM( COALESCE( ss.meta_value, '' ) ) != '' OR TRIM( COALESCE( ai.meta_value, '' ) ) != '' )"
		);

		topersia_diag_row(
			'متکی به پشتیبان',
			$fallback ? 'warn' : 'ok',
			$fallback
				? number_format_i18n( $fallback ) . ' موجودیت <code>meta_description</code> ندارند و از <code>short_summary</code> یا <code>ai_summary</code> استفاده می‌کنند — کار می‌کند، ولی توضیح اختصاصیِ نوشته‌شده برای SERP بهتر است'
				: 'همه توضیح اختصاصی دارند'
		);

		/*
		 * محافظ حذف ردیف — آیا اصلاً می‌تواند فعال شود؟
		 *
		 * محافظ فقط روی پست‌هایی کار می‌کند که ترجمه دارند. اگر هیچ
		 * موجودیتی ترجمه نداشته باشد، محافظ عملاً خاموش است — و این
		 * چیزی است که باید دیده شود، نه اینکه در آزمون کشف شود.
		 */
		$translated = 0;
		$sample_ids = get_posts(
			array(
				'post_type'   => $entity_types,
				'post_status' => array( 'publish', 'draft' ),
				'numberposts' => 200,
				'fields'      => 'ids',
			)
		);

		foreach ( (array) $sample_ids as $sid ) {

			if ( topersia_has_translations( $sid ) ) {
				$translated ++;
			}
		}

		$always = (bool) topersia_setting( 'guard_row_always' );

		topersia_diag_row(
			'محافظ حذف ردیف',
			topersia_setting( 'guard_row_delete' ) ? ( ( $translated || $always ) ? 'ok' : 'warn' ) : 'warn',
			! topersia_setting( 'guard_row_delete' )
				? '⚠️ در تنظیمات خاموش است'
				: (
					$always
						? 'روشن و <strong>سخت‌گیرانه</strong> — روی همهٔ پست‌ها، حتی بدون ترجمه'
						: number_format_i18n( $translated ) . ' موجودیت از ' . number_format_i18n( count( (array) $sample_ids ) ) . ' نمونه ترجمه دارند' .
						  ( $translated
							? '<br>محافظ روی همان‌ها فعال است.'
							: '<br><em>هیچ موجودیت نمونه‌ای ترجمه ندارد، پس محافظ عملاً کنار می‌کشد. این درست است — تا وقتی ترجمه نباشد حذف ردیف بی‌ضرر است. برای سخت‌گیری، گزینهٔ «محافظ ردیف حتی بدون ترجمه» را روشن کن.</em>' )
				)
		);

		/*
		 * زنجیرهٔ جغرافیایی — سنجهٔ مستقیم DATA-P9-001.
		 *
		 * تا وقتی شهرستان به استان و شهر به شهرستان وصل نشده باشد، زنجیرهٔ
		 * نیاکان دوعضوی می‌ماند و containedInPlace اصلاً منتشر نمی‌شود.
		 */
		$rel_pc = topersia_relation( TOPERSIA_REL_PROVINCE_COUNTY );
		$rel_cc = topersia_relation( TOPERSIA_REL_COUNTY_CITY );

		if ( $rel_pc && $rel_cc ) {

			$orphan_county = 0;
			$orphan_city   = 0;
			$seen_county   = 0;
			$seen_city     = 0;

			$args = array(
				'post_status' => array( 'publish', 'draft' ),
				'numberposts' => 800,
				'fields'      => 'ids',
			);

			foreach ( (array) get_posts( array_merge( $args, array( 'post_type' => 'tp_county' ) ) ) as $id ) {

				$seen_county ++;

				if ( empty( $rel_pc->get_parents( $id, 'ids' ) ) ) {
					$orphan_county ++;
				}
			}

			foreach ( (array) get_posts( array_merge( $args, array( 'post_type' => 'tp_city' ) ) ) as $id ) {

				$seen_city ++;

				if ( empty( $rel_cc->get_parents( $id, 'ids' ) ) ) {
					$orphan_city ++;
				}
			}

			topersia_diag_row(
				'زنجیرهٔ جغرافیایی',
				( $orphan_county || $orphan_city ) ? 'warn' : 'ok',
				number_format_i18n( $seen_county ) . ' شهرستان · ' . number_format_i18n( $seen_city ) . ' شهر بررسی شد<br>' .
				(
					( $orphan_county || $orphan_city )
						? number_format_i18n( $orphan_county ) . ' شهرستان و ' . number_format_i18n( $orphan_city ) . ' شهر <strong>بدون والد</strong>' .
						  '<br><em>تا وصل‌نشدن، زنجیرهٔ نیاکان دوعضوی می‌ماند و containedInPlace منتشر نمی‌شود — همان DATA-P9-001.</em>'
						: 'همه به والدشان وصل‌اند'
				)
			);
		}
	}

	echo '</tbody></table>';

}

/* ═══════════════════════════════════════════════════════════════════════
 *  بخش ۱۴ — واردکنندهٔ اسکلت جغرافیایی
 * ═══════════════════════════════════════════════════════════════════════
 * DATA-P9-001 را می‌بندد: زنجیرهٔ کشور ← استان ← شهرستان ← شهر.
 *
 * چرا ابزار اختصاصی و نه WXR وردپرس: WXR پست و متا را وارد می‌کند ولی
 * یال رابطهٔ JetEngine نمی‌سازد. و بدون یال، زنجیرهٔ نیاکان و
 * containedInPlace خالی می‌ماند — یعنی همان بدهی سر جایش است.
 *
 * سه خاصیت که این ابزار را ایمن می‌کند:
 *
 * ۱ — خودتکرارپذیر. هر رکورد با اسلاگش شناسایی می‌شود. اجرای دوباره،
 *     موجودها را رد می‌کند و فقط تازه‌ها را می‌سازد. اگر نیمه‌کاره قطع
 *     شد، دوباره اجرا کن.
 *
 * ۲ — دسته‌ای. هزار رکورد در یک درخواست تایم‌اوت می‌دهد. هر بار یک دسته
 *     پردازش می‌شود و صفحه خودش ادامه می‌دهد.
 *
 * ۳ — حالت آزمایشی. پیش از هر نوشتنی می‌شود دید چه چیزی ساخته خواهد شد.
 *
 * رکوردها به‌عنوان پیش‌نویس ساخته می‌شوند، نه منتشرشده. دلیل: هزار صفحهٔ
 * بدون متن که یک‌باره منتشر شوند، به گوگل سیگنال محتوای نازک می‌دهند —
 * دقیقاً برعکس هدف پروژه. انتشار پس از تولید محتوا انجام می‌شود.
 */
add_filter( 'topersia_admin_tabs', 'topersia_geo_admin_tab' );

function topersia_geo_admin_tab( $tabs ) {

	$tabs['geo'] = array(
		'label'    => 'اسکلت جغرافیایی',
		'callback' => 'topersia_geo_admin_render',
	);

	return $tabs;
}

/**
 * آدرس یک اجرای واردکننده — خام و بدون escape.
 *
 * چرا تابع جدا: wp_nonce_url خروجی‌اش را با esc_html برمی‌گرداند، یعنی &
 * تبدیل به &amp; می‌شود. اگر روی آن دوباره esc_url بزنی، مرورگر پارامترها
 * را با نام «amp;tab» می‌بیند و tab اصلاً وجود ندارد — پس پنل به زبانهٔ
 * پیش‌فرض برمی‌گردد.
 *
 * این دقیقاً همان چیزی بود که در نسخهٔ ۴.۵.۰ باعث می‌شد دکمهٔ آزمایشی به
 * صفحهٔ تنظیمات بپرد. نمونهٔ دیگری از خطر فرض‌کردن رفتار یک تابع بدون
 * خواندنش.
 *
 * اینجا آدرس خام ساخته می‌شود؛ escape در محل استفاده انجام می‌گیرد.
 */
function topersia_geo_url( $level, $offset = 0, $dry = false, $update = false ) {

	$args = array(
		'page'       => 'topersia',
		'tab'        => 'geo',
		'geo_level'  => $level,
		'geo_offset' => absint( $offset ),
		'_wpnonce'   => wp_create_nonce( 'topersia_geo' ),
	);

	if ( $dry ) {
		$args['geo_dry'] = 1;
	}

	if ( $update ) {
		$args['geo_update'] = 1;
	}

	return add_query_arg( $args, admin_url( 'admin.php' ) );
}

/** نگاشت سطح داده به نوع پست و رابطهٔ والد. */
function topersia_geo_levels() {

	return array(
		'country'   => array( 'post_type' => 'tp_country',  'parent_key' => null,              'relation' => 0 ),
		'provinces' => array( 'post_type' => 'tp_province', 'parent_key' => 'parent_country',  'relation' => 0 ),
		'counties'  => array( 'post_type' => 'tp_county',   'parent_key' => 'parent_province', 'relation' => TOPERSIA_REL_PROVINCE_COUNTY ),
		'cities'    => array( 'post_type' => 'tp_city',     'parent_key' => 'parent_county',   'relation' => TOPERSIA_REL_COUNTY_CITY ),
	);
}

/** پستی با این اسلاگ و نوع پیدا می‌کند. */
function topersia_geo_find( $post_type, $slug ) {

	$found = get_posts(
		array(
			'post_type'        => $post_type,
			'name'             => $slug,
			'post_status'      => array( 'publish', 'draft', 'pending' ),
			'numberposts'      => 1,
			'fields'           => 'ids',
			'suppress_filters' => true,
		)
	);

	return $found ? absint( $found[0] ) : 0;
}

/**
 * یک دسته را وارد می‌کند.
 *
 * @return array شمارش: created, skipped, linked, failed, done
 */
/**
 * متادیتای یک رکورد جغرافیایی را می‌نویسد.
 *
 * فقط فیلدهایی که واقعاً در متاباکس‌ها تعریف شده‌اند. کلیدهای ساختاری
 * فایل import — مثل parent_province و confidence — نوشته نمی‌شوند.
 *
 * entity_uid عمداً اینجا نیست: بخش ۳ هسته آن را می‌سازد و هرگز بازنویسی
 * نمی‌کند. نوشتنش از اینجا، پایداری @id را می‌شکست.
 */
function topersia_geo_write_meta( $post_id, $row ) {

	$map = array(
		'name_fa'                => 'name_fa',
		'name_en'                => 'name_en',
		'geo_coordinates'        => 'geo_coordinates',
		'population'             => 'population',
		'area_km2'               => 'area_km2',
		'external_reference_uri' => 'external_reference_uri',
		'iso_a2'                 => 'country_iso',
		'tel_prefix'             => 'tel_prefix',
	);

	foreach ( $map as $from => $to ) {

		if ( isset( $row[ $from ] ) && '' !== $row[ $from ] ) {
			update_post_meta( $post_id, $to, $row[ $from ] );
		}
	}
}

function topersia_geo_import_batch( $data, $level, $offset, $size, $dry, $update = false ) {

	$levels = topersia_geo_levels();
	$spec   = $levels[ $level ];
	$rows   = isset( $data[ $level ] ) ? array_slice( $data[ $level ], $offset, $size ) : array();
	$stat   = array( 'created' => 0, 'skipped' => 0, 'updated' => 0, 'renamed' => 0, 'linked' => 0, 'failed' => 0, 'log' => array() );

	foreach ( $rows as $row ) {

		if ( empty( $row['slug'] ) || empty( $row['name_fa'] ) ) {
			$stat['failed'] ++;
			continue;
		}

		$existing = topersia_geo_find( $spec['post_type'], $row['slug'] );

		if ( $existing ) {

			$post_id = $existing;

			/*
			 * حالت به‌روزرسانی.
			 *
			 * چرا لازم است: تقسیمات کشوری هر سال عوض می‌شود — شهرستان تازه
			 * تأسیس می‌شود، روستا شهر می‌شود، املا اصلاح می‌شود. بدون این،
			 * تنها راه اصلاح یک رکورد غلط، حذف دستی و ورود دوباره بود.
			 *
			 * اسلاگ و entity_uid دست‌نخورده می‌مانند. تغییر اسلاگ یعنی
			 * شکستن URL منتشرشده، و تغییر entity_uid یعنی شکستن @id در کل
			 * گراف — هر دو غیرقابل بازگشت.
			 */
			if ( $update && ! $dry ) {

				if ( ! empty( $row['name_fa'] ) && get_the_title( $post_id ) !== $row['name_fa'] ) {

					wp_update_post(
						array(
							'ID'         => $post_id,
							'post_title' => $row['name_fa'],
						)
					);

					$stat['renamed'] ++;
				}

				topersia_geo_write_meta( $post_id, $row );
				$stat['updated'] ++;

			} else {
				$stat['skipped'] ++;
			}

		} elseif ( $dry ) {

			$stat['created'] ++;
			$stat['log'][] = $row['slug'];
			continue;

		} else {

			$post_id = wp_insert_post(
				array(
					'post_type'   => $spec['post_type'],
					'post_title'  => $row['name_fa'],
					'post_name'   => $row['slug'],
					'post_status' => 'draft',
				),
				true
			);

			if ( is_wp_error( $post_id ) ) {
				$stat['failed'] ++;
				topersia_log( 'ساخت رکورد جغرافیایی شکست خورد', 'error', 'geo', array( 'slug' => $row['slug'], 'error' => $post_id->get_error_message() ) );
				continue;
			}

			$stat['created'] ++;

			topersia_geo_write_meta( $post_id, $row );
		}

		/* یال رابطه با والد */
		if ( ! $dry && $spec['relation'] && ! empty( $spec['parent_key'] ) && ! empty( $row[ $spec['parent_key'] ] ) ) {

			$parent_type = 'counties' === $level ? 'tp_province' : 'tp_county';
			$parent_id   = topersia_geo_find( $parent_type, $row[ $spec['parent_key'] ] );

			if ( $parent_id ) {

				$relation = topersia_relation( $spec['relation'] );

				if ( $relation ) {

					$current = $relation->get_parents( $post_id, 'ids' );
					$current = is_array( $current ) ? array_map( 'absint', $current ) : array();

					if ( ! in_array( $parent_id, $current, true ) ) {

						if ( topersia_relation_connect( $relation, $parent_id, $post_id ) ) {
							$stat['linked'] ++;
						}
					}
				}
			} else {
				topersia_log( 'والد پیدا نشد — یال ساخته نشد', 'warning', 'geo', array( 'slug' => $row['slug'], 'parent' => $row[ $spec['parent_key'] ] ) );
			}
		}
	}

	$total        = isset( $data[ $level ] ) ? count( $data[ $level ] ) : 0;
	$stat['done'] = ( $offset + $size ) >= $total;
	$stat['next'] = $offset + $size;
	$stat['total'] = $total;

	return $stat;
}

/** رندر زبانهٔ اسکلت جغرافیایی. */
function topersia_geo_admin_render() {

	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}

	$path = WP_CONTENT_DIR . '/uploads/topersia-geo-import.json';

	echo '<h2>واردکردن اسکلت جغرافیایی</h2>';
	echo '<p style="max-width:62em">این ابزار بدهی <code>DATA-P9-001</code> را می‌بندد: زنجیرهٔ کشور ← استان ← شهرستان ← شهر، با یال‌های رابطه. رکوردها به‌صورت <strong>پیش‌نویس</strong> ساخته می‌شوند؛ انتشار پس از تولید محتوا انجام می‌شود.</p>';

	if ( ! file_exists( $path ) ) {

		printf(
			'<div class="notice notice-warning inline"><p>فایل داده پیدا نشد. آن را با نام <code>topersia-geo-import.json</code> در پوشهٔ <code>%s</code> بگذار.</p></div>',
			esc_html( str_replace( ABSPATH, '', WP_CONTENT_DIR ) . '/uploads/' )
		);

		return;
	}

	/*
	 * پیام خطا باید بگوید چه چیزی غلط است، نه فقط اینکه چیزی غلط است.
	 *
	 * نسخهٔ قبل فقط می‌گفت «ساختارش معتبر نیست» — که برای عیب‌یابی بی‌فایده
	 * بود: فایل خالی است؟ JSON خراب است؟ کلیدها فرق دارند؟ حالا هر سه
	 * بررسی و گزارش می‌شوند.
	 */
	$raw = file_get_contents( $path );

	if ( false === $raw || '' === trim( (string) $raw ) ) {

		printf(
			'<div class="notice notice-error inline"><p>فایل پیدا شد ولی خوانده نشد یا خالی است. حجم: <code>%s</code> بایت. دسترسی خواندن فایل را بررسی کن.</p></div>',
			esc_html( number_format_i18n( (int) filesize( $path ) ) )
		);

		return;
	}

	$data = json_decode( $raw, true );

	if ( null === $data && JSON_ERROR_NONE !== json_last_error() ) {

		printf(
			'<div class="notice notice-error inline"><p>فایل JSON معتبر نیست: <code>%s</code><br>حجم: <code>%s</code> بایت · ۸۰ نویسهٔ اول: <code>%s</code></p></div>',
			esc_html( json_last_error_msg() ),
			esc_html( number_format_i18n( strlen( $raw ) ) ),
			esc_html( topersia_str_cut( $raw, 80 ) )
		);

		return;
	}

	if ( ! is_array( $data ) || empty( $data['country'] ) ) {

		printf(
			'<div class="notice notice-error inline"><p>JSON خوانده شد ولی کلید <code>country</code> ندارد.<br>کلیدهای موجود: <code>%s</code><br>انتظار: <code>country · provinces · counties · cities</code></p></div>',
			esc_html( is_array( $data ) ? implode( '، ', array_keys( $data ) ) : gettype( $data ) )
		);

		return;
	}

	/* وضعیت فعلی */
	echo '<table class="widefat striped" style="max-width:56em"><thead><tr><th>سطح</th><th>در فایل</th><th>در سایت</th></tr></thead><tbody>';

	foreach ( topersia_geo_levels() as $level => $spec ) {

		$in_file = isset( $data[ $level ] ) ? count( $data[ $level ] ) : 0;
		$in_site = (int) wp_count_posts( $spec['post_type'] )->draft + (int) wp_count_posts( $spec['post_type'] )->publish;

		printf(
			'<tr><td><strong>%s</strong> <code>%s</code></td><td>%s</td><td>%s</td></tr>',
			esc_html( $level ),
			esc_html( $spec['post_type'] ),
			esc_html( number_format_i18n( $in_file ) ),
			esc_html( number_format_i18n( $in_site ) )
		);
	}

	echo '</tbody></table>';

	if ( ! empty( $data['meta']['counts_note'] ) ) {
		echo '<p class="description">' . esc_html( $data['meta']['counts_note'] ) . '</p>';
	}

	/* اجرا */
	$level  = isset( $_GET['geo_level'] ) ? sanitize_key( $_GET['geo_level'] ) : '';
	$offset = isset( $_GET['geo_offset'] ) ? absint( $_GET['geo_offset'] ) : 0;
	$dry    = ! empty( $_GET['geo_dry'] );
	$update = ! empty( $_GET['geo_update'] );
	$levels = topersia_geo_levels();

	if ( $level && isset( $levels[ $level ] ) && check_admin_referer( 'topersia_geo' ) ) {

		/*
		 * حالت آزمایشی چیزی نمی‌نویسد، پس دسته‌بندی‌اش بی‌معناست و فقط
		 * باعث می‌شود صفحه ده بار پشت سر هم رفرش شود — که شبیه حلقهٔ
		 * بی‌پایان به نظر می‌رسد. یک‌جا انجام می‌شود.
		 */
		$batch = $dry ? 5000 : 50;
		$stat  = topersia_geo_import_batch( $data, $level, $offset, $batch, $dry, $update );

		printf(
			'<div class="notice notice-info"><p><strong>%s</strong> — %s تازه · %s %s · %s یال · %s ناموفق · %s از %s%s</p></div>',
			$dry ? 'آزمایشی — هیچ چیز نوشته نشد' : ( $update ? esc_html( $level ) . ' — به‌روزرسانی' : esc_html( $level ) ),
			esc_html( number_format_i18n( $stat['created'] ) ),
			esc_html( number_format_i18n( $update ? $stat['updated'] : $stat['skipped'] ) ),
			$update ? 'به‌روز شد' : 'موجود',
			esc_html( number_format_i18n( $stat['linked'] ) ),
			esc_html( number_format_i18n( $stat['failed'] ) ),
			esc_html( number_format_i18n( min( $stat['next'], $stat['total'] ) ) ),
			esc_html( number_format_i18n( $stat['total'] ) ),
			$stat['renamed'] ? ' · <strong>' . esc_html( number_format_i18n( $stat['renamed'] ) ) . ' عنوان اصلاح شد</strong>' : ''
		);

		if ( ! $stat['done'] ) {

			$next = topersia_geo_url( $level, $stat['next'], $dry, $update );
			$stop = add_query_arg( array( 'page' => 'topersia', 'tab' => 'geo' ), admin_url( 'admin.php' ) );

			printf(
				'<p><a href="%s" class="button button-primary">ادامهٔ دستهٔ بعدی</a> <a href="%s" class="button">توقف</a></p>',
				esc_url( $next ),
				esc_url( $stop )
			);

			/*
			 * تأخیر سه ثانیه، نه یک ثانیه: با تأخیر کوتاه، صفحه پیش از
			 * اینکه بشود خواندش می‌پرد و اگر خطایی رخ داده باشد دیده
			 * نمی‌شود. دکمهٔ توقف هم برای همین است.
			 */
			printf(
				'<script>window.topersiaGeoTimer=setTimeout(function(){location.href=%s;},3000);'
				. 'document.addEventListener("click",function(e){if(e.target.closest("a"))clearTimeout(window.topersiaGeoTimer);},true);</script>',
				wp_json_encode( $next )
			);

		} else {
			echo '<div class="notice notice-success"><p><strong>این سطح کامل شد.</strong></p></div>';
		}
	}

	/* ── رکوردهای یتیم ───────────────────────────────────────────────
	 *
	 * رکوردی که در سایت هست ولی در فایل نیست. منشأ معمولش تغییر فایل
	 * داده بین دو اجراست: نسخهٔ قبلی اسلاگ‌هایی ساخته که نسخهٔ تازه ندارد.
	 *
	 * چرا خودکار حذف نمی‌شوند: ممکن است رکورد دستی و عمدی باشد، یا محتوا
	 * داشته باشد. حذف خودکار در مقیاس هزار رکورد، غیرقابل بازگشت است.
	 * فهرست می‌شوند تا تصمیم با تو باشد.
	 */
	$orphans = array();

	foreach ( topersia_geo_levels() as $lv => $spec ) {

		$file_slugs = array();

		foreach ( (array) ( isset( $data[ $lv ] ) ? $data[ $lv ] : array() ) as $row ) {

			if ( ! empty( $row['slug'] ) ) {
				$file_slugs[ $row['slug'] ] = true;
			}
		}

		$site = get_posts(
			array(
				'post_type'   => $spec['post_type'],
				'post_status' => array( 'publish', 'draft', 'pending' ),
				'numberposts' => 2000,
				'fields'      => 'ids',
			)
		);

		foreach ( (array) $site as $id ) {

			$slug = get_post_field( 'post_name', $id );

			if ( $slug && ! isset( $file_slugs[ $slug ] ) ) {
				$orphans[ $lv ][] = array( 'id' => $id, 'slug' => $slug, 'title' => get_the_title( $id ) );
			}
		}
	}

	if ( $orphans ) {

		$total = 0;

		foreach ( $orphans as $list ) {
			$total += count( $list );
		}

		printf(
			'<h3>رکوردهای یتیم — %s</h3><p style="max-width:62em">این رکوردها در سایت هستند ولی در فایل داده نیستند. به‌روزرسانی هرگز لمسشان نمی‌کند و برای همیشه می‌مانند. اگر از اجرای نسخهٔ قدیمی‌تر فایل مانده‌اند، حذفشان بی‌خطر است؛ اگر دستی ساخته‌ای، نگهشان دار.</p>',
			esc_html( number_format_i18n( $total ) )
		);

		foreach ( $orphans as $lv => $list ) {

			printf( '<p><strong>%s</strong> — %s رکورد</p>', esc_html( $lv ), esc_html( number_format_i18n( count( $list ) ) ) );
			echo '<div style="max-height:16em;overflow:auto;border:1px solid #ccd0d4;padding:8px;margin-bottom:12px">';

			foreach ( $list as $o ) {
				printf(
					'<div><a href="%s" target="_blank" rel="noopener">%s</a> <code>%s</code> <span style="color:#888">#%d</span></div>',
					esc_url( get_edit_post_link( $o['id'] ) ),
					esc_html( $o['title'] ),
					esc_html( $o['slug'] ),
					absint( $o['id'] )
				);
			}

			echo '</div>';
		}
	}

	/* دکمه‌ها */
	echo '<h3>اجرا — به ترتیب</h3>';
	echo '<p style="max-width:62em">ترتیب اهمیت دارد: هر سطح به والدش نیاز دارد. پیش از هر سطح یک بار آزمایشی بزن.</p>';
	echo '<table class="widefat striped" style="max-width:56em"><tbody>';

	foreach ( $levels as $lv => $spec ) {

		printf(
			'<tr><td style="width:14em"><strong>%s</strong></td><td><a href="%s" class="button">آزمایشی</a> <a href="%s" class="button button-primary">اجرا</a> <a href="%s" class="button">به‌روزرسانی</a></td></tr>',
			esc_html( $lv ),
			esc_url( topersia_geo_url( $lv, 0, true ) ),
			esc_url( topersia_geo_url( $lv, 0, false ) ),
			esc_url( topersia_geo_url( $lv, 0, false, true ) )
		);
	}

	echo '</tbody></table>';
	echo '<p class="description">هر دسته ۵۰ رکورد است و صفحه پس از سه ثانیه خودکار ادامه می‌دهد — با دکمهٔ توقف.</p>';
	echo '<p class="description"><strong>اجرا</strong> رکوردهای تازه می‌سازد و موجودها را رد می‌کند. <strong>به‌روزرسانی</strong> نام و متای رکوردهای موجود را از فایل تازه می‌کند — برای وقتی که داده اصلاح شده یا تقسیمات کشوری عوض شده. اسلاگ و <code>entity_uid</code> در هر دو حالت دست‌نخورده می‌مانند، چون تغییرشان URL منتشرشده و <code>@id</code> گراف را می‌شکند.</p>';
}

/* ═══════════════════════════════════════════════════════════════════════
 *  زبانهٔ لاگ
 * ═══════════════════════════════════════════════════════════════════════
 * فیلتر بر سطح، کانال و جست‌وجوی متن. و مهم‌تر: فیلتر بر شناسهٔ درخواست.
 *
 * چرا شناسهٔ درخواست مهم‌ترین است: یک خطای واقعی معمولاً چند رویداد
 * می‌سازد — هشدار، بعد خطا، بعد مرگبار. در سایتی با چند ویرایشگر هم‌زمان
 * این سطرها در هم می‌ریزند. با کلیک روی شناسه، کل داستان یک درخواست از
 * اول تا آخر جدا می‌شود.
 */
add_filter( 'topersia_admin_tabs', 'topersia_log_admin_tab', 5 );

function topersia_log_admin_tab( $tabs ) {

	$tabs['log'] = array(
		'label'    => 'لاگ',
		'callback' => 'topersia_log_admin_render',
	);

	return $tabs;
}

/** رنگ هر سطح. */
function topersia_log_colors() {

	return array(
		'debug'    => array( '#646970', 'اشکال‌زدایی' ),
		'info'     => array( '#2271b1', 'اطلاعات' ),
		'notice'   => array( '#3582c4', 'نکته' ),
		'warning'  => array( '#dba617', 'هشدار' ),
		'error'    => array( '#d63638', 'خطا' ),
		'critical' => array( '#8b0000', 'مرگبار' ),
	);
}

function topersia_log_admin_render() {

	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}

	global $wpdb;

	$table = topersia_log_table();

	if ( get_option( 'topersia_log_schema' ) !== TOPERSIA_LOG_SCHEMA ) {
		echo '<div class="notice notice-warning inline"><p>جدول لاگ هنوز ساخته نشده. صفحه را یک بار تازه کن.</p></div>';
		return;
	}

	/* اقدام‌ها */
	if ( ! empty( $_GET['log_action'] ) && check_admin_referer( 'topersia_log' ) ) {

		if ( 'wipe' === $_GET['log_action'] ) {
			// phpcs:ignore WordPress.DB.PreparedSQL
			$wpdb->query( "TRUNCATE TABLE {$table}" );
			echo '<div class="notice notice-success"><p>لاگ پاک شد.</p></div>';
		}

		if ( 'prune' === $_GET['log_action'] ) {
			topersia_log_prune();
			echo '<div class="notice notice-success"><p>هرس انجام شد.</p></div>';
		}

		if ( 'test' === $_GET['log_action'] ) {
			topersia_log( 'رویداد آزمایشی از پنل', 'warning', 'log', array( 'by' => get_current_user_id() ) );
			echo '<div class="notice notice-info"><p>یک رویداد آزمایشی ثبت شد — پس از تازه‌کردن صفحه پایین می‌آید.</p></div>';
		}
	}

	/* فیلترها */
	$f_level   = isset( $_GET['log_level_f'] ) ? sanitize_key( $_GET['log_level_f'] ) : '';
	$f_channel = isset( $_GET['log_channel'] ) ? sanitize_key( $_GET['log_channel'] ) : '';
	$f_request = isset( $_GET['log_request'] ) ? sanitize_key( $_GET['log_request'] ) : '';
	$f_search  = isset( $_GET['log_search'] ) ? sanitize_text_field( wp_unslash( $_GET['log_search'] ) ) : '';
	$paged     = isset( $_GET['log_paged'] ) ? max( 1, absint( $_GET['log_paged'] ) ) : 1;
	$per       = 60;

	$where = array( '1=1' );
	$args  = array();

	if ( $f_level ) {
		$where[] = 'level = %s';
		$args[]  = $f_level;
	}

	if ( $f_channel ) {
		$where[] = 'channel = %s';
		$args[]  = $f_channel;
	}

	if ( $f_request ) {
		$where[] = 'request_id = %s';
		$args[]  = $f_request;
	}

	if ( $f_search ) {
		$where[] = '( message LIKE %s OR context LIKE %s OR source LIKE %s )';
		$like    = '%' . $wpdb->esc_like( $f_search ) . '%';
		$args[]  = $like;
		$args[]  = $like;
		$args[]  = $like;
	}

	$clause = implode( ' AND ', $where );

	// phpcs:ignore WordPress.DB.PreparedSQL
	$total = (int) ( $args
		? $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$table} WHERE {$clause}", $args ) )
		: $wpdb->get_var( "SELECT COUNT(*) FROM {$table}" ) );

	$q_args   = $args;
	$q_args[] = $per;
	$q_args[] = ( $paged - 1 ) * $per;

	// phpcs:ignore WordPress.DB.PreparedSQL
	$rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$table} WHERE {$clause} ORDER BY id DESC LIMIT %d OFFSET %d", $q_args ) );

	/* آمار */
	// phpcs:ignore WordPress.DB.PreparedSQL
	$by_level = $wpdb->get_results( "SELECT level, COUNT(*) c FROM {$table} GROUP BY level", OBJECT_K );
	// phpcs:ignore WordPress.DB.PreparedSQL
	$channels = $wpdb->get_col( "SELECT DISTINCT channel FROM {$table} ORDER BY channel" );
	// phpcs:ignore WordPress.DB.PreparedSQL
	$oldest = $wpdb->get_var( "SELECT MIN(logged_at) FROM {$table}" );

	$colors = topersia_log_colors();
	$base   = add_query_arg( array( 'page' => 'topersia', 'tab' => 'log' ), admin_url( 'admin.php' ) );

	echo '<h2>لاگ رویدادها</h2>';

	if ( ! topersia_setting( 'log_enabled' ) ) {
		echo '<div class="notice notice-warning inline"><p>ثبت رویداد در تنظیمات خاموش است — چیزی تازه ثبت نمی‌شود.</p></div>';
	}

	printf(
		'<p style="max-width:62em">%s رویداد · قدیمی‌ترین: <code>%s</code> · آستانهٔ فعلی: <strong>%s</strong> · نگه‌داری %s روز، سقف %s سطر</p>',
		esc_html( number_format_i18n( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$table}" ) ) ),
		esc_html( $oldest ? $oldest : '—' ),
		esc_html( isset( $colors[ topersia_setting( 'log_level' ) ] ) ? $colors[ topersia_setting( 'log_level' ) ][1] : '—' ),
		esc_html( number_format_i18n( absint( topersia_setting( 'log_retain_days' ) ) ) ),
		esc_html( number_format_i18n( absint( topersia_setting( 'log_max_rows' ) ) ) )
	);

	/* شمارش بر سطح */
	echo '<p>';

	foreach ( $colors as $lv => $meta ) {

		$count = isset( $by_level[ $lv ] ) ? (int) $by_level[ $lv ]->c : 0;

		printf(
			'<a href="%s" class="button %s" style="margin-left:6px">%s <span style="color:%s;font-weight:700">%s</span></a>',
			esc_url( add_query_arg( 'log_level_f', $lv, $base ) ),
			$f_level === $lv ? 'button-primary' : '',
			esc_html( $meta[1] ),
			esc_attr( $meta[0] ),
			esc_html( number_format_i18n( $count ) )
		);
	}

	printf( '<a href="%s" class="button %s">همه</a>', esc_url( $base ), $f_level ? '' : 'button-primary' );
	echo '</p>';

	/* فرم فیلتر */
	echo '<form method="get" style="margin:12px 0">';
	echo '<input type="hidden" name="page" value="topersia" /><input type="hidden" name="tab" value="log" />';

	echo '<select name="log_channel"><option value="">همهٔ کانال‌ها</option>';

	foreach ( (array) $channels as $ch ) {
		printf( '<option value="%s" %s>%s</option>', esc_attr( $ch ), selected( $f_channel, $ch, false ), esc_html( $ch ) );
	}

	echo '</select> ';

	printf( '<input type="search" name="log_search" value="%s" placeholder="جست‌وجو در متن، بافت و منبع" style="width:24em" /> ', esc_attr( $f_search ) );
	submit_button( 'فیلتر', 'secondary', '', false );
	echo '</form>';

	/* اقدام‌ها */
	$act = function ( $a ) use ( $base ) {
		return add_query_arg( array( 'log_action' => $a, '_wpnonce' => wp_create_nonce( 'topersia_log' ) ), $base );
	};

	$export = add_query_arg(
		array(
			'action'   => 'topersia_log_export',
			'level'    => $f_level,
			'channel'  => $f_channel,
			'request'  => $f_request,
			'search'   => $f_search,
			'_wpnonce' => wp_create_nonce( 'topersia_log_export' ),
		),
		admin_url( 'admin-post.php' )
	);

	printf(
		'<p><a href="%s" class="button button-primary">دریافت خروجی متنی</a> <a href="%s" class="button">ثبت رویداد آزمایشی</a> <a href="%s" class="button">هرس بر پایهٔ تنظیمات</a> <a href="%s" class="button" onclick="return confirm(\'کل لاگ پاک شود؟\')">پاک‌کردن همه</a></p>',
		esc_url( $export ),
		esc_url( $act( 'test' ) ),
		esc_url( $act( 'prune' ) ),
		esc_url( $act( 'wipe' ) )
	);

	echo '<p class="description" style="max-width:62em">خروجی متنی همین فیلترهای بالا را اعمال می‌کند و رویدادها را بر پایهٔ شناسهٔ درخواست گروه‌بندی می‌کند، با یک خلاصهٔ آماری در ابتدا.</p>';

	if ( $f_request ) {
		printf(
			'<div class="notice notice-info inline"><p>فقط درخواست <code>%s</code> — <a href="%s">نمایش همه</a></p></div>',
			esc_html( $f_request ),
			esc_url( $base )
		);
	}

	if ( ! $rows ) {
		echo '<p>هیچ رویدادی با این فیلتر نیست.</p>';
		return;
	}

	/* جدول */
	echo '<table class="widefat striped"><thead><tr>';
	echo '<th style="width:12em">زمان</th><th style="width:6em">سطح</th><th style="width:7em">کانال</th><th>پیام</th><th style="width:9em">منبع</th><th style="width:7em">درخواست</th>';
	echo '</tr></thead><tbody>';

	foreach ( $rows as $r ) {

		$c   = isset( $colors[ $r->level ] ) ? $colors[ $r->level ] : array( '#646970', $r->level );
		$ctx = $r->context ? json_decode( $r->context, true ) : array();

		echo '<tr>';
		printf( '<td dir="ltr" style="text-align:left"><code>%s</code></td>', esc_html( $r->logged_at ) );
		printf( '<td><span style="color:%s;font-weight:700">%s</span></td>', esc_attr( $c[0] ), esc_html( $c[1] ) );
		printf( '<td><code>%s</code></td>', esc_html( $r->channel ) );

		echo '<td>' . esc_html( $r->message );

		if ( $ctx ) {
			echo '<br><code style="direction:ltr;display:inline-block;font-size:11px;color:#666">' . esc_html( wp_json_encode( $ctx, JSON_UNESCAPED_UNICODE ) ) . '</code>';
		}

		if ( $r->url ) {
			echo '<br><span style="font-size:11px;color:#888;direction:ltr;display:inline-block">' . esc_html( $r->url ) . '</span>';
		}

		echo '</td>';
		printf( '<td dir="ltr" style="text-align:left;font-size:11px">%s</td>', esc_html( $r->source ) );
		printf(
			'<td><a href="%s"><code>%s</code></a>%s</td>',
			esc_url( add_query_arg( 'log_request', $r->request_id, $base ) ),
			esc_html( substr( $r->request_id, 0, 6 ) ),
			$r->user_id ? '<br><span style="font-size:11px;color:#888">#' . absint( $r->user_id ) . '</span>' : ''
		);
		echo '</tr>';
	}

	echo '</tbody></table>';

	/* صفحه‌بندی */
	$pages = (int) ceil( $total / $per );

	if ( $pages > 1 ) {

		echo '<p style="margin-top:12px">';

		for ( $i = 1; $i <= min( $pages, 20 ); $i ++ ) {
			printf(
				'<a href="%s" class="button %s" style="margin-left:4px">%s</a>',
				esc_url( add_query_arg( 'log_paged', $i, $base ) ),
				$i === $paged ? 'button-primary' : '',
				esc_html( number_format_i18n( $i ) )
			);
		}

		echo '</p>';
	}

	echo '<p class="description" style="max-width:62em">روی شناسهٔ درخواست کلیک کن تا همهٔ رویدادهای همان بارگذاری صفحه را با هم ببینی. وقتی چند ویرایشگر هم‌زمان کار می‌کنند، این تنها راه جدا کردن داستان یک خطا از بقیه است.</p>';
}

/** زبانهٔ راهنما. */
function topersia_admin_tab_help() {

	echo '<div style="max-width:62em">';

	echo '<h2>کدام کار در کجا انجام می‌شود</h2>';
	echo '<table class="widefat striped"><thead><tr><th style="width:26em">کار</th><th>محل</th></tr></thead><tbody>';

	$rows = array(
		'تغییر شناسهٔ رابطه پس از بازسازی'         => 'همین صفحه › تنظیمات',
		'روشن‌کردن استخراج خودکار استان'           => 'همین صفحه › تنظیمات — اول زنجیرهٔ جغرافیایی را کامل کن',
		'خاموش‌کردن جاروی خروجی در شرایط اضطراری'  => 'همین صفحه › تنظیمات',
		'تغییر مسیرهای ماسک /geo'                  => 'همین صفحه › تنظیمات <strong>+</strong> <code>.htaccess</code> <strong>+</strong> <code>wp-config.php</code> — هر سه باید هم‌خوان باشند',
		'افزودن موجودیت تازه به نقشهٔ شِما'         => 'فایل <code>topersia-schema.php</code> › بخش ۲',
		'تغییر منطق اسلاگ یا شناسهٔ یکتا'           => 'فایل <code>topersia-core.php</code> › بخش ۲ و ۳',
		'افزودن فیلد به متاباکس'                   => 'JetEngine › Meta Boxes — ترجیحاً با فایل import، نه دستی',
		'ساخت واژه‌نامهٔ تازه'                      => 'JetEngine › Glossaries — شناسه را هرگز پیش‌بینی نکن، از فهرست بخوان',
		'قفل‌کردن یک تنظیم در برابر تغییر از پنل'   => '<code>define</code> در <code>wp-config.php</code>',
	);

	foreach ( $rows as $task => $where ) {
		printf( '<tr><td>%s</td><td>%s</td></tr>', esc_html( $task ), wp_kses_post( $where ) );
	}

	echo '</tbody></table>';

	echo '<h2>ترتیب تقدم پیکربندی</h2>';
	echo '<ol>';
	echo '<li><code>define</code> در <code>wp-config.php</code> — قفل سخت. پنل نمی‌تواند تغییرش دهد و فیلد مربوطه با نشان 🔒 غیرفعال می‌شود.</li>';
	echo '<li>تنظیم در زبانهٔ تنظیمات — راه معمول.</li>';
	echo '<li>پیش‌فرض داخل فایل افزونه.</li>';
	echo '</ol>';
	echo '<p>در شرایطی که یک فلگ سایت را شکسته و پیشخوان در دسترس نیست، همیشه باید راهی باشد که از بیرون پنل قفلش کنی. <code>wp-config.php</code> آن راه است.</p>';

	echo '<h2>چرا ویرایشگر کد در این پنل نیست</h2>';
	echo '<p>یک خطای نحوی در ویرایشگر زنده یعنی صفحهٔ سفید روی کل سایت، و تنها راه نجاتش دسترسی مستقیم به فایل است. پس ویرایشگر پیشخوان وابستگی به سرور را حذف نمی‌کند — فقط یک راه تازه برای ساختن آن اضطرار اضافه می‌کند.</p>';
	echo '<p>افزون بر آن، بخش ۱۲ هسته کل فلسفه‌اش کاهش سطح حمله است و ویرایشگر کد دقیقاً برعکس آن است. و حاکمیت این پروژه بر «هر چیزی یک فایل نسخه‌دار و بازتولیدپذیر است» بنا شده؛ ویرایش مستقیم در دیتابیس آن را نابود می‌کند.</p>';
	echo '<p>آنچه واقعاً باعث رفتن به سرور می‌شد <strong>پیکربندی</strong> بود، نه منطق — و آن کامل به زبانهٔ تنظیمات منتقل شده است.</p>';

	echo '<h2>دو افزونه، یک وابستگی یک‌طرفه</h2>';
	echo '<table class="widefat striped"><thead><tr><th style="width:16em">افزونه</th><th>مسئولیت</th></tr></thead><tbody>';
	echo '<tr><td><code>topersia-core</code></td><td>ساختن داده: اسلاگ، شناسهٔ یکتا، یال‌های مشتق‌شده، ترتیب توقف‌ها، عنوان و توضیح متا، ماسک مسیر، و همین پنل.</td></tr>';
	echo '<tr><td><code>topersia-schema</code></td><td>خواندن همان داده و انتشارش به‌صورت JSON-LD. هرگز چیزی نمی‌نویسد.</td></tr>';
	echo '</tbody></table>';
	echo '<p>هسته هیچ وابستگی به افزونهٔ شِما ندارد. افزونهٔ شِما بدون هسته خودش را خاموش نگه می‌دارد و در پیشخوان هشدار می‌دهد.</p>';

	echo '<h2>پیش از هر تغییر ساختاری</h2>';
	echo '<p>بکاپ Duplicator بگیر و روی سیستم خودت دانلود کن. تغییر شناسهٔ رابطه یا مسیر ماسک، اثرش فوری و سراسری است.</p>';

	echo '</div>';
}